  let left = r.right - pw;
  if (left < 8) left = r.left;
  left = Math.max(8, Math.min(left, vw - pw - 8));
  let top = r.bottom + 4;
  if (top + ph > vh - 8) top = r.top - ph - 4;   // flip above if it overflows
