// ── Connect to existing tmux session ──
async function openConnect() {
  const el = document.getElementById('connect-list');
  el.innerHTML = '<div class="connect-empty">Loading...</div>';
  document.getElementById('connect-overlay').classList.add('active');
  try {
    const r = await fetch(API + '/api/tmux-sessions');
    const items = await r.json();
    if (!items.length) {
      el.innerHTML = '<div class="connect-empty">No unregistered tmux sessions found.</div>';
      return;
    }
    el.innerHTML = items.map(s =>
      `<div class="connect-item" onclick="doConnect('${esc(s.tmux_name)}')">
        <div class="connect-item-info">
          <div class="connect-item-name">${esc(s.tmux_name)}</div>
          ${s.dir ? `<div class="connect-item-dir">${esc(s.dir)}</div>` : ''}
        </div>
      </div>`
    ).join('');
  } catch(e) {
    el.innerHTML = '<div class="connect-empty">Failed to load workers.</div>';
  }
}
function closeConnect() {
  document.getElementById('connect-overlay').classList.remove('active');
}
async function doConnect(tmuxName) {
  closeConnect();
  await apiCall(API + '/api/sessions/connect', {
    method: 'POST', headers: {'Content-Type':'application/json'},
    body: JSON.stringify({ tmux_name: tmuxName })
  });
  await fetchSessions();
}

// ── Connect iTerm2 pane ──
let _iterm2SelectedPaneId = null;

async function openConnectIterm2() {
  _iterm2SelectedPaneId = null;
  document.getElementById('iterm2-session-name').value = '';
  document.getElementById('iterm2-connect-btn').disabled = true;
  document.getElementById('iterm2-connect-overlay').classList.add('active');
  const list = document.getElementById('iterm2-pane-list');
  list.innerHTML = '<div style="color:var(--dim);font-size:0.85rem;text-align:center;padding:20px;">Loading iTerm2 panes…</div>';
  try {
    const r = await fetch(API + '/api/iterm2/sessions');
    const d = await r.json();
    const panes = d.panes || [];
    if (!panes.length) {
      // "Make sure iTerm2 is running" was this arm's ONLY message, and it was
      // wrong for every cause that isn't that: a missing route (this endpoint
      // 404'd until AMUX-2871) and, on this machine, osascript blocking on a
      // macOS Automation consent that never gets answered from a launchd
      // process. The server now says which it was — show it rather than
      // re-guessing at the user's machine.
      list.innerHTML = d.error
        ? `<div style="color:var(--red);font-size:0.85rem;text-align:center;padding:20px;">Could not list iTerm2 panes.<br><span style="color:var(--dim);font-size:0.78rem;">${esc(d.error)}</span><br><span style="color:var(--dim);font-size:0.78rem;">If iTerm2 is running, grant Automation access to amux in System Settings → Privacy &amp; Security.</span></div>`
        : '<div style="color:var(--dim);font-size:0.85rem;text-align:center;padding:20px;">No open iTerm2 panes found.<br>Make sure iTerm2 is running.</div>';
      return;
    }
    list.innerHTML = panes.map(p => `
      <div class="connect-item iterm2-pane-item" data-id="${esc(p.id)}" data-name="${esc(p.name)}"
           onclick="_selectIterm2Pane(this, '${esc(p.id)}', '${esc(p.name)}')"
           style="cursor:pointer;padding:10px 12px;border:1px solid var(--border);border-radius:6px;transition:border-color 0.15s;"
           onmouseenter="this.style.borderColor='var(--accent)'" onmouseleave="if(!this.classList.contains('selected'))this.style.borderColor='var(--border)'">
        <div style="font-weight:500;font-size:0.88rem;">${esc(p.name)}</div>
        <div style="font-size:0.75rem;color:var(--dim);margin-top:2px;">${esc(p.tty)} &nbsp;·&nbsp; window ${p.window}, tab ${p.tab}</div>
      </div>`).join('');
  } catch(e) {
    list.innerHTML = '<div style="color:var(--red);font-size:0.85rem;text-align:center;padding:20px;">Failed to reach iTerm2.<br>Make sure iTerm2 is running.</div>';
  }
}

function _selectIterm2Pane(el, id, name) {
  document.querySelectorAll('.iterm2-pane-item').forEach(e => {
    e.classList.remove('selected');
    e.style.borderColor = 'var(--border)';
    e.style.background = '';
  });
  el.classList.add('selected');
  el.style.borderColor = 'var(--accent)';
  el.style.background = 'rgba(88,166,255,0.06)';
  _iterm2SelectedPaneId = id;
  const inp = document.getElementById('iterm2-session-name');
  if (!inp.value) {
    // Auto-fill session name from pane title, sanitized
    inp.value = name.replace(/[^a-zA-Z0-9_-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 40) || 'iterm2';
  }
  document.getElementById('iterm2-connect-btn').disabled = false;
}

function closeConnectIterm2() {
  document.getElementById('iterm2-connect-overlay').classList.remove('active');
  _iterm2SelectedPaneId = null;
}

async function connectIterm2Pane() {
  if (!_iterm2SelectedPaneId) return;
  const name = document.getElementById('iterm2-session-name').value.trim();
  if (!name) { showToast('Enter a worker name'); return; }
  const btn = document.getElementById('iterm2-connect-btn');
  btn.disabled = true;
  btn.textContent = 'Connecting…';
  try {
    const r = await fetch(API + '/api/sessions', {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ name, provider: 'iterm2', iterm2_session_id: _iterm2SelectedPaneId })
    });
    const d = await r.json();
    if (!r.ok) { showToast('Error: ' + (d.error || r.status)); btn.disabled = false; btn.textContent = 'Connect'; return; }
    closeConnectIterm2();
    await fetchSessions();
    showToast('Connected: ' + name);
    setTimeout(() => openPeek(name), 300);
  } catch(e) {
    showToast('Error: ' + e.message);
    btn.disabled = false;
    btn.textContent = 'Connect';
  }
}

// ── Create session ──
let _createBranchEdited = false;  // track if user manually changed branch name
let _createDirIsGit = false;     // track if current dir is a git repo

let _createProvider = 'claude';
function _selectProvider(p) {
  _createProvider = p;
  document.getElementById('create-provider-claude').classList.toggle('selected', p === 'claude');
  document.getElementById('create-provider-codex').classList.toggle('selected', p === 'codex');
  document.getElementById('create-provider-gemini').classList.toggle('selected', p === 'gemini');
  const _ollamaBtn = document.getElementById('create-provider-ollama');
  if (_ollamaBtn) _ollamaBtn.classList.toggle('selected', p === 'ollama');
  // Hide branch/template/session-name options for non-Claude providers since they use different mechanics
  const isClaude = p === 'claude';
  document.getElementById('create-branch-enabled').closest('.field-group').style.display = isClaude ? '' : 'none';
  document.getElementById('create-worktree-field').style.display = isClaude && _createDirIsGit ? '' : 'none';
  document.getElementById('create-template-field').style.display = isClaude ? '' : 'none';
  // Ollama runs `codex --oss --local-provider ollama --model <model>` — the ONLY
  // provider that needs a model chosen at create time (the others default), so
  // surface the installed-model picker here rather than making the user create
  // then edit. Missing this option was why an ollama worker could not be made
  // from the create modal at all (AMUX-3182).
  const _omField = document.getElementById('create-ollama-model-field');
  if (_omField) {
    _omField.style.display = p === 'ollama' ? '' : 'none';
    if (p === 'ollama') _loadOllamaModelsForCreate();
  }
}
// Populate the create modal's local-model picker from the same endpoint the
// edit-provider menu uses. Re-fetched on each select so a freshly `ollama pull`ed
// model appears without a page reload; prefers a qwen build (the box default).
function _loadOllamaModelsForCreate() {
  const sel = document.getElementById('create-ollama-model');
  if (!sel) return;
  sel.innerHTML = '<option value="">Loading local models…</option>';
  fetch(API + '/api/ollama/models', { headers: _authHeaders() })
    .then(r => r.json())
    .then(d => {
      const mlist = d.models || [];
      sel.innerHTML = '';
      if (!mlist.length) {
        const o = document.createElement('option');
        o.value = ''; o.textContent = 'No local models — run: ollama pull qwen3.8:27b';
        sel.appendChild(o);
        return;
      }
      mlist.forEach(name => { const o = document.createElement('option'); o.value = name; o.textContent = name; sel.appendChild(o); });
      const qwen = mlist.find(m => m.toLowerCase().includes('qwen'));
      sel.value = qwen || mlist[0];
    })
    .catch(() => { sel.innerHTML = '<option value="">Could not reach Ollama</option>'; });
}
function openCreate() {
  _createProvider = 'claude';
  document.getElementById('create-provider-claude').classList.add('selected');
  document.getElementById('create-provider-codex').classList.remove('selected');
  document.getElementById('create-provider-gemini').classList.remove('selected');
  const _ollamaBtn0 = document.getElementById('create-provider-ollama');
  if (_ollamaBtn0) _ollamaBtn0.classList.remove('selected');
  const _omField0 = document.getElementById('create-ollama-model-field');
  if (_omField0) _omField0.style.display = 'none';
  document.getElementById('create-branch-enabled').closest('.field-group').style.display = '';
  document.getElementById('create-template-field').style.display = '';
  document.getElementById('create-name').value = '';
  document.getElementById('create-dir').value = (_filesCwd && _filesCwd !== '/') ? _filesCwd : (window._cloudEmail ? '/root' : '');
  document.getElementById('create-prompt').value = '';
  document.getElementById('create-branch').value = '';
  document.getElementById('create-branch-enabled').checked = false;
  document.getElementById('create-branch-wrap').style.display = 'none';
  document.getElementById('create-branch-suggestions').style.display = 'none';
  document.getElementById('create-branch-suggestions').innerHTML = '';
  document.getElementById('create-branch-existing').style.display = 'none';
  document.getElementById('create-branch-existing').innerHTML = '';
  _branchesLoaded = '';
  document.getElementById('ac-list').innerHTML = '';
  document.getElementById('ac-list').classList.remove('open');
  _createBranchEdited = false;
  _createDirIsGit = false;
  // Reset worktree
  document.getElementById('create-worktree-enabled').checked = false;
  document.getElementById('create-worktree-field').style.display = 'none';
  document.getElementById('create-worktree-info').style.display = 'none';
  // Reset template state — section collapsed by default
  _selectedTemplate = null;
  document.getElementById('tmpl-section-body').style.display = 'none';
  document.getElementById('tmpl-section-chev').style.transform = '';
  document.getElementById('tmpl-selected-badge').style.display = 'none';
  document.getElementById('tmpl-selected-wrap').style.display = 'none';
  document.getElementById('create-overlay').classList.add('active');
  // Check git for default dir
  const defaultDir = document.getElementById('create-dir').value;
  if (defaultDir) _checkDirGit(defaultDir);
  setTimeout(() => document.getElementById('create-name').focus({ preventScroll: true }), 100);
}
function closeCreate() {
  document.getElementById('create-overlay').classList.remove('active');
  document.getElementById('ac-list').classList.remove('open');
}

// ── Templates ──
let _selectedTemplate = null;
let _allTemplates = [];
let _templatesLoaded = false;

async function _loadTemplates() {
  if (_templatesLoaded) { _renderTemplateAccordion(); return; }
  try {
    const r = await fetch(API + '/api/templates');
    _allTemplates = await r.json();
    _templatesLoaded = true;
  } catch(e) { _allTemplates = []; }
  _renderTemplateAccordion();
}

function _renderTemplateAccordion() {
  const loading = document.getElementById('tmpl-loading');
  const acc = document.getElementById('tmpl-accordion');
  if (loading) loading.style.display = 'none';
  if (!acc) return;
  if (!_allTemplates.length) {
    acc.style.display = 'none';
    return;
  }
  acc.innerHTML = _allTemplates.map((t, i) =>
    `<div class="tmpl-item" id="tmpl-item-${i}">
      <div class="tmpl-item-hdr" onclick="_toggleTmplItem(${i})">
        <span class="tmpl-item-icon">${t.icon || '📋'}</span>
        <span class="tmpl-item-label">${esc(t.label)}</span>
        <span class="tmpl-item-chev">&#x25B6;</span>
      </div>
      <div class="tmpl-item-body">
        <div class="tmpl-item-desc">${esc(t.description || '')}</div>
        ${t.dirs && t.dirs.length ? `<div class="tmpl-item-dirs">Creates: ${t.dirs.map(d => `<code>${esc(d)}/</code>`).join(' ')}</div>` : ''}
        <button class="btn" style="font-size:0.75rem;padding:3px 10px;" onclick="event.stopPropagation();_selectTemplate(${i})">Use this template</button>
      </div>
    </div>`
  ).join('');
  acc.style.display = '';
}

function _toggleTmplSection() {
  const body = document.getElementById('tmpl-section-body');
  const chev = document.getElementById('tmpl-section-chev');
  const open = body.style.display === 'none';
  body.style.display = open ? '' : 'none';
  chev.style.transform = open ? 'rotate(90deg)' : '';
  if (open) {
    // Lazy-load templates on first expand
    if (!_templatesLoaded) {
      _loadTemplates();
    } else {
      document.getElementById('tmpl-accordion').style.display = _selectedTemplate ? 'none' : '';
      document.getElementById('tmpl-loading').style.display = 'none';
    }
  }
}

function _toggleTmplItem(i) {
  document.getElementById('tmpl-item-' + i)?.classList.toggle('open');
}

function _selectTemplate(i) {
  _selectedTemplate = _allTemplates[i];
  document.getElementById('tmpl-accordion').style.display = 'none';
  document.getElementById('tmpl-selected-wrap').style.display = '';
  document.getElementById('tmpl-selected-text').textContent = (_selectedTemplate.icon || '') + ' ' + _selectedTemplate.label;
  // Show badge in collapsed header
  const badge = document.getElementById('tmpl-selected-badge');
  badge.textContent = (_selectedTemplate.icon || '') + ' ' + _selectedTemplate.label;
  badge.style.display = '';
  // Auto-fill initial prompt if field is empty and template has one
  const promptEl = document.getElementById('create-prompt');
  if (_selectedTemplate.initial_prompt && !promptEl.value.trim()) {
    promptEl.value = _selectedTemplate.initial_prompt;
  }
}

function _clearTemplate() {
  _selectedTemplate = null;
  document.getElementById('tmpl-accordion').style.display = '';
  document.getElementById('tmpl-selected-wrap').style.display = 'none';
  document.getElementById('tmpl-selected-badge').style.display = 'none';
}
function _createNameChanged(val) {
  // Auto-update branch name if user hasn't manually edited it
  if (!_createBranchEdited) {
    const slug = val.trim().toLowerCase().replace(/[^a-z0-9-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
    document.getElementById('create-branch').value = slug ? 'session/' + slug : '';
  }
}
function _onBranchInput(val) {
  _createBranchEdited = true;
}
let _branchesLoaded = '';  // dir for which branches were last loaded
let _allBranches = [];     // cached branch list for filtering
async function _loadExistingBranches() {
  const dir = document.getElementById('create-dir').value.trim();
  if (!dir) return;
  if (dir !== _branchesLoaded) {
    _branchesLoaded = dir;
    _allBranches = [];
    try {
      const r = await fetch(API + '/api/git-branches?' + new URLSearchParams({dir}));
      const d = await r.json();
      if (d.branches) _allBranches = d.branches;
    } catch(e) {}
  }
  _filterBranches();
}
function _filterBranches() {
  const el = document.getElementById('create-branch-existing');
  if (!_allBranches.length) { el.style.display = 'none'; return; }
  const q = document.getElementById('create-branch').value.trim().toLowerCase();
  const filtered = q ? _allBranches.filter(b => b.toLowerCase().includes(q)) : _allBranches;
  if (!filtered.length) { el.style.display = 'none'; el.innerHTML = ''; return; }
  el.innerHTML = '<span style="font-size:0.72rem;color:var(--dim);width:100%;">' + (q ? `Matching branches (${filtered.length}):` : `Existing branches (${_allBranches.length}):`) + '</span>' +
    filtered.slice(0, 20).map(b =>
      `<span class="chip" style="cursor:pointer;font-size:0.75rem;" onclick="document.getElementById('create-branch').value='${esc(b)}';_createBranchEdited=true;_filterBranches();">${esc(b)}</span>`
    ).join('') + (filtered.length > 20 ? `<span style="font-size:0.72rem;color:var(--dim);">+${filtered.length - 20} more</span>` : '');
  el.style.display = 'flex';
}
function _toggleCreateBranch(on) {
  document.getElementById('create-branch-wrap').style.display = on ? '' : 'none';
  if (!on) {
    // nothing extra to reset
  }
  if (on) {
    // Pre-fill if empty
    const inp = document.getElementById('create-branch');
    if (!inp.value) {
      const name = document.getElementById('create-name').value.trim();
      const slug = name.toLowerCase().replace(/[^a-z0-9-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
      inp.value = slug ? 'session/' + slug : '';
    }
    inp.addEventListener('input', () => { _createBranchEdited = true; }, {once: true});
    setTimeout(() => inp.focus({preventScroll: true}), 50);
  }
}
function _toggleWorktree(on) {
  document.getElementById('create-worktree-info').style.display = on ? '' : 'none';
  if (on) {
    // Worktree implies branch — enable and lock branch checkbox
    document.getElementById('create-branch-enabled').checked = true;
    _toggleCreateBranch(true);
  }
}
let _gitCheckTimer = null;
async function _checkDirGit(dir) {
  if (!dir) { _createDirIsGit = false; document.getElementById('create-worktree-field').style.display = 'none'; return; }
  try {
    const r = await fetch(API + '/api/git-check?dir=' + encodeURIComponent(dir));
    const d = await r.json();
    _createDirIsGit = !!d.is_git;
    document.getElementById('create-worktree-field').style.display = _createDirIsGit ? '' : 'none';
    if (!_createDirIsGit) {
      document.getElementById('create-worktree-enabled').checked = false;
      document.getElementById('create-worktree-info').style.display = 'none';
    }
  } catch(e) {
    _createDirIsGit = false;
    document.getElementById('create-worktree-field').style.display = 'none';
  }
}
async function _suggestBranch() {
  const name = document.getElementById('create-name').value.trim();
  const dir = document.getElementById('create-dir').value.trim();
  const prompt = document.getElementById('create-prompt').value.trim();
  const btn = document.getElementById('create-branch-suggest-btn');
  const sugg = document.getElementById('create-branch-suggestions');
  btn.textContent = '…'; btn.disabled = true;
  sugg.style.display = 'none'; sugg.innerHTML = '';
  try {
    const r = await fetch(API + '/api/suggest-branch', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({name, dir, prompt}),
    });
    const d = await r.json();
    if (d.suggestions && d.suggestions.length) {
      sugg.innerHTML = d.suggestions.map(s =>
        `<span class="chip" style="cursor:pointer;" onclick="document.getElementById('create-branch').value='${esc(s)}';_createBranchEdited=true;document.getElementById('create-branch-suggestions').style.display='none';">${esc(s)}</span>`
      ).join('');
      sugg.style.display = 'flex';
    }
  } catch(e) {}
  btn.textContent = '✨'; btn.disabled = false;
}
async function submitCreate() {
  const name = document.getElementById('create-name').value.trim();
  const dir = document.getElementById('create-dir').value.trim();
  const typedPrompt = document.getElementById('create-prompt').value.trim();
  // Use typed prompt, fall back to template's initial_prompt if field is empty
  const prompt = typedPrompt || (_selectedTemplate && _selectedTemplate.initial_prompt ? _selectedTemplate.initial_prompt : '');
  const branchEnabled = document.getElementById('create-branch-enabled').checked;
  const branch = branchEnabled ? document.getElementById('create-branch').value.trim() : '';
  const worktreeEnabled = document.getElementById('create-worktree-enabled').checked && _createDirIsGit;
  if (!name) { document.getElementById('create-name').focus({ preventScroll: true }); return; }

  if (!online) {
    // Offline: save as draft, will sync when connected
    closeCreate();
    addDraft(name, dir, prompt);
    showToast('Saved draft — will sync when online');
    render();
    return;
  }

  // Online: create immediately, optionally queue prompt. Direct fetch (not
  // apiCall) so a name clash (409) shows a clear message and keeps the dialog
  // open to fix — apiCall would pop a generic "Error: 409" with the form gone.
  const createBody = { name, dir, creator: _getDeviceName() };
  if (_createProvider !== 'claude') createBody.provider = _createProvider;
  // Ollama needs its model chosen now — the server routes it to CC_MODEL and
  // builds `--model` at launch. Without it the create path defaulted to the
  // CLAUDE default model, mislabelling the worker (AMUX-3182).
  if (_createProvider === 'ollama') {
    const _om = document.getElementById('create-ollama-model');
    const _m = _om && _om.value ? _om.value.trim() : '';
    if (_m) createBody.model = _m;
  }
  if (worktreeEnabled) createBody.worktree = true;
  let r;
  try {
    r = await fetch(API + '/api/sessions', {
      method: 'POST', headers: _authHeaders({'Content-Type':'application/json'}),
      body: JSON.stringify(createBody)
    });
  } catch(e) {
    showToast('Create failed — server unreachable');
    return;
  }
  if (r.status === 409) {
    const nameEl = document.getElementById('create-name');
    showToast('A worker named “' + name + '” already exists — pick another name');
    if (nameEl) { nameEl.focus({ preventScroll: true }); nameEl.select && nameEl.select(); }
    return;   // leave the dialog open so the name can be changed
  }
  if (!r.ok) {
    let emsg = ''; try { emsg = (await r.json()).error || ''; } catch(e) {}
    showToast('Create failed: ' + (emsg || ('error ' + r.status)));
    return;   // dialog stays open
  }
  closeCreate();
  if (r && r.ok) {
    if (dir) _addRecentDir(dir);
    // Apply template if selected (creates dirs + writes CLAUDE.md before session starts)
    if (_selectedTemplate && dir) {
      await fetch(API + '/api/sessions/' + encodeURIComponent(name) + '/apply-template', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({ template_id: _selectedTemplate.id, dir }),
      }).catch(() => {});
    }
    // Save branch preference: custom name, auto (default), or none
    if (branch && dir) {
      // Custom branch name — create it and save to config
      await fetch(API + '/api/sessions/' + encodeURIComponent(name) + '/git', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({branch, create: true}),
      }).catch(() => {});
      await fetch(API + '/api/sessions/' + encodeURIComponent(name) + '/config', {
        method: 'PATCH', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({branch}),
      }).catch(() => {});
    } else if (branchEnabled && !branch && dir) {
      // Checkbox on but no custom name — auto-create will handle it
    } else if (!branchEnabled && dir) {
      // Explicitly no branch — work on main
      await fetch(API + '/api/sessions/' + encodeURIComponent(name) + '/config', {
        method: 'PATCH', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({branch: 'none'}),
      }).catch(() => {});
    }
    // If YOLO-by-default is on, enable it BEFORE start so the worker launches in
    // YOLO mode (adds the flag to CC_FLAGS; keeps the resolved --model).
    await _applyYoloDefault(name);
    // Start session — pass prompt to server so it waits for Claude to be ready
    const startBody = prompt ? { prompt } : {};
    await apiCall(API + '/api/sessions/' + encodeURIComponent(name) + '/start', {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify(startBody)
    });
  }
  await fetchSessions();
  // Scroll to the newly created session card
  const newCard = document.querySelector('[data-session="' + CSS.escape(name) + '"]');
  if (newCard) newCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

// ── Directory autocomplete + recent dirs ──
let acTimer = null;
let acItems = [];
let acSelected = -1;
let _acSuppressNext = false;  // set true on paste — skip dropdown for that one input event

function _getRecentDirs() {
  try { return JSON.parse(localStorage.getItem('amux_recent_dirs') || '[]'); } catch(e) { return []; }
}
function _addRecentDir(dir) {
  if (!dir) return;
  let recents = _getRecentDirs().filter(d => d !== dir);
  recents.unshift(dir);
  recents = recents.slice(0, 12);
  localStorage.setItem('amux_recent_dirs', JSON.stringify(recents));
}
function _buildSuggestedDirs() {
  // Combine recent dirs + unique dirs from loaded sessions, deduped
  const recents = _getRecentDirs();
  const sessionDirs = [...new Set(sessions.map(s => s.dir).filter(Boolean))];
  const combined = [...recents];
  for (const d of sessionDirs) {
    if (!combined.includes(d)) combined.push(d);
  }
  return combined.slice(0, 15);
}

function _acShowSuggested() {
  const el = document.getElementById('ac-list');
  const recents = _getRecentDirs();
  const sessionDirs = [...new Set(sessions.map(s => s.dir).filter(Boolean))].filter(d => !recents.includes(d));
  if (!recents.length && !sessionDirs.length) { el.classList.remove('open'); return; }
  acItems = [...recents, ...sessionDirs].slice(0, 15);
  acSelected = -1;
  let html = '';
  if (recents.length) {
    html += `<div class="ac-section">Recent</div>`;
    html += recents.slice(0, 8).map((item, i) =>
      `<div class="ac-item" onmousedown="acPick(${i})">${esc(item)}</div>`
    ).join('');
  }
  if (sessionDirs.length) {
    const offset = recents.length;
    html += `<div class="ac-section">Workers</div>`;
    html += sessionDirs.slice(0, 7).map((item, i) =>
      `<div class="ac-item" onmousedown="acPick(${offset + i})">${esc(item)}</div>`
    ).join('');
  }
  el.innerHTML = html;
  el.classList.add('open');
}

function acFetch(query) {
  clearTimeout(acTimer);
  const el = document.getElementById('ac-list');
  if (_acSuppressNext) {
    _acSuppressNext = false;
    el.classList.remove('open');
    return;
  }
  if (!query || query.length < 2) {
    // Show recent/session dirs when field is empty or very short
    _acShowSuggested();
    return;
  }
  el.classList.remove('open');
  acTimer = setTimeout(async () => {
    try {
      const r = await fetch(API + '/api/autocomplete/dir?q=' + encodeURIComponent(query));
      acItems = await r.json();
      acSelected = -1;
      if (!acItems.length) { el.classList.remove('open'); return; }
      el.innerHTML = acItems.map((item, i) =>
        `<div class="ac-item" onmousedown="acPick(${i})">${esc(item)}</div>`
      ).join('');
      el.classList.add('open');
    } catch(e) {}
  }, 150);
}
function acPick(i) {
  const inp = document.getElementById('create-dir');
  inp.value = acItems[i];
  document.getElementById('ac-list').classList.remove('open');
  // If they picked a dir, fetch its contents
  setTimeout(() => acFetch(inp.value), 50);
}
function acKeydown(e) {
  const el = document.getElementById('ac-list');
  if (!el.classList.contains('open')) {
    if (e.key === 'Enter') { e.preventDefault(); submitCreate(); }
    return;
  }
  if (e.key === 'ArrowDown') {
    e.preventDefault();
    acSelected = Math.min(acSelected + 1, acItems.length - 1);
    acHighlight();
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    acSelected = Math.max(acSelected - 1, 0);
    acHighlight();
  } else if (e.key === 'Enter') {
    e.preventDefault();
    if (acSelected >= 0) acPick(acSelected);
    else { el.classList.remove('open'); submitCreate(); }
  } else if (e.key === 'Tab' && acItems.length) {
    e.preventDefault();
    acPick(acSelected >= 0 ? acSelected : 0);
  } else if (e.key === 'Escape') {
    el.classList.remove('open');
  }
}
function acHighlight() {
  const items = document.getElementById('ac-list').querySelectorAll('.ac-item');
  items.forEach((el, i) => el.classList.toggle('selected', i === acSelected));
  if (items[acSelected]) items[acSelected].scrollIntoView({ block: 'nearest' });
}
// Close autocomplete when clicking outside
document.addEventListener('click', e => {
  if (!e.target.closest('.ac-wrap')) {
    document.getElementById('ac-list').classList.remove('open');
  }
  // Close card slash/@ autocomplete
  if (!e.target.closest('.send-row') && _cardAcName) {
    const el = document.getElementById('card-ac-' + _cardAcName);
    if (el) { el.classList.remove('open'); el._atItems = null; el._atSel = -1; }
    _cardAcItems = [];
  }
});

// ═══════ EVENT HANDLERS ═══════
// Pause peek refresh while selecting text (keep paused until selection is cleared or copied)
let peekSelectTimer = null;
function peekCheckSelection() {
  clearTimeout(peekSelectTimer);
  const sel = window.getSelection();
  if (sel && sel.toString().length > 0) {
    peekSelecting = true;
    peekSelectTimer = setTimeout(peekCheckSelection, 500);
  } else {
    peekSelecting = false;
  }
}
document.getElementById('peek-body').addEventListener('mousedown', () => { peekSelecting = true; clearTimeout(peekSelectTimer); });
document.getElementById('peek-body').addEventListener('touchstart', () => { peekSelecting = true; clearTimeout(peekSelectTimer); }, {passive: true});
document.getElementById('peek-body').addEventListener('scroll', function() {
  if (_isScrolledToBottom(this)) {
    _peekScrollLocked = false;
    _hideScrollLockBadge(this);
  } else {
    _peekScrollLocked = true;
    _showScrollLockBadge(this, () => {
      _peekScrollLocked = false;
      applyPeekSearch(false, false);
      this.scrollTop = this.scrollHeight;
      _hideScrollLockBadge(this);
    });
  }
}, {passive: true});
// Force URLs in peek output to open in the system browser (PWA desktop + mobile).
// Handle both click (desktop) and touchend (iOS/Android) for reliability.
function _peekOpenLink(e) {
  const a = e.target.closest('a[href]');
  if (!a) return;
  const href = a.href;
  if (!href || !/^https?:\/\//.test(href)) return;
  // Don't preventDefault — let the anchor's natural target="_blank" navigation fire.
  // Chrome desktop PWA scope rules open external URLs in the system browser.
  // Any programmatic replacement (window.open, tmp.click) loses the user gesture
  // and can be silently blocked.
  e.stopPropagation();
}
document.getElementById('peek-body').addEventListener('click', _peekOpenLink);
document.getElementById('peek-body').addEventListener('touchend', _peekOpenLink, {passive: false});
document.addEventListener('mouseup', () => { peekCheckSelection(); _peekShowSelPopover(); });
document.addEventListener('touchend', () => { peekCheckSelection(); setTimeout(_peekShowSelPopover, 50); });

// ── Peek selection popover (Look up / Copy) ──
function _peekShowSelPopover() {
  const sel = window.getSelection();
  const text = sel ? sel.toString().trim() : '';
  const body = document.getElementById('peek-body');
  // Only show when selection is inside peek body
  if (!text || !body || !sel.anchorNode || !body.contains(sel.anchorNode)) {
    _peekHideSelPopover();
    return;
  }
  let pop = document.getElementById('peek-sel-popover');
  if (!pop) {
    pop = document.createElement('div');
    pop.id = 'peek-sel-popover';
    pop.style.cssText = 'position:fixed;z-index:10000;background:#1a1a2e;border:1px solid #444;border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,0.5);padding:4px;display:flex;gap:2px;font-size:0.78rem;';
    pop.innerHTML = '<button id="peek-sel-lookup" style="background:none;border:none;color:#c7d2fe;padding:6px 10px;cursor:pointer;border-radius:5px;">&#x1F50D; Look up</button><button id="peek-sel-copy" style="background:none;border:none;color:#c7d2fe;padding:6px 10px;cursor:pointer;border-radius:5px;">Copy</button><button id="peek-sel-read" style="background:none;border:none;color:#c7d2fe;padding:6px 10px;cursor:pointer;border-radius:5px;">&#x1F50A; Read aloud</button>';
    document.body.appendChild(pop);
    pop.querySelector('#peek-sel-lookup').onclick = (e) => { e.stopPropagation(); _peekLookupSelection(); };
    pop.querySelector('#peek-sel-copy').onclick = (e) => {
      e.stopPropagation();
      const t = window.getSelection()?.toString() || '';
      if (t) navigator.clipboard?.writeText(t);
      _peekHideSelPopover();
    };
    // Read aloud the highlighted text (Ethan: "drag and highlight then I can do
    // lookup copy or read aloud"). Same /api/tts path as the one-click button;
    // the audio plays independently, so hiding the popover after kicking it off
    // is fine (_ttsSpeak's button-state restore is harmless on the hidden node).
    pop.querySelector('#peek-sel-read').onclick = (e) => {
      e.stopPropagation();
      const t = window.getSelection()?.toString() || '';
      const btn = e.currentTarget;
      _peekHideSelPopover();
      if (t) _ttsSpeak(t, btn);
    };
    pop.addEventListener('mousedown', (e) => e.preventDefault()); // don't kill selection
  }
  // Position above the selection
  const range = sel.getRangeAt(0);
  const rect = range.getBoundingClientRect();
  pop.style.display = 'flex';
  // Default above selection; if no room, put below
  const popH = 36;
  const popW = 250;   // three buttons: Look up · Copy · Read aloud
  let top = rect.top - popH - 8;
  if (top < 8) top = rect.bottom + 8;
  let left = rect.left + (rect.width / 2) - (popW / 2);
  left = Math.max(8, Math.min(left, window.innerWidth - popW - 8));
  pop.style.top = top + 'px';
  pop.style.left = left + 'px';
}
function _peekHideSelPopover() {
  const pop = document.getElementById('peek-sel-popover');
  if (pop) pop.style.display = 'none';
}
async function _peekLookupSelection() {
  const text = window.getSelection()?.toString().trim() || '';
  if (!text) return;
  _peekHideSelPopover();
  _peekShowLookupModal(text, null, true);
  try {
    const r = await fetch(API + '/api/lookup', {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ text, session: peekSession })
    });
    // NEVER call r.json() unconditionally. /api/lookup was never ported from
    // python, so nothing was mounted at that path and the GET-only SPA
    // catch-all answered this POST with 405 and a ZERO-BYTE body. r.json()
    // then threw "Unexpected end of JSON input" — a parser error naming
    // neither the path nor the status, which sent the reader at the client
    // instead of at a missing route.
    const raw = await r.text();
    let d = null;
    try { d = raw ? JSON.parse(raw) : null; } catch (_) { /* handled next */ }
    if (!d) {
      const detail = raw ? raw.slice(0, 200) : '(empty body)';
      _peekShowLookupModal(
        text, 'Lookup failed: HTTP ' + r.status + ' from /api/lookup — ' + detail, false);
      amuxTrack('lookup_non_json', { status: r.status, bytes: raw.length });
      return;
    }
    if (d.error) {
      _peekShowLookupModal(text, 'Error: ' + d.error, false);
    } else {
      _peekShowLookupModal(text, d.text || '(no response)', false);
    }
  } catch (e) {
    _peekShowLookupModal(text, 'Lookup failed: ' + e.message, false);
      amuxTrack('lookup_failed', { err: String(e).slice(0, 200) });
  }
}
function _peekShowLookupModal(query, result, loading) {
  let modal = document.getElementById('peek-lookup-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'peek-lookup-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:10001;display:flex;align-items:center;justify-content:center;padding:20px;';
    modal.innerHTML = '<div style="background:#1a1a2e;border:1px solid #444;border-radius:12px;max-width:560px;width:100%;max-height:80dvh;overflow:auto;padding:20px;box-shadow:0 24px 64px rgba(0,0,0,0.6);color:#e8e8e8;position:relative;"><button id="peek-lookup-close" style="position:absolute;top:10px;right:12px;background:none;border:none;color:#aaa;font-size:1.1rem;cursor:pointer;">&#x2715;</button><div style="font-size:0.7rem;color:#888;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:6px;">Looking up</div><div id="peek-lookup-query" style="font-family:monospace;font-size:0.85rem;background:#111;padding:8px 12px;border-radius:6px;margin-bottom:14px;word-break:break-word;max-height:120px;overflow:auto;"></div><div style="font-size:0.7rem;color:#888;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:6px;">Explanation</div><div id="peek-lookup-result" style="font-size:0.92rem;line-height:1.55;white-space:pre-wrap;"></div></div>';
    document.body.appendChild(modal);
    modal.querySelector('#peek-lookup-close').onclick = () => { modal.style.display = 'none'; };
    modal.addEventListener('click', (e) => { if (e.target === modal) modal.style.display = 'none'; });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modal.style.display !== 'none') modal.style.display = 'none';
    });
  }
  modal.querySelector('#peek-lookup-query').textContent = query;
  modal.querySelector('#peek-lookup-result').textContent = loading ? 'Looking up…' : result;
  modal.style.display = 'flex';
}
// Hide popover on click outside
document.addEventListener('mousedown', (e) => {
  const pop = document.getElementById('peek-sel-popover');
  if (pop && pop.style.display !== 'none' && !pop.contains(e.target)) {
    // Let the new selection check handle re-showing
    setTimeout(() => { if (!window.getSelection()?.toString().trim()) _peekHideSelPopover(); }, 10);
  }
});

// ── Clipboard: copy/paste events (most reliable in Chrome PWA desktop) ──
// The 'copy' and 'paste' DOM events give direct clipboardData access without
// any permission prompt, and Chrome fires them for Cmd/Ctrl+C/V even in
// standalone PWA mode where no native Edit menu exists.

document.addEventListener('copy', function(e) {
  const ae = document.activeElement;
  if (ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.isContentEditable)) return;
  const sel = window.getSelection()?.toString();
  if (sel) { e.clipboardData.setData('text/plain', sel); e.preventDefault(); }
});

document.addEventListener('paste', function(e) {
  const ae = document.activeElement;
  if (ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.isContentEditable)) return;
  const peekOpen = document.getElementById('peek-overlay')?.classList.contains('active');
  const boardOpen = document.getElementById('board-detail-overlay')?.classList.contains('active');
  // Check for image/file paste — route to uploadAndAttach when peek is open
  if (peekOpen && e.clipboardData?.items) {
    for (const item of e.clipboardData.items) {
      if (item.kind === 'file') {
        e.preventDefault();
        _enqueueUpload(item.getAsFile());
        return;
      }
    }
  }
  const text = e.clipboardData?.getData('text/plain');
  if (!text) return;
  const inp = peekOpen ? document.getElementById('peek-cmd-input')
    : boardOpen ? document.querySelector('#board-detail-overlay textarea, #board-detail-overlay input')
    : document.querySelector('.card.open .send-input') || document.getElementById('search');
  if (!inp) return;
  e.preventDefault();
  if (inp.id === 'peek-cmd-input') _slashAcSuppressNext = true;
  const s = inp.selectionStart ?? inp.value.length;
  const en = inp.selectionEnd ?? inp.value.length;
  inp.value = inp.value.slice(0, s) + text + inp.value.slice(en);
  inp.selectionStart = inp.selectionEnd = s + text.length;
  inp.focus({ preventScroll: true });
  inp.dispatchEvent(new Event('input', { bubbles: true }));
});

// ── PWA clipboard polyfill ────────────────────────────────────────
// macOS desktop PWAs don't fire native copy/paste/select-all events even when
// focus is on an editable element. This helper intercepts those shortcuts and
// implements them via the Clipboard API. Called first in all keydown handlers
// so it works in every app context (sessions, peek, board detail, workspace).
// Returns true if the event was fully handled.
function _pasteTextInto(target) {
  navigator.clipboard.readText().then(text => {
    if (!text) return;
    if (target.id === 'create-dir') _acSuppressNext = true;
    if (target.id === 'peek-cmd-input') _slashAcSuppressNext = true;
    target.focus({ preventScroll: true });
    const s = target.selectionStart ?? target.value.length;
    const en = target.selectionEnd ?? target.value.length;
    target.value = target.value.slice(0, s) + text + target.value.slice(en);
    target.selectionStart = target.selectionEnd = s + text.length;
    target.dispatchEvent(new Event('input', { bubbles: true }));
    if (typeof autoGrow === 'function') autoGrow(target);
  }).catch(() => showToast('Paste failed — clipboard blocked?'));  // user action: never fail silently
}
function _pwaCb(e) {
  if (!(e.metaKey || e.ctrlKey) || e.altKey || e.shiftKey) return false;
  const k = e.key.toLowerCase();
  if (k !== 'a' && k !== 'c' && k !== 'x' && k !== 'v') return false;
  const ae = document.activeElement;
  // Textarea (notes editor): let browser handle natively
  if (ae && (ae.id === 'notes-editor' || ae.id === 'peek-notes-editor')) return false;
  // Other contentEditable elements: let browser handle natively
  if (ae && ae.isContentEditable) return false;
  const inp = (ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA')) ? ae : null;

  // Cmd+A — select all in focused input
  if (k === 'a' && inp) { e.preventDefault(); inp.select(); return true; }

  // Cmd+C / Cmd+X — copy (or cut) selected text.
  // Works for both focused inputs AND plain text selected in terminal output divs.
  if ((k === 'c' || k === 'x') && navigator.clipboard?.writeText) {
    // Case 1: focused input/textarea with a text selection
    if (inp) {
      const sel = inp.value.slice(inp.selectionStart, inp.selectionEnd);
      if (sel) {
        e.preventDefault();
        // Copy is a user action: confirm it, and surface a clipboard denial
        navigator.clipboard.writeText(sel).then(() => showToast('Copied'), () => showToast('Copy failed'));
        if (k === 'x') {
          const s = inp.selectionStart, en = inp.selectionEnd;
          inp.value = inp.value.slice(0, s) + inp.value.slice(en);
          inp.selectionStart = inp.selectionEnd = s;
          inp.dispatchEvent(new Event('input', { bubbles: true }));
          if (typeof autoGrow === 'function') autoGrow(inp);
        }
        return true;
      }
    }
    // Case 2: text selected in a terminal output div (peek body, workspace pane body, etc.)
    if (k === 'c') {
      const sel = window.getSelection()?.toString();
      if (sel) {
        e.preventDefault();
        navigator.clipboard.writeText(sel).then(() => showToast('Copied'), () => showToast('Copy failed'));
        return true;
      }
    }
  }

  // Cmd+V — paste into best available input via clipboard API.
  // We always use clipboard.readText() rather than relying on native paste events,
  // because Chrome desktop PWA does not reliably fire native paste on focused inputs.
  if (k === 'v') {
    const peekOpen  = document.getElementById('peek-overlay')?.classList.contains('active');
    const boardOpen = document.getElementById('board-detail-overlay')?.classList.contains('active');
    const gridOpen  = document.getElementById('grid-view')?.classList.contains('active');
    const target = inp
      || (peekOpen  && document.getElementById('peek-cmd-input'))
      || (boardOpen && document.querySelector('#board-detail-overlay textarea, #board-detail-overlay input'))
      || (gridOpen  && document.activeElement?.closest('#grid-view') && document.activeElement)
      || document.querySelector('.card.open .send-input')
      || document.getElementById('search');
    if (!target) return false;

    // If the target is already focused, let the browser handle Cmd+V natively.
    if (target === document.activeElement) return false;
    if (!navigator.clipboard?.readText) return false;
    e.preventDefault();
    // Try clipboard.read() first for image/file paste support in peek
    if (peekOpen && navigator.clipboard.read) {
      navigator.clipboard.read().then(items => {
        for (const item of items) {
          const imgType = item.types.find(t => t.startsWith('image/'));
          if (imgType) {
            item.getType(imgType).then(blob => {
              const ext = imgType.split('/')[1] || 'png';
              const file = new File([blob], 'pasted-image.' + ext, { type: imgType });
              _enqueueUpload(file);
            });
            return;
          }
        }
        _pasteTextInto(target);
      }).catch(() => _pasteTextInto(target));
    } else {
      _pasteTextInto(target);
    }
    return true;
  }

  return false;
}

document.addEventListener('keydown', (e) => {
  // Clipboard shortcuts work everywhere — run before any context-specific early returns
  if (_pwaCb(e)) return;

  // File preview / markdown overlay is the topmost modal (can open over peek OR
  // standalone from the file explorer) — Escape exits it, closing the find bar or
  // the mobile actions menu first if either is open.
  const _fo = document.getElementById('file-overlay');
  if (_fo && _fo.classList.contains('active')) {
    if (e.key === 'Escape') {
      e.preventDefault();
      const sr = document.getElementById('md-search-row');
      if (sr && sr.classList.contains('active')) { _mdSearchClose(); return; }
      const fa = document.getElementById('file-actions');
      if (fa && fa.classList.contains('open')) { fa.classList.remove('open'); return; }
      closeFilePreview();
    }
    return;
  }

  if (document.getElementById('grid-view').classList.contains('active')) {
    if (e.key === 'Escape') { e.preventDefault(); exitGridMode(); return; }
    if ((e.ctrlKey || e.metaKey) && e.key === 'c' && !e.altKey && !e.shiftKey) {
      const hasSelection = window.getSelection().toString().length > 0;
      if (!hasSelection) {
        const names = Object.keys(_gridPanes);
        const target = _lastActivePane && _gridPanes[_lastActivePane] ? _lastActivePane
          : names.length === 1 ? names[0] : null;
        if (target) { e.preventDefault(); gpDoKeys(target, 'C-c'); return; }
      }
    }
    return;
  }
  if (document.getElementById('sched-overlay').classList.contains('active')) {
    if (e.key === 'Escape') { e.preventDefault(); closeSchedModal(); return; }
    return;
  }
  if (document.getElementById('board-detail-overlay').classList.contains('active')) {
    if (e.key === 'Escape') { e.preventDefault(); closeBoardDetail(); return; }
    if ((e.metaKey || e.ctrlKey) && e.key === 's') { e.preventDefault(); boardDetailSave(); return; }
    return;
  }
  if (!document.getElementById('peek-overlay').classList.contains('active')) return;
  if (e.key === 'Escape') {
    const histM = document.getElementById('cmd-history-modal');
    if (histM && histM.classList.contains('active')) { e.preventDefault(); closeCmdHistoryModal(); return; }
    e.preventDefault(); closePeek(); return;
  }
  // Ctrl+C with no selection → send interrupt; Ctrl+X (outside input) → send Ctrl-X
  if ((e.metaKey || e.ctrlKey) && !e.altKey && !e.shiftKey) {
    const ae = document.activeElement;
    const inInput = ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA');
    const hasPageSelection = window.getSelection().toString().length > 0;
    const hasInputSelection = inInput && ae.selectionStart !== ae.selectionEnd;
    if (e.key === 'c' && !hasPageSelection && !hasInputSelection) {
      e.preventDefault(); peekQuickKeys('C-c'); return;
    }
    if (e.key === 'x' && !inInput && !hasPageSelection) {
      e.preventDefault(); peekQuickKeys('C-x'); return;
    }
  }
});

// ── Escape closes the topmost modal, whatever it is ───────────────────────
// The handler above knows five overlay ids BY NAME and hard-returns unless
// peek is open, so it can never reach a dialog app.js appends to <body>: 12
// of those 14 dialogs had no Escape at all. An unreachable footer plus no
// Escape is a trap, so this is the generic backstop.
//
// It CLICKS the dialog's own cancel control rather than removing the node.
// Several of these dialogs are promises (_gateConfirm, _showSteerPrompt) and
// ripping the backdrop out of the DOM would leave the caller awaiting a
// promise that can never settle — a hang instead of a cancel. Clicking Cancel
// runs the dialog's own cleanup path, which means a dialog added LATER gets
// Escape for free with no registration to remember.
//
// Runs only when the handler above did not already preventDefault, so the
// five ids it owns keep their specific close functions.
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape' || e.defaultPrevented) return;
  // Overlays with a dedicated handler, or deliberately not dismissable
  // (upgrade/apikey are gates their authors chose to make sticky — rule 8:
  // do not quietly overturn someone else's decision).
  const OWNED = ['peek-overlay', 'wt-overlay', 'video-overlay', 'teleprompter-overlay',
                 'upgrade-modal', 'apikey-setup-modal'];
  const vw = window.innerWidth, vh = window.innerHeight;
  let best = null, bestZ = -1;
  for (const el of document.body.children) {
    if (OWNED.indexOf(el.id) !== -1) continue;
    const cs = getComputedStyle(el);
    if (cs.position !== 'fixed' || cs.display === 'none' || cs.visibility === 'hidden') continue;
    if (parseFloat(cs.opacity || '1') < 0.05) continue;
    const r = el.getBoundingClientRect();
    if (r.width < vw - 4 || r.height < vh - 4) continue;   // must be a full backdrop
    const z = parseInt(cs.zIndex, 10) || 0;
    if (z >= bestZ) { bestZ = z; best = el; }              // ties: later in DOM wins
  }
  if (!best) return;
  const CANCEL = /^(cancel|close|dismiss|not now|later)$/i;
  const btn = Array.prototype.slice.call(best.querySelectorAll('button, .btn')).find((b) => {
    const cs = getComputedStyle(b);
    return cs.display !== 'none' && cs.visibility !== 'hidden' &&
           CANCEL.test((b.textContent || '').trim());
  });
  e.preventDefault();
  if (btn) { btn.click(); return; }
  if (best.classList.contains('active')) { best.classList.remove('active'); return; }
  if (best.classList.contains('open')) { best.classList.remove('open'); return; }
  if (!best.id) { best.remove(); return; }                 // anonymous, no cancel
  best.style.display = 'none';
});

// ═══════ LAYOUT MODES (list / grid) ═══════
let layoutMode = localStorage.getItem('amux_layout') || 'grid';
let sortMode = localStorage.getItem('amux_sort_mode') || 'natural';
// A mode persisted by an older build (or hand-edited) must not leave the
// list sorting by a comparator that no longer exists.
if (!['natural','human','alpha','status'].includes(sortMode)) sortMode = 'natural';
if (document.body) setTimeout(() => _sortBtnSync(), 0);
else document.addEventListener('DOMContentLoaded', () => _sortBtnSync());
let cardOrder = JSON.parse(localStorage.getItem('amux_card_order') || '[]');
let _frozen = localStorage.getItem('amux_frozen') === '1';
let _sortable = null;
let _tileJustDragged = false; // keep for toggle() guard

// Natural sort: pinned first, then most recently active
// Sort that matches the server's list_sessions() order:
// pinned > running > status priority (active/waiting=0, idle/none=1) > last_activity desc
const _STATUS_PRI = {active: 0, waiting: 0, idle: 1, '': 1};
function _naturalSortSessions(a, b) {
  if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;
  if (a.running !== b.running) return a.running ? -1 : 1;
  const ap = _STATUS_PRI[a.status] ?? 1, bp = _STATUS_PRI[b.status] ?? 1;
  if (ap !== bp) return ap - bp;
  return (b.last_activity || 0) - (a.last_activity || 0);
}

// Alphabetical sort: pinned first, then by name — stable across activity changes
function _alphaSortSessions(a, b) {
  if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;
  return (a.name || '').localeCompare(b.name || '');
}

// Last message a PERSON sent, newest first. Schedulers and inter-session
// traffic are excluded server-side (last_human_ts), so a lane driven entirely
// by a cron sinks instead of masquerading as the most recent thing you touched.
// Sessions you have never messaged sort last rather than jumbling into the
// middle at position zero.
function _humanSortSessions(a, b) {
  if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;
  const at = a.last_human_ts || 0, bt = b.last_human_ts || 0;
  if (!at && !bt) return _naturalSortSessions(a, b);
  if (!at) return 1;
  if (!bt) return -1;
  return bt - at;
}

// Status order, then recency within each bucket.
function _statusSortSessions(a, b) {
  if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;
  if (a.running !== b.running) return a.running ? -1 : 1;
  const ap = _STATUS_PRI[a.status] ?? 1, bp = _STATUS_PRI[b.status] ?? 1;
  if (ap !== bp) return ap - bp;
  return (b.last_activity || 0) - (a.last_activity || 0);
}

function _sortFnFor(mode) {
  return mode === 'alpha'  ? _alphaSortSessions
       : mode === 'human'  ? _humanSortSessions
       : mode === 'status' ? _statusSortSessions
       : _naturalSortSessions;
}

// Sort by frozen cardOrder; sessions not in the list go to the end in natural order
function _sortByCardOrder(arr) {
  const idx = Object.fromEntries(cardOrder.map((n, i) => [n, i]));
  return [...arr].sort((a, b) => {
    const ia = idx[a.name] ?? Infinity;
    const ib = idx[b.name] ?? Infinity;
    if (ia !== ib) return ia - ib;
    return _naturalSortSessions(a, b);
  });
}

function toggleFreeze() {
  if (_frozen) {
    _frozen = false;
    localStorage.removeItem('amux_frozen');
    cardOrder = [];
    localStorage.removeItem('amux_card_order');
  } else {
    // Compute order using the SAME logic as render() — works even for collapsed groups
    const visible = sessions.filter(s => !s.archived);
    let ordered;
    if (layoutMode === 'group') {
      const buckets = {active: [], waiting: [], idle: [], stopped: []};
      visible.forEach(s => {
        if (!s.running) buckets.stopped.push(s);
        else if (s.status === 'active') buckets.active.push(s);
        else if (s.status === 'waiting') buckets.waiting.push(s);
        else buckets.idle.push(s);
      });
      const sortFn = _sortFnFor(sortMode);
      for (const k of Object.keys(buckets)) buckets[k].sort(sortFn);
      ordered = [...buckets.active, ...buckets.waiting, ...buckets.idle, ...buckets.stopped];
    } else {
      ordered = [...visible].sort(_sortFnFor(sortMode));
    }
    cardOrder = ordered.map(s => s.name);
    localStorage.setItem('amux_card_order', JSON.stringify(cardOrder));
    _frozen = true;
    localStorage.setItem('amux_frozen', '1');
  }
  _updateResetBtn();
  render();
}

function _updateResetBtn() {
  const eb = document.getElementById('tile-expand-btn');
  if (eb) eb.classList.toggle('active', expanded.size > 0);
  const fb = document.getElementById('tile-freeze-btn');
  if (fb) fb.classList.toggle('active', _frozen);
}

function setLayoutMode(mode) {
  layoutMode = mode;
  localStorage.setItem('amux_layout', mode);
  const cards = document.querySelector('.cards');
  if (cards) cards.classList.toggle('grid-mode', mode === 'grid');
  if (mode === 'group') destroySortable();
  render();
  _updateResetBtn();
}

// Sort options. 'human' exists because "last activity" is dominated by
// schedulers and inter-session traffic — a lane nobody has touched in a week
// can sit at the top looking busy. Sorting by the last thing a PERSON sent
// answers "where did I leave off", which is a different question.
const _SORT_OPTS = [
  { id: 'natural', label: 'Recent activity',     hint: 'Any traffic, including schedules and other workers' },
  { id: 'human',   label: 'Last message from me', hint: 'Ignores schedulers and session-to-session' },
  { id: 'alpha',   label: 'Name (A–Z)',      hint: 'Stable — the order stops shifting under you' },
  { id: 'status',  label: 'Status',               hint: 'Active, then waiting, then idle, then stopped' },
];
const _SORT_GLYPH = { natural: '⇅', human: '●', alpha: 'A↓', status: '☷' };

function _sortLabel(id) {
  const o = _SORT_OPTS.find(x => x.id === id);
  return o ? o.label : id;
}
function _sortBtnSync() {
  const btn = document.getElementById('tile-sort-btn');
  if (!btn) return;
  btn.innerHTML = _SORT_GLYPH[sortMode] || 'A↓';
  btn.title = 'Sort: ' + _sortLabel(sortMode);
  btn.classList.toggle('active', sortMode !== 'natural');
}
function toggleSortMenu() {
  const m = document.getElementById('sort-menu');
  if (!m) return;
  const open = m.style.display !== 'block';
  m.innerHTML = _SORT_OPTS.map(o => {
    const on = o.id === sortMode;
    return `<div class="sort-opt${on ? ' active' : ''}" onclick="event.stopPropagation();setSortMode('${o.id}')">
      <div style="display:flex;align-items:center;gap:7px;">
        <span style="width:14px;opacity:${on ? 1 : 0.35};">${on ? '✓' : ''}</span>
        <span style="font-weight:${on ? 600 : 400};">${esc(o.label)}</span>
      </div>
      <div style="font-size:0.66rem;color:var(--dim);margin-left:21px;">${esc(o.hint)}</div>
    </div>`;
  }).join('');
  m.style.display = open ? 'block' : 'none';
}
function closeSortMenu() {
  const m = document.getElementById('sort-menu');
  if (m) m.style.display = 'none';
}
function setSortMode(mode) {
  sortMode = _SORT_OPTS.some(o => o.id === mode) ? mode : 'natural';
  localStorage.setItem('amux_sort_mode', sortMode);
  closeSortMenu();
  _sortBtnSync();
  // Sorting is an explicit act, so it must beat the frozen card order that
  // otherwise pins the list to whatever it looked like when you froze it.
  _frozen = false;
  try { localStorage.removeItem('amux_frozen'); localStorage.removeItem('amux_card_order'); } catch (e) {}
  cardOrder = [];
  if (typeof showToast === 'function') showToast('Sorted by ' + _sortLabel(sortMode).toLowerCase());
  render();
}

function toggleSortMode() {   // legacy entry point; cycles through the options
  const i = _SORT_OPTS.findIndex(o => o.id === sortMode);
  setSortMode(_SORT_OPTS[(i + 1) % _SORT_OPTS.length].id);
  const btn = document.getElementById('tile-sort-btn');
  if (btn) btn.classList.toggle('active', sortMode !== 'natural');
  if (sortMode !== 'natural') destroySortable();   // computed order — manual drag would fight it
  render();
}

function initSortable() {
  if (typeof Sortable === 'undefined') return;
  if (sortMode !== 'natural') { destroySortable(); return; }
  destroySortable();
  const cards = document.querySelector('.cards');
  if (!cards) return;
  _sortable = Sortable.create(cards, {
    handle: '.card-drag-handle',
    animation: 120,
    easing: 'cubic-bezier(0.2, 0, 0, 1)',
    ghostClass: 'sortable-ghost',
    chosenClass: 'sortable-chosen',
    dragClass: 'sortable-drag',
    delay: 120,
    delayOnTouchOnly: true,
    touchStartThreshold: 3,
    swapThreshold: 0.6,
    onStart: function(evt) {
      _tileJustDragged = false;
      document.body.classList.add('session-dragging');
    },
    onEnd: function(evt) {
      document.body.classList.remove('session-dragging');
      _tileJustDragged = evt.oldIndex !== evt.newIndex;
      const allCards = cards.querySelectorAll('.card[data-session]');
      cardOrder = Array.from(allCards).map(c => c.dataset.session);
      localStorage.setItem('amux_card_order', JSON.stringify(cardOrder));
      _updateResetBtn();
    }
  });
}

function destroySortable() {
  if (_sortable) { try { _sortable.destroy(); } catch(e) {} _sortable = null; }
}

// Safety net: if a drag ends abnormally (Escape, window blur, cancelled by browser),
// onEnd may not fire — clean up the dragging body classes so cursor resets.
function _clearDragClasses() {
  document.body.classList.remove('board-dragging', 'session-dragging');
}
document.addEventListener('mouseup', _clearDragClasses);
document.addEventListener('pointerup', _clearDragClasses);
document.addEventListener('dragend', _clearDragClasses);
document.addEventListener('keydown', function(e) { if (e.key === 'Escape') _clearDragClasses(); });

function tileMouseDown(e, name) {} // no-op — kept so card HTML doesn't break

// Initialize layout on load
document.addEventListener('DOMContentLoaded', function() {
  const cards = document.querySelector('.cards');
  // Default to grid on desktop, list on mobile
  if (layoutMode === 'grid' && window.innerWidth >= 900) {
    if (cards) cards.classList.add('grid-mode');
    setTimeout(initSortable, 200);
  } else {
    if (layoutMode === 'group' || (layoutMode === 'grid' && window.innerWidth < 900)) layoutMode = 'list';
    setTimeout(initSortable, 200);
  }
  const sortBtn = document.getElementById('tile-sort-btn');
  if (sortBtn) sortBtn.classList.toggle('active', sortMode !== 'natural');
  const freezeBtn = document.getElementById('tile-freeze-btn');
  if (freezeBtn) freezeBtn.classList.toggle('active', _frozen);
});

// ═══════ REPORTS ═══════
let _reportTypes = {};  // loaded from /api/reports/types
let _reportCharts = {};  // chartId → Chart instance

function _vendorColor(typeId, vid) {
  return (_reportTypes[typeId]?.vendors?.[vid]?.color) || '#888';
}
function _vendorLabel(typeId, vid) {
  return (_reportTypes[typeId]?.vendors?.[vid]?.label) || vid;
}

async function fetchReports() {
  const [rTypes, rReports] = await Promise.all([
    fetch(API + '/api/reports/types').then(r=>r.json()).catch(()=>({})),
    fetch(API + '/api/reports').then(r=>r.json()).catch(()=>[]),
  ]);
  _reportTypes = rTypes;
  renderReports(rReports);
}

function renderReports(reports) {
  const list = document.getElementById('reports-list');
  if (!reports.length) {
    list.innerHTML = '<div style="text-align:center;padding:40px 0;color:var(--dim);font-size:0.85rem;">No reports yet. Click <b>+ Add Report</b> to get started.</div>';
    return;
  }
  // Destroy old chart instances
  Object.values(_reportCharts).forEach(c => { try { c.destroy(); } catch(e){} });
  _reportCharts = {};
  list.innerHTML = reports.map(r => `
    <div class="report-card" data-report-id="${r.id}" data-report-type="${r.type||'infra-spend'}">
      <div class="report-card-header">
        <span class="report-card-title">${esc(r.name)}</span>
        <span class="report-last-refresh" id="rpt-refresh-ts-${r.id}">${r.last_refresh ? 'Updated ' + _fmtRelTime(r.last_refresh) : 'Never refreshed'}</span>
        <button class="report-refresh-btn" id="rpt-refresh-btn-${r.id}" onclick="refreshReport('${r.id}')" title="Refresh">&#x21BB;</button>
        <button class="report-del-btn" onclick="deleteReport('${r.id}')" title="Delete report">&times;</button>
      </div>
      <div class="report-body" id="rpt-body-${r.id}">
        <div style="color:var(--dim);font-size:0.82rem;padding:20px 0;text-align:center;">
          Click \u21bb to load data
        </div>
      </div>
    </div>
  `).join('');
  // Show cached data immediately, then auto-refresh in background
  reports.forEach(r => {
    loadReportData(r.id, null);
    refreshReport(r.id);
  });
}

async function loadReportData(id, data) {
  if (!data) {
    try {
      const r = await fetch(API + '/api/reports/' + id + '/data');
      const d = await r.json();
      data = d.data;
      if (d.refreshed_at) {
        const el = document.getElementById('rpt-refresh-ts-' + id);
        if (el) el.textContent = 'Updated ' + _fmtRelTime(d.refreshed_at);
      }
    } catch(e) { return; }
  }
  if (!data || !Object.keys(data).length) return;
  const body = document.getElementById('rpt-body-' + id);
  if (!body) return;
  const _rCard = body.closest('[data-report-id]');
  const _rtype = _rCard ? (_rCard.dataset.reportType || 'infra-spend') : 'infra-spend';
  const _isCount = (_reportTypes[_rtype]?.display === 'count');
  const _col0 = _isCount ? 'Metric' : 'Vendor';
  const _col4 = _isCount ? 'Total (90d)' : 'Total (12mo)';
  body.innerHTML = `
    <div class="report-period-tabs" style="margin-bottom:10px;">
      <button class="report-period-tab active" onclick="setReportPeriod('${id}','monthly',this)">Monthly</button>
      <button class="report-period-tab" onclick="setReportPeriod('${id}','weekly',this)">Weekly</button>
      <button class="report-period-tab" onclick="setReportPeriod('${id}','daily',this)">Daily</button>
    </div>
    <div class="report-chart-wrap"><canvas id="rpt-chart-${id}"></canvas></div>
    <table class="report-table">
      <thead><tr><th>${_col0}</th><th style="text-align:right">This Month</th><th style="text-align:right">Last Month</th><th style="text-align:right">${_col4}</th></tr></thead>
      <tbody id="rpt-table-${id}"></tbody>
    </table>
  `;
  body._data = data;
  body._period = 'monthly';
  body._rtype = _rtype;
  _renderReportChart(id, data, 'monthly');
}

function setReportPeriod(id, period, btn) {
  const body = document.getElementById('rpt-body-' + id);
  if (!body || !body._data) return;
  body._period = period;
  body.querySelectorAll('.report-period-tab').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  _renderReportChart(id, body._data, period);
}

function _renderReportChart(id, data, period) {
  const canvas = document.getElementById('rpt-chart-' + id);
  const tbody = document.getElementById('rpt-table-' + id);
  if (!canvas) return;

  const body = document.getElementById('rpt-body-' + id);
  const rtype = body?._rtype || 'infra-spend';
  const vendors = Object.keys(data);
  // Collect all period labels
  const labelSet = new Set();
  vendors.forEach(v => {
    (data[v][period] || []).forEach(p => labelSet.add(p.month || p.week || p.date || ''));
  });
  const labels = [...labelSet].sort().slice(-12);

  // Build datasets
  const datasets = vendors.map(v => {
    const vdata = data[v];
    const pts = {};
    (vdata[period] || []).forEach(p => { pts[p.month || p.week || p.date || ''] = p.amount || 0; });
    return {
      label: _vendorLabel(rtype, v),
      data: labels.map(l => pts[l] || 0),
      backgroundColor: _vendorColor(rtype, v),
      borderRadius: 3,
    };
  });

  // Destroy old chart
  if (_reportCharts[id]) { try { _reportCharts[id].destroy(); } catch(e){} }

  const _isCount = (_reportTypes[rtype]?.display === 'count');
  const _yFmt = _isCount ? (v => v.toLocaleString()) : (v => '$' + v.toFixed(0));
  if (typeof Chart !== 'undefined' && labels.length) {
    _reportCharts[id] = new Chart(canvas, {
      type: 'bar',
      data: { labels, datasets },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { position: 'bottom', labels: { font: { size: 11 }, boxWidth: 12 } } },
        scales: {
          x: { stacked: !_isCount, ticks: { font: { size: 10 }, maxRotation: 45 } },
          y: { stacked: !_isCount, ticks: { font: { size: 10 }, callback: _yFmt } }
        }
      }
    });
  } else if (!labels.length) {
    canvas.parentElement.innerHTML = '<div style="text-align:center;padding:30px 0;color:var(--dim);font-size:0.82rem;">No data available \u2014 click \u21bb to fetch</div>';
  }

  // Table: show per-vendor current month, last month, 12mo total
  if (tbody) {
    const now = new Date();
    const thisMo = now.toISOString().slice(0,7);
    const lastMo = new Date(now.getFullYear(), now.getMonth()-1, 1).toISOString().slice(0,7);
    let rows = '';
    let totThis=0, totLast=0, tot12=0;
    vendors.forEach(v => {
      const vd = data[v];
      const vcolor = _vendorColor(rtype, v);
      const vlabel = _vendorLabel(rtype, v);
      if (vd.error) {
        rows += `<tr><td><span class="report-vendor-dot" style="background:${vcolor}"></span>${vlabel}</td><td colspan="3" class="report-error">${esc(vd.error)}</td></tr>`;
        return;
      }
      const monthly = vd.monthly || [];
      const thisAmt = monthly.find(m=>m.month===thisMo)?.amount||0;
      const lastAmt = monthly.find(m=>m.month===lastMo)?.amount||0;
      const total12 = monthly.slice(-12).reduce((a,m)=>a+m.amount,0);
      totThis+=thisAmt; totLast+=lastAmt; tot12+=total12;
      const _fmt = _isCount ? (v => v.toLocaleString()) : (v => '$' + v.toFixed(2));
      rows += `<tr>
        <td><span class="report-vendor-dot" style="background:${vcolor}"></span>${vlabel}</td>
        <td style="text-align:right">${_fmt(thisAmt)}</td>
        <td style="text-align:right">${_fmt(lastAmt)}</td>
        <td style="text-align:right">${_fmt(total12)}</td>
      </tr>`;
    });
    const _fmtTot = _isCount ? (v => v.toLocaleString()) : (v => '$' + v.toFixed(2));
    rows += `<tr class="report-total">
      <td>Total</td>
      <td style="text-align:right">${_fmtTot(totThis)}</td>
      <td style="text-align:right">${_fmtTot(totLast)}</td>
      <td style="text-align:right">${_fmtTot(tot12)}</td>
    </tr>`;
    tbody.innerHTML = rows;
  }
}

async function refreshReport(id) {
  const btn = document.getElementById('rpt-refresh-btn-' + id);
  if (btn) { btn.classList.add('spinning'); btn.disabled = true; }
  try {
    const r = await fetch(API + '/api/reports/' + id + '/refresh', { method: 'POST' });
    const d = await r.json();
    if (d.data) {
      await loadReportData(id, d.data);
      const ts = document.getElementById('rpt-refresh-ts-' + id);
      if (ts && d.refreshed_at) ts.textContent = 'Updated ' + _fmtRelTime(d.refreshed_at);
    }
  } finally {
    if (btn) { btn.classList.remove('spinning'); btn.disabled = false; }
  }
}

async function deleteReport(id) {
  if (!await showConfirm('Delete this report?', 'Delete', true)) return;
  await fetch(API + '/api/reports/' + id, { method: 'DELETE' });
  fetchReports();
}

function _populateAddReportModal() {
  const typeSelect = document.getElementById('add-report-type');
  typeSelect.innerHTML = Object.entries(_reportTypes).map(([id, t]) =>
    `<option value="${id}">${esc(t.label)}</option>`
  ).join('') || '<option value="infra-spend">Infrastructure Spend</option>';
  _updateAddReportVendors();
}
function _updateAddReportVendors() {
  const typeId = document.getElementById('add-report-type').value;
  const vendors = _reportTypes[typeId]?.vendors || {};
  const grp = document.getElementById('add-report-vendors-group');
  const entries = Object.entries(vendors);
  if (!entries.length) { grp.style.display = 'none'; return; }
  grp.style.display = '';
  grp.querySelector('div').innerHTML = entries.map(([vid, vm]) =>
    `<label style="display:flex;align-items:center;gap:5px;font-size:0.82rem;">` +
    `<input type="checkbox" value="${vid}" checked> ${esc(vm.label)}</label>`
  ).join('');
}
function openAddReport() {
  _populateAddReportModal();
  document.getElementById('add-report-overlay').style.display = 'flex';
  document.getElementById('add-report-name').focus();
}
function closeAddReport() {
  document.getElementById('add-report-overlay').style.display = 'none';
}
async function submitAddReport() {
  const name = document.getElementById('add-report-name').value.trim() || 'New Report';
  const type = document.getElementById('add-report-type').value;
  const vendors = [...document.querySelectorAll('#add-report-vendors-group input[type=checkbox]:checked')].map(c=>c.value);
  closeAddReport();
  await fetch(API + '/api/reports', {
    method: 'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({name, type, config:{vendors}})
  });
  fetchReports();
}

function _fmtRelTime(ts) {
  const diff = Math.floor(Date.now()/1000) - ts;
  if (diff < 60) return 'just now';
  if (diff < 3600) return Math.floor(diff/60) + 'm ago';
  if (diff < 86400) return Math.floor(diff/3600) + 'h ago';
  return Math.floor(diff/86400) + 'd ago';
}

// ═══════ BOARD ═══════
let activeView = 'sessions';
let boardItems = [];
// Archived cards are fetched LAZILY (AMUX-2271). They are 1577 of 1624 rows and
// 97% of the payload, and the board hides them everywhere unless something asks
// for them: `_bqWantsArchived` for the global board, the per-session peek panel
// for one lane. Loading them up front cost 4.7MB on every client, forever, to
// render nothing. `boardArchived` is kept SEPARATE from `boardItems` so the
// ETag/lastBoardJSON comparison keeps working on the non-archived payload
// alone; `_mergeArchived` re-joins them after each fetch, with the fresh
// non-archived record winning on id so an un-archived card cannot show twice.
let boardArchived = [];
let _archivedAt = 0;
let _archivedLoading = null;
function _mergeArchived(data) {
  if (!boardArchived.length) return data;
  const have = new Set(data.map(i => i.id));
  return data.concat(boardArchived.filter(i => !have.has(i.id)));
}
async function _ensureArchived() {
  // One in-flight fetch at a time; refresh at most once a minute, since the
  // age-archive sweep only moves cards every few hours.
  if (_archivedLoading) return _archivedLoading;
  if (boardArchived.length && (Date.now() - _archivedAt) < 60000) return;
  _archivedLoading = (async () => {
    try {
      const r = await fetch(API + '/api/board?archived=1&done_limit=0&full=1');
      const d = await r.json();
      if (Array.isArray(d)) {
        boardArchived = d.filter(i => i.archived);
        _archivedAt = Date.now();
        boardItems = _mergeArchived(boardItems.filter(i => !i.archived));
        renderBoard();
        if (typeof renderPeekIssues === 'function' && document.getElementById('peek-issues-list')) {
          try { renderPeekIssues(); } catch (e) {}
        }
      }
    } catch (e) { console.error('fetch archived:', e); }
    finally { _archivedLoading = null; }
  })();
  return _archivedLoading;
}
