// ── Team / Org / Invites ──────────────────────────────────────────────────────
async function loadTeamSection() {
  try {
    const list = document.getElementById('settings-members-list');
    if (!list) return;

    if (_cloudEmail) {
      // Cloud mode: use gateway-level members
      const [membersRes, invitesRes, orgRes] = await Promise.all([
        fetch('/api/gateway/members'), fetch('/api/org/invites'), fetch('/api/org')
      ]);
      if (orgRes.ok) {
        const org = await orgRes.json();
        const nameEl = document.getElementById('settings-org-name');
        if (nameEl && nameEl !== document.activeElement) nameEl.value = org.name || '';
      }
      const members = membersRes.ok ? await membersRes.json() : [];
      const invites = invitesRes.ok ? await invitesRes.json() : [];
      let html = '';
      if (members.length) {
        html += members.map(m => `
          <div style="display:flex;justify-content:space-between;align-items:center;padding:3px 0;border-bottom:1px solid var(--border);">
            <span style="font-size:0.78rem;">${esc(m.email || 'Unknown')}</span>
            <span style="color:var(--dim);font-size:0.68rem;">member</span>
          </div>`).join('');
      }
      if (invites.length) {
        html += '<div style="margin-top:4px;font-size:0.68rem;color:var(--dim);">Pending invites:</div>';
        html += invites.map(inv => `
          <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0;">
            <span style="font-size:0.72rem;color:var(--dim);">expires ${new Date(inv.expires_at*1000).toLocaleDateString()}</span>
            <button onclick="deleteInvite('${esc(inv.token)}')" style="background:none;border:none;color:var(--dim);cursor:pointer;font-size:0.65rem;">revoke</button>
          </div>`).join('');
      }
      list.innerHTML = html || '<span style="color:var(--dim);font-size:0.75rem;">No members yet — invite someone!</span>';
    } else {
      // Local mode: use container-level org
      const [orgRes, membersRes] = await Promise.all([
        fetch('/api/org'), fetch('/api/org/members')
      ]);
      const org = await orgRes.json();
      const members = await membersRes.json();
      const nameEl = document.getElementById('settings-org-name');
      if (nameEl && nameEl !== document.activeElement) nameEl.value = org.name || '';
      if (!members.length) {
        list.innerHTML = '<span style="color:var(--dim);font-size:0.75rem;">No members yet — invite someone!</span>';
      } else {
        list.innerHTML = members.map(m => `
          <div style="display:flex;justify-content:space-between;align-items:center;padding:3px 0;border-bottom:1px solid var(--border);">
            <span>${esc(m.name || m.email)}</span>
            <span style="color:var(--dim);font-size:0.7rem;">${m.role}</span>
          </div>`).join('');
      }
    }
  } catch(e) {}
}

async function deleteInvite(token) {
  // Confirm at the response, not on faith — the old swallowed catch toasted
  // "Invite revoked" even when the DELETE never landed.
  const r = await fetch('/api/org/invites/' + token, {method: 'DELETE'}).catch(() => null);
  if (!r || !r.ok) { showToast('Failed to revoke invite'); return; }
  showToast('Invite revoked');
  loadTeamSection();
}

async function saveOrgName(val) {
  val = val.trim();
  if (!val) return;
  await fetch('/api/org', {method:'PATCH', headers:{'Content-Type':'application/json'}, body: JSON.stringify({name: val})});
}

async function openTeamInvite() {
  closeSettings();
  const res = await fetch('/api/org/invites', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({})});
  const data = await res.json();
  if (!data.url) { showAlert('Failed to create invite: ' + (data.error || 'unknown error')); return; }
  // Show modal with copyable link
  const modal = document.createElement('div');
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);display:flex;align-items:center;justify-content:center;z-index:9999;';
  modal.innerHTML = `<div style="background:var(--bg2,#1a1a1a);border:1px solid var(--border,#333);border-radius:12px;padding:28px;max-width:480px;width:90%;box-sizing:border-box;max-height:min(90dvh,calc(100dvh - 24px));overflow-y:auto;overscroll-behavior:contain;">
    <h3 style="margin:0 0 8px;font-size:1rem;">Invite to workspace</h3>
    <p style="color:var(--dim);font-size:0.82rem;margin:0 0 14px;">Share this link. It expires in 7 days.</p>
    <div style="display:flex;gap:8px;">
      <input id="invite-link-input" type="text" value="${data.url}" readonly
        style="flex:1;padding:8px 10px;border-radius:6px;border:1px solid var(--border,#333);background:var(--bg,#111);color:inherit;font-size:0.8rem;min-width:0;">
      <button onclick="(function(){var el=document.getElementById('invite-link-input');el.select();navigator.clipboard.writeText(el.value).then(()=>{this.textContent='Copied!';setTimeout(()=>this.textContent='Copy',1500)})}).call(this)"
        style="padding:8px 14px;border-radius:6px;background:var(--accent,#a78bfa);color:#000;border:none;cursor:pointer;font-weight:600;white-space:nowrap;">Copy</button>
    </div>
    <div style="margin-top:16px;text-align:right;">
      <button onclick="this.closest('div[style*=fixed]').remove()"
        style="padding:6px 18px;border-radius:6px;background:var(--bg3,#222);border:1px solid var(--border,#333);color:#ddd;cursor:pointer;">Done</button>
    </div>
  </div>`;
  document.body.appendChild(modal);
  modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
  // Auto-copy
  setTimeout(() => { try { navigator.clipboard.writeText(data.url); } catch(e) {} }, 100);
}

// ── Billing ─────────────────────────────────────────────────────────────────
async function loadBillingSection() {
  const sec = document.getElementById('settings-billing-section');
  const sep = document.getElementById('settings-billing-sep');
  const info = document.getElementById('settings-billing-info');
  if (!sec || !info) return;
  try {
    const r = await fetch('/api/stripe/status');
    if (!r.ok) { sec.style.display = 'none'; if (sep) sep.style.display = 'none'; return; }
    const d = await r.json();
    if (!d.stripe_configured) { sec.style.display = 'none'; if (sep) sep.style.display = 'none'; return; }
    sec.style.display = '';
    if (sep) sep.style.display = '';
    if (d.plan === 'pro') {
      let statusText = 'Active subscription';
      if (d.in_trial && d.trial_ends_at) {
        const days = Math.ceil((d.trial_ends_at * 1000 - Date.now()) / 86400000);
        statusText = 'Trial \u2014 ' + days + ' day' + (days !== 1 ? 's' : '') + ' remaining';
      }
      info.innerHTML = '<div style="display:flex;align-items:center;gap:8px;">' +
        '<span style="background:var(--accent);color:#000;border-radius:4px;padding:1px 8px;font-size:0.72rem;font-weight:600;">PRO</span>' +
        '<span>' + statusText + '</span></div>' +
        (d.has_billing ? '<button class="btn" style="font-size:0.7rem;padding:3px 10px;margin-top:8px;" onclick="openBillingPortal()">Manage billing</button>' : '');
    } else {
      const trialNote = d.trial_days ? '<div style="font-size:0.72rem;color:var(--green,#3fb950);margin-bottom:10px;">' + d.trial_days + '-day free trial included</div>' : '';
      const annualBtn = d.has_annual
        ? '<button class="btn primary" style="font-size:0.78rem;padding:5px 16px;" onclick="startCheckout(\'annual\')">Annual \u2014 $200/yr (save 17%)</button>'
        : '';
      info.innerHTML =
        '<div style="margin-bottom:10px;">Free plan</div>' +
        trialNote +
        '<div style="display:flex;flex-direction:column;gap:8px;">' +
          '<div style="background:var(--card,#1e1e2e);border:1px solid var(--border,#333);border-radius:8px;padding:12px;">' +
            '<div style="font-weight:600;color:var(--text);margin-bottom:4px;">Pro Monthly \u2014 $20/mo</div>' +
            '<div style="font-size:0.72rem;color:var(--dim);margin-bottom:8px;">Unlimited workers \u00b7 No idle timeout \u00b7 Team workspaces</div>' +
            '<button class="btn primary" style="font-size:0.78rem;padding:5px 16px;" onclick="startCheckout(\'monthly\')">Start free trial</button>' +
          '</div>' +
          (d.has_annual ? '<div style="background:var(--card,#1e1e2e);border:1px solid var(--accent,#7c6fcd);border-radius:8px;padding:12px;">' +
            '<div style="font-weight:600;color:var(--text);margin-bottom:4px;">Pro Annual \u2014 $200/yr <span style="color:var(--green,#3fb950);font-size:0.72rem;">save 17%</span></div>' +
            '<div style="font-size:0.72rem;color:var(--dim);margin-bottom:8px;">Same features \u00b7 $16.67/mo effective</div>' +
            '<button class="btn primary" style="font-size:0.78rem;padding:5px 16px;" onclick="startCheckout(\'annual\')">Start free trial</button>' +
          '</div>' : '') +
        '</div>' +
        (d.has_billing ? '<button class="btn" style="font-size:0.7rem;padding:3px 10px;margin-top:8px;" onclick="openBillingPortal()">Manage billing</button>' : '');
    }
  } catch(e) { sec.style.display = 'none'; if (sep) sep.style.display = 'none'; }
}

async function startCheckout(billing) {
  billing = billing || 'monthly';
  try {
    const r = await fetch('/api/stripe/checkout', {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ billing })
    });
    const d = await r.json();
    if (d.url) location.href = d.url;
    else alert(d.error || 'Failed to start checkout');
  } catch(e) { alert('Connection error'); }
}

async function openBillingPortal() {
  try {
    const r = await fetch('/api/stripe/portal', { method: 'POST' });
    const d = await r.json();
    if (d.url) location.href = d.url;
    else alert(d.error || 'No billing account');
  } catch(e) { alert('Connection error'); }
}

// Load team + API keys + billing whenever settings opens
const _origToggleSettings = toggleSettings;
toggleSettings = function() {
  _origToggleSettings();
  const menu = document.getElementById('settings-menu');
  if (menu && menu.style.display !== 'none') {
    loadTeamSection();
    loadApiKeys();
    loadBillingSection();
  }
};

// invite_token param is now handled server-side by gateway (redirect → /invite/<token> accept page)
// Just clean it from URL if somehow present
(function() {
  const params = new URLSearchParams(location.search);
  if (params.has('invite_token')) {
    params.delete('invite_token');
    history.replaceState({}, '', location.pathname + (params.toString() ? '?' + params.toString() : ''));
  }
})();

// Deep-link: #path=/some/path (or ?path= for backwards compat)
// Hash-based routing works in PWA mode — SW never strips fragments, no iOS query-param loss
async function _handleDeeplink(hash) {
  // #view=<tab> (or ?view=<tab>) — land on a top-level view directly. Rig
  // deeplink like #peek= below: simulator verification needs to reach a TAB on
  // real WebKit without tap automation (the Groups tab shipped with no way to
  // open it headlessly). The query form exists because `simctl openurl` does
  // not reliably deliver a #fragment to an already-open Safari tab — verified
  // 2026-08-08: the reload hit the server, the hash never reached the page.
  // The walkthrough stands down for any '='-bearing hash; ?view= is handled
  // in its gate as well.
  if ((!hash || hash.indexOf('=') < 0) && location.search) {
    const m = location.search.match(/[?&]view=([^&]+)/);
    if (m) hash = '#view=' + m[1];
  }
  if (hash && hash.startsWith('#view=')) {
    const v = decodeURIComponent(hash.slice(6));
    // Deferred like #peek= below: this runs from the early inline script,
    // where switchView still null-derefs on #grid-view (parsed later). A bare
    // try/catch here SWALLOWED that throw and the deeplink silently no-oped —
    // the same half-boot trap _restoreScreen's own comment documents.
    const tryView = (attempt) => {
      if (document.getElementById('grid-view') && document.getElementById('tab-' + v)) {
        try { switchView(v); } catch(e) {}
        return;
      }
      if (attempt < 25) setTimeout(() => tryView(attempt + 1), 200);
    };
    tryView(0);
    return;
  }
  // #peek=<session>[&tab=<tab>] — open a session's peek directly, optionally on
  // a specific tab (shareable links; also lets headless/simulator test rigs land
  // exactly where they need to without tap automation, which is how the PWA gets
  // verified on a real iOS WebKit rather than a desktop approximation).
  if (hash && hash.startsWith('#peek=')) {
    const raw = hash.slice(6);
    const amp = raw.indexOf('&');
    const target = decodeURIComponent(amp < 0 ? raw : raw.slice(0, amp));
    let tab = '';
    if (amp >= 0) {
      const m = raw.slice(amp + 1).match(/(?:^|&)tab=([^&]+)/);
      if (m) tab = decodeURIComponent(m[1]);
    }
    const tryOpen = (attempt) => {
      // `sessions` (b009f6e's THIRD casualty): `typeof workers` was undefined
      // forever, so tryOpen polled out its 20 attempts and every #peek= link
      // silently no-oped — masked until the peekState-restore stand-down
      // removed the fallback that happened to open A peek (the wrong one).
      if (typeof sessions !== 'undefined' && sessions.some(s => s.name === target)) {
        openPeek(target);
        // Let openPeek finish its own async setup before switching tabs.
        if (tab) setTimeout(() => { try { setPeekTab(tab); } catch(e) {} }, 350);
        return;
      }
      if (attempt < 20) setTimeout(() => tryOpen(attempt + 1), 400);
    };
    tryOpen(0);
    return;
  }
  // #menu=<session>[&scroll=N] — open a session card's ⋯ menu directly. Rig
  // deeplink like #peek= above (AMUX-1731): the menu detaches on iPhone, the
  // geometry beacon lives in toggleMenu, and a real-WebKit reproduction needs
  // to drive the SHIPPED function without tap automation. scroll=N scrolls
  // the list first so scrolled-state geometry is what gets measured.
  if (hash && hash.startsWith('#menu=')) {
    const raw = hash.slice(6);
    const amp = raw.indexOf('&');
    const target = decodeURIComponent(amp < 0 ? raw : raw.slice(0, amp));
    let scrollN = 0;
    if (amp >= 0) { const m = raw.slice(amp + 1).match(/(?:^|&)scroll=(\d+)/); if (m) scrollN = parseInt(m[1]); }
    const tryMenu = (attempt) => {
      const el = document.getElementById('menu-' + target);
      if (el) {
        if (scrollN) window.scrollTo(0, scrollN);
        setTimeout(() => { try { toggleMenu(target); } catch(e) {} }, 250);
        return;
      }
      if (attempt < 20) setTimeout(() => tryMenu(attempt + 1), 400);
    };
    tryMenu(0);
    return;
  }
  // #issue=<id> — open a board card directly from anywhere (AMUX-2165), the
  // shareable twin of the task-label id chip.
  if (hash && hash.startsWith('#issue=')) {
    const id = decodeURIComponent(hash.slice(7));
    const tryOpen = (attempt) => {
      if (typeof boardItems !== 'undefined' && boardItems.some(i => i.id === id)) {
        switchView('board');
        setTimeout(() => { try { openBoardDetail(id); } catch (e) {} }, 250);
        return;
      }
      if (attempt < 20) setTimeout(() => tryOpen(attempt + 1), 400);
    };
    tryOpen(0);
    return;
  }
  // #browser=<session> — land in the Browser view focused on a given session's
  // live browser (AMUX-3073). This is the "click here to sign in" resume link an
  // agent drops in a needs-you card: there was NO route to a session's browser,
  // and _bwSession was hardcoded to 'amux' with no setter, so a notification
  // could never say where to click and an agent's only fallback was to ask in
  // chat (amux-gtm asked ~6x in one day). Sets the session, opens the tab, and
  // starts the live view so the human sees the page awaiting sign-in at once.
  if (hash && hash.startsWith('#browser=')) {
    const raw = hash.slice(9);
    const amp = raw.indexOf('&');
    const sess = decodeURIComponent(amp < 0 ? raw : raw.slice(0, amp));
    const tryOpen = (attempt) => {
      // Defer the _bwSession assignment into the poll: at initial page load
      // _handleDeeplink runs (line ~26113) BEFORE the `let _bwSession` at ~29910
      // is initialized, so a direct assign here throws in the temporal dead
      // zone. By the time this setTimeout fires the whole script has executed.
      if (document.getElementById('browser-view') && document.getElementById('tab-browser')) {
        if (sess) { try { _bwSession = sess; } catch(e) {} }
        try { switchView('browser'); } catch(e) {}   // calls _bwInit()
        try { _bwSessionLabelSync(); } catch(e) {}
        setTimeout(() => { try { _bwSetLive(true); } catch(e) {} }, 250);
        return;
      }
      if (attempt < 25) setTimeout(() => tryOpen(attempt + 1), 200);
    };
    tryOpen(0);
    return;
  }
  let dpath = null;
  if (hash && hash.startsWith('#path=')) {
    dpath = decodeURIComponent(hash.slice(6));
  } else {
    dpath = new URLSearchParams(location.search).get('path');
    // Migrate old ?path= links to hash format
    if (dpath) history.replaceState({}, '', location.pathname + '#path=' + _encodeHashPath(dpath));
  }
  if (!dpath) return;
  try {
    const r = await fetch(API + '/api/ls?path=' + encodeURIComponent(dpath));
    const d = await r.json();
    if (d.error === 'not a directory') {
      const parent = dpath.split('/').slice(0, -1).join('/') || '/';
      _filesPath = parent;
      switchView('files');
      openFilePreview(dpath);
    } else if (!d.error) {
      _filesPath = dpath;
      switchView('files');
    }
  } catch(e) {}
}
// On page load
_handleDeeplink(location.hash);
// Restore the screen you were on — INCLUDING after iOS evicts a backgrounded
// PWA (which wipes sessionStorage but keeps localStorage): the active tab and
// any open session peek. Bounded to 24h so a days-later open still lands on a
// sane default rather than a stale heavy tab.
const _UI_RESTORE_MAX_AGE = 24 * 3600 * 1000;
function _restoreScreen() {
  // Must run AFTER the DOM is parsed: switchView touches #grid-view, which is
  // defined later in the HTML than this inline script — calling it during boot
  // (setTimeout 0) null-derefs and throws. The app never calls switchView on
  // load (it relies on the hardcoded default tab), so ours is the first.
  // Don't override an explicit deeplink: a file link (#path=) or a view link
  // (#view= / ?view=, the rig entry). The saved-tab restore silently beat the
  // view deeplink on 2026-08-08 — the rig asked for ?view=groups, got last
  // session's Workers tab, and the deeplink looked broken while working fine.
  const _hasDeeplink = (location.hash && (location.hash.startsWith('#path=')
                                          || location.hash.startsWith('#view=')
                                          || location.hash.startsWith('#browser=')))
                     || /[?&]view=/.test(location.search);
  // 1. Restore the tab.
  if (!_hasDeeplink) {
    try {
      const _v = JSON.parse(localStorage.getItem('amux_ui_view') || 'null');
      // Only restore a view whose nav tab still EXISTS. localStorage outlives
      // the feature it names: when the notes view was deleted, browsers that had
      // last been on it kept restoring 'notes' into a dispatcher that no longer
      // had a branch for it. The catch below then hid the failure while
      // switchView had already set activeView, leaving a half-switched UI. This
      // is the general case, not a notes special-case — any view we remove later
      // is stale in someone's localStorage the moment it ships.
      if (_v && _v.v && _v.v !== 'workers' && (Date.now() - (_v.ts || 0) < _UI_RESTORE_MAX_AGE)
          && document.getElementById('tab-' + _v.v)) {
        try { switchView(_v.v); } catch(e) {}
      }
    } catch(e) {}
  }
  // 2. Restore an open session peek. Prefer sessionStorage (same tab session);
  //    fall back to localStorage when we came back after an eviction.
  //    A #peek= deeplink names its own target — restoring the LAST peek over
  //    it made the rig land on whichever session was peeked before (verified
  //    2026-08-08: #peek=amux opened amux-frustrations), and a shared link
  //    would misdirect the same way.
  if (location.hash && location.hash.startsWith('#peek=')) return;
  let _ps = null;
  try { _ps = JSON.parse(sessionStorage.getItem('peekState') || 'null'); } catch(e) {}
  if (!_ps || !_ps.session) {
    try {
      const _lp = JSON.parse(localStorage.getItem('amux_peek_state') || 'null');
      if (_lp && _lp.session && (Date.now() - (_lp.ts || 0) < _UI_RESTORE_MAX_AGE)) _ps = _lp;
    } catch(e) {}
  }
  if (_ps && _ps.session) {
    setTimeout(() => {
      openPeek(_ps.session);
      // Restore the tab WITHIN the peek — guarded on the button still
      // existing, because localStorage outlives removed tabs (the notes-view
      // lesson above applies one level down).
      if (_ps.tab && _ps.tab !== 'terminal') {
        setTimeout(() => {
          if (peekSession === _ps.session && document.getElementById('peek-tab-' + _ps.tab)) {
            try { setPeekTab(_ps.tab); } catch(e) {}
          }
        }, 350);
      }
      if (_ps.split && window.innerWidth > 600) {
        setTimeout(() => {
          const wrap = document.getElementById('peek-split-wrap');
          const btn = document.getElementById('peek-split-toggle');
          if (wrap) wrap.classList.add('split-active');
          if (btn) btn.classList.add('active');
          _psfLoad(_ps.splitPath || peekSessionDir || '/');
        }, 300);
      }
    }, 200);
  }
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', _restoreScreen);
else _restoreScreen();
// On hash change (e.g. paste URL into address bar while app already open — no page reload)
window.addEventListener('hashchange', () => _handleDeeplink(location.hash));

function forceUpdate() {
  const el = document.getElementById('update-status');
  el.textContent = 'Updating...';
  if (!('serviceWorker' in navigator)) {
    location.reload(true);
    return;
  }
  navigator.serviceWorker.getRegistration().then(reg => {
    if (!reg) { location.reload(true); return; }
    reg.update().then(() => {
      if (reg.waiting) {
        reg.waiting.postMessage({type: 'SKIP_WAITING'});
      }
      caches.keys().then(keys => Promise.all(keys.map(k => caches.delete(k)))).then(() => {
        el.textContent = 'Cache cleared, reloading...';
        setTimeout(() => location.reload(true), 300);
      });
    }).catch(() => {
      el.textContent = 'Update failed, reloading...';
      setTimeout(() => location.reload(true), 300);
    });
  });
}

async function pullFromRemote(btn) {
  const el = document.getElementById('pull-status');
  btn.disabled = true; btn.textContent = '⏳ Pulling...';
  el.textContent = '';
  // `r` is declared out here so the catch can tell a transport failure (no response
  // at all) from a response we could not parse. The old code could not: it reported
  // BOTH as 'Network error', so a 405 with an empty body — what a build without
  // /api/pull actually returns — sent the reader to check their wifi.
  let r = null;
  try {
    r = await fetch(API + '/api/pull', { method: 'POST' });
    // Read as text first. r.json() throws on an empty body, and that throw is
    // indistinguishable from a network fault once it reaches the catch.
    const body = await r.text();
    let d = null;
    try { d = JSON.parse(body); } catch (_) { /* handled below, with the status */ }

    if (d) {
      el.textContent = d.output || (d.ok ? 'Up to date' : 'Failed');
      el.style.color = d.ok ? 'var(--green)' : 'var(--red)';
      if (d.ok && !(d.output || '').includes('Already up to date')) {
        setTimeout(() => forceUpdate(), 1500);
      }
      return;
    }

    // Responded, but not with JSON. Say what actually came back.
    const snippet = body.trim().slice(0, 200);
    el.textContent = 'HTTP ' + r.status + (r.statusText ? ' ' + r.statusText : '') +
      (snippet ? ': ' + snippet
               : ' (empty body) — this build may not serve /api/pull');
    el.style.color = 'var(--red)';
  } catch (e) {
    // Only a genuine transport failure can reach here now.
    el.textContent = (r ? 'Failed reading response: ' : 'Network error: ') + e.message;
    el.style.color = 'var(--red)';
  } finally {
    // finally, because the success path now returns early.
    btn.disabled = false; btn.textContent = '⬇ Pull from remote';
  }
}

// ── DevTools Panel ──────────────────────────────────────────────
(function() {
  const MAX_LOG = 500;
  const MAX_NET = 200;
  let _dtLogs = [];
  let _dtNet  = [];
  let _dtOpen = false;
  let _dtTab  = 'console';
  let _dtReplHist = [];
  let _dtReplIdx  = -1;

  // ── Console override ──
  const _origConsole = {};
  ['log','info','warn','error','debug'].forEach(level => {
    _origConsole[level] = console[level].bind(console);
    console[level] = function(...args) {
      _origConsole[level](...args);
      const text = args.map(a => {
        try { return (typeof a === 'object' && a !== null) ? JSON.stringify(a, null, 2) : String(a); }
        catch(e) { return String(a); }
      }).join(' ');
      _dtLogPush(level === 'debug' ? 'log' : level, text);
    };
  });

  // ── Fetch interception ──
  const _origFetch = window.fetch.bind(window);
  window.fetch = async function(input, init) {
    const method = (init && init.method) ? init.method.toUpperCase() : 'GET';
    const url = typeof input === 'string' ? input : (input.url || String(input));
    const t0 = Date.now();
    let entry = { method, url, status: '…', ms: null, t: new Date().toLocaleTimeString() };
    _dtNet.push(entry);
    if (_dtNet.length > MAX_NET) _dtNet = _dtNet.slice(-MAX_NET);
    if (_dtOpen && _dtTab === 'network') _renderDevNetwork();
    try {
      const res = await _origFetch(input, init);
      entry.status = res.status;
      entry.ms = Date.now() - t0;
      if (_dtOpen && _dtTab === 'network') _renderDevNetwork();
      return res;
    } catch(e) {
      entry.status = 'ERR';
      entry.ms = Date.now() - t0;
      if (_dtOpen && _dtTab === 'network') _renderDevNetwork();
      throw e;
    }
  };

  // ── Clipboard event debug ──
  ['copy','cut','paste'].forEach(evtName => {
    document.addEventListener(evtName, e => {
      const ae = document.activeElement;
      const aeDesc = ae ? `${ae.tagName}#${ae.id || ''}${ae.className ? '.'+ae.className.split(' ')[0] : ''}` : 'none';
      let extra = '';
      if (evtName === 'paste' && e.clipboardData) {
        extra = ' types=[' + Array.from(e.clipboardData.types).join(',') + ']';
      }
      _dtLogPush('info', `[clipboard] ${evtName}${extra} — target=${e.target && e.target.tagName} activeEl=${aeDesc}`);
    }, true); // capture phase
  });

  // ── Keyboard debug (Cmd+C/V/X) — capture AND bubble phase ──
  const _watchKeys = new Set(['c','v','x','z']);
  document.addEventListener('keydown', e => {
    if ((e.metaKey || e.ctrlKey) && _watchKeys.has(e.key.toLowerCase())) {
      const ae = document.activeElement;
      const aeDesc = ae ? `${ae.tagName}#${ae.id || ''}` : 'none';
      const isEditable = ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.isContentEditable);
      _dtLogPush('log', `[key:capture] ${e.metaKey?'Cmd':'Ctrl'}+${e.key} focus=${aeDesc} editable=${isEditable} defaultPrevented=${e.defaultPrevented}`);
      // schedule a microtask to log after handlers run
      Promise.resolve().then(() => {
        _dtLogPush('log', `[key:after] ${e.metaKey?'Cmd':'Ctrl'}+${e.key} defaultPrevented=${e.defaultPrevented}`);
      });
    }
  }, true);

  // ── Internal log push ──
  function _dtLogPush(level, text) {
    _dtLogs.push({ level, text, t: new Date().toLocaleTimeString() });
    if (_dtLogs.length > MAX_LOG) _dtLogs = _dtLogs.slice(-MAX_LOG);
    if (_dtOpen && _dtTab === 'console') _renderDevLogs();
  }

  // ── Render helpers ──
  function _renderDevLogs() {
    const el = document.getElementById('dt-log-area');
    if (!el) return;
    const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 10;
    el.innerHTML = _dtLogs.map(e => {
      const cls = e.level === 'error' ? 'error' : e.level === 'warn' ? 'warn' : e.level === 'info' ? 'info' : '';
      const escaped = e.text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
      return `<div class="dt-entry ${cls}"><span class="dt-ts">${e.t}</span> ${escaped}</div>`;
    }).join('');
    if (atBottom) el.scrollTop = el.scrollHeight;
  }

  function _renderDevNetwork() {
    const el = document.getElementById('dt-net-area');
    if (!el) return;
    const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 10;
    el.innerHTML = _dtNet.slice().reverse().map(e => {
      const statusCls = (e.status >= 400 || e.status === 'ERR') ? 'error' : (e.status === '…') ? 'pending' : 'ok';
      const shortUrl = e.url.replace(/^https?:\/\/[^/]+/, '');
      return `<div class="dt-net-entry">` +
        `<span class="dt-net-method">${e.method}</span>` +
        `<span class="dt-net-status ${statusCls}">${e.status}</span>` +
        `<span class="dt-net-url" title="${e.url}">${shortUrl}</span>` +
        `<span class="dt-net-ms">${e.ms !== null ? e.ms+'ms' : ''}</span>` +
        `<span class="dt-ts">${e.t}</span>` +
      `</div>`;
    }).join('');
    if (atBottom) el.scrollTop = el.scrollHeight;
  }

  function _renderDevInfo() {
    const el = document.getElementById('dt-info-area');
    if (!el) return;
    const sw = navigator.serviceWorker;
    const rows = [
      ['Standalone (PWA)', navigator.standalone !== undefined ? String(navigator.standalone) : (window.matchMedia('(display-mode: standalone)').matches ? 'true (display-mode)' : 'false')],
      ['User Agent', navigator.userAgent],
      ['Platform', navigator.platform || navigator.userAgentData?.platform || '?'],
      ['Viewport', `${window.innerWidth}×${window.innerHeight} (dpr=${devicePixelRatio})`],
      ['Online', String(navigator.onLine)],
      ['SW supported', String('serviceWorker' in navigator)],
      ['SW controller', sw && sw.controller ? sw.controller.scriptURL : 'none'],
      ['SW state', sw && sw.controller ? sw.controller.state : 'n/a'],
      ['IndexedDB', String('indexedDB' in window)],
      ['Clipboard API', String('clipboard' in navigator)],
      ['clipboard.read', String(!!(navigator.clipboard && navigator.clipboard.read))],
      ['clipboard.write', String(!!(navigator.clipboard && navigator.clipboard.write))],
      ['Permissions API', String('permissions' in navigator)],
      ['amux version', (document.querySelector('meta[name="amux-version"]') || {content:'?'}).content],
    ];
    el.innerHTML = rows.map(([k,v]) =>
      `<div class="dt-info-row"><span class="dt-info-key">${k}</span><span class="dt-info-val">${v}</span></div>`
    ).join('');
  }

  // ── REPL history ──
  window.dtReplHistUp = function(inp) {
    if (!_dtReplHist.length) return;
    if (_dtReplIdx === -1) _dtReplIdx = _dtReplHist.length - 1;
    else if (_dtReplIdx > 0) _dtReplIdx--;
    inp.value = _dtReplHist[_dtReplIdx];
  };
  window.dtReplHistDown = function(inp) {
    if (_dtReplIdx === -1) return;
    if (_dtReplIdx < _dtReplHist.length - 1) { _dtReplIdx++; inp.value = _dtReplHist[_dtReplIdx]; }
    else { _dtReplIdx = -1; inp.value = ''; }
  };

  // ── Public API ──
  window.openDevtools = function() {
    _dtOpen = true;
    const panel = document.getElementById('devtools-panel');
    if (panel) panel.classList.add('open');
    dtSwitchTab(_dtTab);
  };

  window.closeDevtools = function() {
    _dtOpen = false;
    const panel = document.getElementById('devtools-panel');
    if (panel) panel.classList.remove('open');
  };

  window.dtSwitchTab = function(tab) {
    _dtTab = tab;
    document.querySelectorAll('.dt-tab').forEach(b => b.classList.toggle('active', b.textContent.toLowerCase() === tab));
    document.querySelectorAll('.dt-panel').forEach(p => p.classList.toggle('active', p.id === 'dt-panel-' + tab));
    if (tab === 'console') _renderDevLogs();
    else if (tab === 'network') _renderDevNetwork();
    else if (tab === 'info') _renderDevInfo();
  };

  window.dtClearConsole = function() {
    _dtLogs = [];
    _renderDevLogs();
  };

  window.dtEval = function(code) {
    if (!code.trim()) return;
    _dtReplHist.push(code);
    _dtReplIdx = -1;
    _dtLogPush('log', '> ' + code);
    try {
      // eslint-disable-next-line no-eval
      const result = (0, eval)(code);
      const out = (result === undefined) ? 'undefined' :
                  (typeof result === 'object' && result !== null) ? JSON.stringify(result, null, 2) : String(result);
      _dtLogPush('info', '← ' + out);
    } catch(e) {
      _dtLogPush('error', '✗ ' + e.message);
    }
  };

  // ── Resize handle ──
  document.addEventListener('DOMContentLoaded', () => {
    const handle = document.getElementById('dt-resize-handle');
    const panel  = document.getElementById('devtools-panel');
    if (!handle || !panel) return;
    let dragging = false, startY = 0, startH = 0;
    handle.addEventListener('mousedown', e => {
      dragging = true;
      startY = e.clientY;
      startH = panel.offsetHeight;
      document.body.style.userSelect = 'none';
      e.preventDefault();
    });
    document.addEventListener('mousemove', e => {
      if (!dragging) return;
      const delta = startY - e.clientY;
      const newH = Math.max(120, Math.min(window.innerHeight * 0.8, startH + delta));
      panel.style.height = newH + 'px';
    });
    document.addEventListener('mouseup', () => {
      if (dragging) { dragging = false; document.body.style.userSelect = ''; }
    });
  });

  // log startup
  _dtLogPush('info', '[devtools] Panel initialised — ' + new Date().toLocaleString());
})();

