function _metricsGaugeCls(pct) {
  return pct < 50 ? 'low' : pct < 80 ? 'mid' : 'high';
}

function _metricsGaugeColor(cls) {
  return cls === 'low' ? '#3fb950' : cls === 'mid' ? '#f0a742' : '#f85149';
}

function _metricsFormatUptime(s) {
  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60);
  return d > 0 ? d + 'd ' + h + 'h' : h > 0 ? h + 'h ' + m + 'm' : m + 'm';
}

function _metricsRelTime(ts) {
  if (!ts) return '\u2014';
  try {
    const diff = (Date.now() - new Date(ts).getTime()) / 1000;
    if (diff < 60) return 'just now';
    if (diff < 3600) return Math.floor(diff / 60) + 'm ago';
    if (diff < 86400) return Math.floor(diff / 3600) + 'h ago';
    return Math.floor(diff / 86400) + 'd ago';
  } catch(e) { return ts; }
}

// Network speed test
let _metricsSpeedtestSize = 10 * 1024 * 1024;  // 10 MB per direction
let _metricsSpeedtestRunning = false;
let _metricsSpeedtestResult = null;  // { down: Mbps, up: Mbps, ping: ms }

function _metricsResetSpeedtest() {
  _metricsSpeedtestResult = null;
  const down = document.getElementById('speedtest-down');
  const up = document.getElementById('speedtest-up');
  const ping = document.getElementById('speedtest-ping');
  const bar = document.getElementById('speedtest-bar');
  const status = document.getElementById('speedtest-status');
  if (down) down.innerHTML = '\u2014';
  if (up) up.innerHTML = '\u2014';
  if (ping) ping.innerHTML = '\u2014';
  if (bar) bar.style.width = '0%';
  if (status) status.textContent = 'Tests transfer ' + (_metricsSpeedtestSize/1048576).toFixed(0) + ' MB to/from this server.';
}

function _metricsFmtSpeed(mbps) {
  if (mbps >= 1000) return (mbps/1000).toFixed(2);
  if (mbps >= 100) return mbps.toFixed(0);
  if (mbps >= 10) return mbps.toFixed(1);
  return mbps.toFixed(2);
}

function _metricsSpeedUnit(mbps) { return mbps >= 1000 ? 'Gbps' : 'Mbps'; }

async function _metricsRunSpeedtest() {
  if (_metricsSpeedtestRunning) return;
  _metricsSpeedtestRunning = true;
  const btn = document.getElementById('speedtest-run-btn');
  const status = document.getElementById('speedtest-status');
  const bar = document.getElementById('speedtest-bar');
  const downEl = document.getElementById('speedtest-down');
  const upEl = document.getElementById('speedtest-up');
  const pingEl = document.getElementById('speedtest-ping');
  const downSubEl = document.getElementById('speedtest-down-sub');
  const upSubEl = document.getElementById('speedtest-up-sub');
  if (btn) { btn.disabled = true; btn.textContent = 'Running\u2026'; }
  if (downEl) downEl.innerHTML = '\u2026';
  if (upEl) upEl.innerHTML = '\u2014';
  if (pingEl) pingEl.innerHTML = '\u2014';
  if (bar) bar.style.width = '0%';

  try {
    // 1. Latency: average of 3 small no-cache pings
    if (status) status.textContent = 'Measuring latency\u2026';
    const pings = [];
    for (let i = 0; i < 3; i++) {
      const t0 = performance.now();
      await fetch(API + '/api/speedtest/download?bytes=1&_=' + Date.now() + '_' + i, { cache: 'no-store' }).then(r => r.arrayBuffer());
      pings.push(performance.now() - t0);
    }
    const avgPing = pings.reduce((a,b)=>a+b,0) / pings.length;
    if (pingEl) pingEl.textContent = avgPing.toFixed(0);
    if (bar) bar.style.width = '15%';

    // 2. Download test
    if (status) status.textContent = 'Downloading ' + (_metricsSpeedtestSize/1048576).toFixed(0) + ' MB\u2026';
    const dStart = performance.now();
    const dResp = await fetch(API + '/api/speedtest/download?bytes=' + _metricsSpeedtestSize + '&_=' + Date.now(), { cache: 'no-store' });
    const reader = dResp.body.getReader();
    let downBytes = 0;
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      downBytes += value.length;
      const pct = 15 + (downBytes / _metricsSpeedtestSize) * 40;
      if (bar) bar.style.width = pct.toFixed(1) + '%';
    }
    const dElapsed = (performance.now() - dStart) / 1000;
    const downMbps = (downBytes * 8) / dElapsed / 1e6;
    if (downEl) downEl.textContent = _metricsFmtSpeed(downMbps);
    if (downSubEl) downSubEl.textContent = _metricsSpeedUnit(downMbps);

    // 3. Upload test — generate random payload
    if (status) status.textContent = 'Uploading ' + (_metricsSpeedtestSize/1048576).toFixed(0) + ' MB\u2026';
    if (upEl) upEl.innerHTML = '\u2026';
    const payload = new Uint8Array(_metricsSpeedtestSize);
    // Fill with pseudo-random — incompressible enough for HTTP
    for (let i = 0; i < payload.length; i += 4096) {
      const end = Math.min(i + 4096, payload.length);
      for (let j = i; j < end; j++) payload[j] = (Math.random() * 256) | 0;
    }
    const uStart = performance.now();
    await fetch(API + '/api/speedtest/upload?_=' + Date.now(), {
      method: 'POST',
      headers: { 'Content-Type': 'application/octet-stream' },
      body: payload,
      cache: 'no-store',
    });
    const uElapsed = (performance.now() - uStart) / 1000;
    const upMbps = (_metricsSpeedtestSize * 8) / uElapsed / 1e6;
    if (upEl) upEl.textContent = _metricsFmtSpeed(upMbps);
    if (upSubEl) upSubEl.textContent = _metricsSpeedUnit(upMbps);
    if (bar) bar.style.width = '100%';
    _metricsSpeedtestResult = { down: downMbps, up: upMbps, ping: avgPing };
    if (status) status.textContent = 'Done \u00B7 ' + downMbps.toFixed(1) + ' Mbps down, ' + upMbps.toFixed(1) + ' Mbps up, ' + avgPing.toFixed(0) + ' ms ping.';
  } catch (e) {
    if (status) status.textContent = 'Speed test failed: ' + (e.message || e);
    if (bar) bar.style.width = '0%';
  } finally {
    _metricsSpeedtestRunning = false;
    if (btn) { btn.disabled = false; btn.textContent = 'Run again'; }
  }
}

function _metricsRender() {
  const data = _metricsData;
  if (!data) return;
  const sys = data.system || {};
  const sessions = data.sessions || [];

  // Sidebar session list
  const listEl = document.getElementById('metrics-session-list');
  if (listEl) {
    if (!sessions.length) {
      listEl.innerHTML = '<div style="padding:16px 12px;font-size:0.8rem;color:var(--dim);">No workers found</div>';
    } else {
      listEl.innerHTML = sessions.map(s => {
        const cls = _metricsGaugeCls(s.cpu_percent);
        const dotBg = s.active ? _metricsGaugeColor(cls) : 'transparent';
        const dotBorder = s.active ? 'none' : '1.5px solid var(--dim)';
        const sel = _metricsSelectedSession === s.name ? ' active' : '';
        const sub = s.active ? (s.cpu_percent.toFixed(1) + '% \u00B7 ' + (s.rss_mb > 0 ? s.rss_mb.toFixed(0) + ' MB' : 'idle')) : 'stopped';
        return `<div class="metrics-session-item${sel}" onclick="_metricsSelectSession('${s.name}')">
          <div class="metrics-session-dot" style="background:${dotBg};border:${dotBorder};"></div>
          <div class="metrics-session-info">
            <div class="metrics-session-name">${s.name}</div>
            <div class="metrics-session-sub">${sub}</div>
          </div>
        </div>`;
      }).join('');
    }
  }

  // Main content
  const content = document.getElementById('metrics-content');
  if (!content) return;

  let html = '';

  // Header
  const cacheAge = data.cache_age_seconds;
  const cacheLabel = cacheAge !== undefined
    ? `<span style="font-size:0.7rem;color:var(--dim);margin-left:4px;">(${cacheAge}s ago)</span>`
    : '';
  html += `<div class="metrics-hdr">
    <div class="metrics-hdr-left">
      <span class="metrics-hdr-title">System Metrics</span>
      ${sys.hostname ? `<span class="metrics-hostname">${sys.hostname}</span>` : ''}
      ${sys.uptime_seconds ? `<span class="metrics-uptime">up ${_metricsFormatUptime(sys.uptime_seconds)}</span>` : ''}
    </div>
    <div style="display:flex;align-items:center;gap:8px;">
      ${cacheLabel}
      <button class="btn" id="metrics-refresh-btn" onclick="_metricsLoad()" style="font-size:0.8rem;padding:5px 12px;">\u21BB Refresh</button>
    </div>
  </div>`;

  if (!sys.psutil) {
    html += `<div class="metrics-no-psutil">
      \u26A0\uFE0F Process-level CPU &amp; RAM per worker requires psutil &mdash;
      run <code>pip3 install psutil</code> then restart the server.
      System metrics are shown via fallback commands.
    </div>`;
  }

  // System metric cards
  html += '<div class="metrics-cards">';
  if (sys.cpu_percent !== undefined) {
    const cls = _metricsGaugeCls(sys.cpu_percent);
    html += `<div class="metrics-card">
      <div class="metrics-card-title">CPU</div>
      <div class="metrics-card-value">${sys.cpu_percent.toFixed(1)}<span>%</span></div>
      <div class="metrics-card-sub">${sys.cpu_count || ''} logical cores</div>
      <div class="metrics-gauge"><div class="metrics-gauge-fill ${cls}" style="width:${Math.min(100,sys.cpu_percent)}%"></div></div>
    </div>`;
  }
  if (sys.ram_total_mb) {
    const cls = _metricsGaugeCls(sys.ram_percent || 0);
    html += `<div class="metrics-card">
      <div class="metrics-card-title">Memory (RAM)</div>
      <div class="metrics-card-value">${(sys.ram_used_mb / 1024).toFixed(1)}<span> GB</span></div>
      <div class="metrics-card-sub">of ${(sys.ram_total_mb / 1024).toFixed(1)} GB &mdash; ${(sys.ram_percent || 0).toFixed(0)}%</div>
      <div class="metrics-gauge"><div class="metrics-gauge-fill ${cls}" style="width:${Math.min(100, sys.ram_percent || 0)}%"></div></div>
    </div>`;
  }
  if (sys.swap_total_mb !== undefined) {
    const swapPct = sys.swap_total_mb > 0 ? sys.swap_used_mb / sys.swap_total_mb * 100 : 0;
    const cls = _metricsGaugeCls(swapPct);
    const swapVal = sys.swap_used_mb < 1024 ? sys.swap_used_mb.toFixed(0) + ' MB' : (sys.swap_used_mb / 1024).toFixed(1) + ' GB';
    const swapTot = sys.swap_total_mb < 1024 ? sys.swap_total_mb.toFixed(0) + ' MB' : (sys.swap_total_mb / 1024).toFixed(1) + ' GB';
    html += `<div class="metrics-card">
      <div class="metrics-card-title">Swap</div>
      <div class="metrics-card-value" style="font-size:1.2rem;">${swapVal}</div>
      <div class="metrics-card-sub">of ${swapTot} &mdash; ${swapPct.toFixed(0)}%</div>
      <div class="metrics-gauge"><div class="metrics-gauge-fill ${cls}" style="width:${Math.min(100, swapPct)}%"></div></div>
    </div>`;
  }
  if (sys.disk_total_gb) {
    const cls = _metricsGaugeCls(sys.disk_percent || 0);
    // Free space is the number you act on, so it leads. Clicking through to
    // Disk Cleanup is the point: a red gauge with no next step is just anxiety.
    html += `<div class="metrics-card reclaim-catcard" onclick="_metricsSetMode('disk')" title="Open Disk Cleanup">
      <div class="metrics-card-title">Disk</div>
      <div class="metrics-card-value">${sys.disk_free_gb != null ? sys.disk_free_gb : (sys.disk_total_gb - sys.disk_used_gb).toFixed(1)}<span> GB free</span></div>
      <div class="metrics-card-sub">${sys.disk_used_gb} of ${sys.disk_total_gb} GB used &mdash; ${(sys.disk_percent || 0).toFixed(0)}%</div>
      <div class="metrics-gauge"><div class="metrics-gauge-fill ${cls}" style="width:${Math.min(100, sys.disk_percent || 0)}%"></div></div>
      <div style="font-size:0.66rem;color:var(--accent,#58a6ff);margin-top:6px;">Disk Cleanup &rsaquo;</div>
    </div>`;
  }
  html += '</div>';

  // Load averages
  if (sys.load_avg && sys.load_avg.length) {
    html += '<div class="metrics-section-title">Load Average</div><div class="metrics-load-row">';
    const labels = ['1 min', '5 min', '15 min'];
    sys.load_avg.forEach((v, i) => {
      const pct = sys.cpu_count ? Math.min(100, v / sys.cpu_count * 100) : 0;
      const cls = _metricsGaugeCls(pct);
      html += `<div class="metrics-load-block">
        <div class="metrics-load-val" style="color:${_metricsGaugeColor(cls)}">${v.toFixed(2)}</div>
        <div class="metrics-load-lbl">${labels[i] || ''}</div>
      </div>`;
    });
    html += '</div>';
  }

  // Server internals
  const srv = data.server || {};
  if (srv.pid) {
    html += '<div class="metrics-section-title">Server Internals</div><div class="metrics-cards">';
    html += `<div class="metrics-card">
      <div class="metrics-card-title">Threads</div>
      <div class="metrics-card-value">${srv.thread_count}</div>
      <div class="metrics-card-sub">${Object.entries(srv.thread_breakdown || {}).map(([k,v]) => k + ': ' + v).join(' · ')}</div>
    </div>`;
    html += `<div class="metrics-card">
      <div class="metrics-card-title">Requests</div>
      <div class="metrics-card-value">${(srv.request_count || 0).toLocaleString()}</div>
      <div class="metrics-card-sub">since last restart</div>
    </div>`;
    html += `<div class="metrics-card">
      <div class="metrics-card-title">Server Uptime</div>
      <div class="metrics-card-value" style="font-size:1.2rem;">${_metricsFormatUptime(srv.uptime_seconds || 0)}</div>
      <div class="metrics-card-sub">PID ${srv.pid} · Python ${srv.python_version || '?'}</div>
    </div>`;
    html += '</div>';
  }

  // Network speed test
  html += `<div class="metrics-section-title">Network Speed Test</div>
    <div class="metrics-speedtest" id="metrics-speedtest">
      <div class="metrics-speedtest-cards">
        <div class="metrics-speedtest-card">
          <div class="metrics-speedtest-label">Download</div>
          <div class="metrics-speedtest-value" id="speedtest-down">&mdash;</div>
          <div class="metrics-speedtest-sub" id="speedtest-down-sub">Mbps</div>
        </div>
        <div class="metrics-speedtest-card">
          <div class="metrics-speedtest-label">Upload</div>
          <div class="metrics-speedtest-value" id="speedtest-up">&mdash;</div>
          <div class="metrics-speedtest-sub" id="speedtest-up-sub">Mbps</div>
        </div>
        <div class="metrics-speedtest-card">
          <div class="metrics-speedtest-label">Latency</div>
          <div class="metrics-speedtest-value" id="speedtest-ping">&mdash;</div>
          <div class="metrics-speedtest-sub" id="speedtest-ping-sub">ms</div>
        </div>
      </div>
      <div class="metrics-speedtest-bar"><div class="metrics-speedtest-bar-fill" id="speedtest-bar"></div></div>
      <div class="metrics-speedtest-row">
        <div class="metrics-speedtest-status" id="speedtest-status">Tests transfer ${(_metricsSpeedtestSize/1048576).toFixed(0)} MB to/from this server.</div>
        <div style="display:flex;gap:8px;">
          <button class="btn" id="speedtest-run-btn" onclick="_metricsRunSpeedtest()" style="font-size:0.8rem;padding:5px 14px;">Run speed test</button>
          <button class="btn" id="speedtest-reset-btn" onclick="_metricsResetSpeedtest()" style="font-size:0.8rem;padding:5px 12px;">Reset</button>
        </div>
      </div>
    </div>`;

  // Session breakdown table
  html += '<div class="metrics-section-title">Worker Breakdown</div>';
  html += '<div class="metrics-table-wrap"><table class="metrics-table"><thead><tr>';
  html += '<th>Worker</th><th>Status</th><th>CPU %</th><th>RAM (MB)</th><th>Memory File</th><th>Tokens Today</th><th>Last Active</th><th>Processes</th>';
  html += '</tr></thead><tbody>';

  if (!sessions.length) {
    html += '<tr><td colspan="8" style="text-align:center;color:var(--dim);padding:20px;">No workers found</td></tr>';
  } else {
    const sorted = [...sessions].sort((a, b) => (b.cpu_percent - a.cpu_percent) || (b.rss_mb - a.rss_mb));
    sorted.forEach(s => {
      const sel = _metricsSelectedSession === s.name ? ' row-selected' : '';
      const cpuCls = _metricsGaugeCls(s.cpu_percent);
      const cpuColor = s.active ? _metricsGaugeColor(cpuCls) : 'var(--dim)';
      const statusHtml = s.active
        ? '<span style="color:#3fb950;">&#x25CF;</span> active'
        : '<span style="color:var(--dim);">&#x25CB;</span> stopped';
      const cpuHtml = s.active
        ? `<span style="color:${cpuColor};font-weight:600;">${s.cpu_percent.toFixed(1)}%</span>
           <span class="metrics-mini-bar"><span class="metrics-mini-bar-fill metrics-gauge-fill ${cpuCls}" style="width:${Math.min(100,s.cpu_percent)}%"></span></span>`
        : '\u2014';
      const ramHtml = s.active && s.rss_mb > 0 ? s.rss_mb.toFixed(0) : '\u2014';
      const memFile = s.memory_file_kb > 0 ? s.memory_file_kb.toFixed(1) + ' KB' : '\u2014';
      const tokens = s.tokens_today > 0 ? s.tokens_today.toLocaleString() : '\u2014';
      const lastAct = _metricsRelTime(s.last_active);
      const procs = s.pids && s.pids.length ? s.pids.length : (s.active ? '1' : '\u2014');
      html += `<tr class="${sel}" onclick="_metricsSelectSession('${s.name}')">
        <td><strong>${s.name}</strong></td>
        <td style="font-size:0.78rem;">${statusHtml}</td>
        <td>${cpuHtml}</td>
        <td>${ramHtml}</td>
        <td style="font-size:0.78rem;color:var(--dim);">${memFile}</td>
        <td style="font-size:0.78rem;">${tokens}</td>
        <td style="font-size:0.78rem;color:var(--dim);">${lastAct}</td>
        <td style="font-size:0.78rem;color:var(--dim);">${procs}</td>
      </tr>`;
    });
  }
  html += '</tbody></table></div>';

  content.innerHTML = html;
  _metricsApplySidebarState();
}

function _metricsSelectSession(name) {
  _metricsSelectedSession = _metricsSelectedSession === name ? null : name;
  _metricsRender();
}

// ── Metrics > Disk Cleanup (reclaim) ─────────────────────────────────────────
// Scan / findings / treemap / quarantine over /api/reclaim.
//
// The one number this UI must never fake: "reclaimed". A move within a volume
// frees nothing, and on APFS even a delete frees nothing while a local snapshot
// still references the blocks — measured on 2026-08-16, deleting 22GB of ollama
// models moved `df` by ~0. So every reclaim figure shown here is a real
// free-space delta reported by the server, and estimates are labelled as such.
let _metricsMode = 'system';
let _reclaimScan = null;
let _reclaimTimer = null;
let _reclaimSel = new Set();
let _reclaimTreePath = null;
let _reclaimTree = null;
let _reclaimQuarantine = null;
let _reclaimCat = null;

const _RECLAIM_CATS = {
  build:     { label: 'Build artifacts', hint: 'Regenerable. Costs a rebuild, not data.', safe: true },
  cache:     { label: 'Caches',          hint: 'Regenerable. Apps refill these on demand.', safe: true },
  devtool:   { label: 'Dev tool stores', hint: 'Models, images, registries. Re-download can be slow.', safe: true },
  large:     { label: 'Large files',     hint: 'Recently touched. Review individually.', safe: false },
  stale:     { label: 'Stale files',     hint: 'Large and untouched for 90d+. Review individually.', safe: false },
  duplicate: { label: 'Likely duplicates', hint: 'Same size + head/tail fingerprint, NOT a full hash. Verify before deleting.', safe: false },
  snapshot:  { label: 'APFS snapshots',  hint: 'Holds deleted blocks. Not deletable from here.', safe: false },
};

const _KIND_COLORS = {
  model: '#a371f7', media: '#f0883e', image: '#3fb950', archive: '#e3b341',
  data: '#58a6ff', code: '#6e7681', build: '#f85149', doc: '#39c5cf', other: '#484f58',
};

// _fmtBytes is declared once, further down (the B/KB/MB/GB version by the
// torrent renderer). A second copy lived here; in a classic script the LAST
// declaration wins, so this one governed nothing at runtime and only tripped
// eslint no-redeclare, which failed the SPA static gate and kept rust.yml red
// for 3 runs on origin/main (reported by mixpeek-homepage-claude 2026-08-17,
// which also blocked their MHC-377 CI step from ever running). Removed.

function _metricsSetMode(mode) {
  _metricsMode = mode;
  document.getElementById('metricsmode-system')?.classList.toggle('active', mode === 'system');
  document.getElementById('metricsmode-disk')?.classList.toggle('active', mode === 'disk');
  const mc = document.getElementById('metrics-content');
  const rc = document.getElementById('reclaim-content');
  if (mc) mc.style.display = mode === 'system' ? '' : 'none';
  if (rc) rc.style.display = mode === 'disk' ? '' : 'none';
  const sb = document.getElementById('metrics-sidebar');
  if (sb) sb.style.display = mode === 'disk' ? 'none' : '';
  if (mode === 'disk') _reclaimLoad(); else _reclaimStopPolling();
}

function _reclaimStopPolling() {
  if (_reclaimTimer) { clearInterval(_reclaimTimer); _reclaimTimer = null; }
}

async function _reclaimLoad() {
  try {
    const [scan, quar] = await Promise.all([
      fetch(API + '/api/reclaim/scan/latest').then(r => r.ok ? r.json() : null).catch(() => null),
      fetch(API + '/api/reclaim/quarantine').then(r => r.ok ? r.json() : null).catch(() => null),
    ]);
    _reclaimScan = scan;
    _reclaimQuarantine = quar;
    _reclaimRender();
    const st = scan?.scan?.status;
    if (st === 'running' && !_reclaimTimer) _reclaimTimer = setInterval(_reclaimPoll, 1500);
    if (st !== 'running') _reclaimStopPolling();
    // Any terminal status, not just 'done'. A cancelled or interrupted scan
    // still persists the tree it built before it stopped, and gating on 'done'
    // meant the map silently never appeared for the two statuses that are most
    // common here - the server restarts on every commit to this checkout.
    if (st && st !== 'running' && !_reclaimTree) _reclaimLoadTree(null);
  } catch (e) {
    const el = document.getElementById('reclaim-content');
    if (el) el.innerHTML = '<div style="color:var(--red);padding:20px;">Could not load reclaim data: ' + esc(String(e)) + '</div>';
  }
}

async function _reclaimPoll() {
  const r = await fetch(API + '/api/reclaim/scan/latest').then(r => r.ok ? r.json() : null).catch(() => null);
  if (!r) return;
  const wasRunning = _reclaimScan?.scan?.status === 'running';
  _reclaimScan = r;
  _reclaimRender();
  if (r.scan?.status !== 'running') {
    _reclaimStopPolling();
    if (wasRunning) { _reclaimTree = null; _reclaimLoadTree(null); showToast('Disk scan complete'); }
  }
}

async function _reclaimStartScan() {
  const btn = document.getElementById('reclaim-scan-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Starting…'; }
  try {
    const r = await fetch(API + '/api/reclaim/scan', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({}),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok) { showToast(d.error || 'Scan could not start'); }
    _reclaimSel = new Set();
    await _reclaimLoad();
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Rescan'; }
  }
}

async function _reclaimCancelScan() {
  const id = _reclaimScan?.scan?.id;
  if (!id) return;
  await fetch(API + '/api/reclaim/scan/' + encodeURIComponent(id) + '/cancel', { method: 'POST' });
  _reclaimLoad();
}

async function _reclaimLoadTree(path) {
  const id = _reclaimScan?.scan?.id;
  if (!id) return;
  const qs = path ? '?path=' + encodeURIComponent(path) : '';
  _reclaimTree = await fetch(API + '/api/reclaim/tree/' + encodeURIComponent(id) + qs)
    .then(r => r.ok ? r.json() : null).catch(() => null);
  _reclaimTreePath = path;
  _reclaimRender();
}

function _reclaimToggle(path) {
  if (_reclaimSel.has(path)) _reclaimSel.delete(path); else _reclaimSel.add(path);
  _reclaimRender();
}

function _reclaimSetCat(cat) {
  _reclaimCat = (_reclaimCat === cat || !cat) ? null : cat;
  _reclaimRender();
}

function _reclaimSelectCategory(cat) {
  // Only regenerable categories are bulk-selectable. Stale/duplicate/large are
  // judgment calls and stay one-at-a-time on purpose (ethos rule 8).
  const rows = (_reclaimScan?.findings || []).filter(f => f.category === cat && f.regenerable);
  const allOn = rows.length && rows.every(f => _reclaimSel.has(f.path));
  rows.forEach(f => allOn ? _reclaimSel.delete(f.path) : _reclaimSel.add(f.path));
  _reclaimRender();
}

async function _reclaimQuarantineSelected() {
  const paths = [..._reclaimSel];
  if (!paths.length) return;
  const est = (_reclaimScan?.findings || []).filter(f => _reclaimSel.has(f.path))
    .reduce((a, f) => a + (f.bytes || 0), 0);
  const msg = 'Move ' + paths.length + ' item(s) to quarantine?\n\n'
    + 'Estimated size: ' + _fmtBytes(est) + '\n\n'
    + 'Nothing is deleted. Files move to ~/.amux/quarantine and can be restored '
    + 'with one click. Space is NOT returned until you purge the batch.\n\n'
    + paths.slice(0, 12).join('\n') + (paths.length > 12 ? '\n…and ' + (paths.length - 12) + ' more' : '');
  if (!confirm(msg)) return;
  const r = await fetch(API + '/api/reclaim/quarantine', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ paths, scan_id: _reclaimScan?.scan?.id }),
  });
  const d = await r.json().catch(() => ({}));
  if (d.refused && d.refused.length) {
    alert('Staged ' + (d.moved || 0) + ' item(s).\n\nRefused ' + d.refused.length + ':\n'
      + d.refused.map(x => x.path + ' — ' + x.reason).join('\n'));
  } else {
    showToast('Staged ' + (d.moved || 0) + ' item(s) — ' + _fmtBytes(d.bytes || 0));
  }
  _reclaimSel = new Set();
  _reclaimLoad();
}

async function _reclaimRestore(batchId) {
  if (!confirm('Restore every file in this batch to its original location?')) return;
  const r = await fetch(API + '/api/reclaim/quarantine/' + encodeURIComponent(batchId) + '/restore', { method: 'POST' });
  const d = await r.json().catch(() => ({}));
  showToast('Restored ' + (d.restored || 0) + ' item(s)');
  if (d.failed && d.failed.length) alert('Failed:\n' + d.failed.map(x => x.path + ' — ' + x.reason).join('\n'));
  _reclaimLoad();
}

// The exit condition for a learned skip. A filesystem that hung once may
// answer next week, and without a way back the scan's coverage only ever
// shrinks — silently, which is the part that makes it worse than the hang.
async function _reclaimUnskip(path) {
  const r = await fetch(API + '/api/reclaim/skipped?path=' + encodeURIComponent(path), { method: 'DELETE' });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) { showToast(d.error || 'Could not clear that skip'); return; }
  showToast('Will be scanned again next run');
  _reclaimLoad();
}

async function _reclaimPurge(batchId, bytes) {
  const msg = 'PERMANENTLY DELETE this quarantine batch?\n\n'
    + 'Size: ' + _fmtBytes(bytes) + '\n\n'
    + 'This cannot be undone. Restore will no longer be possible.';
  if (!confirm(msg)) return;
  if (prompt('Type PURGE to confirm permanent deletion:') !== 'PURGE') { showToast('Cancelled'); return; }
  const r = await fetch(API + '/api/reclaim/quarantine/' + encodeURIComponent(batchId)
    + '?confirm=' + encodeURIComponent(batchId), { method: 'DELETE' });
  const d = await r.json().catch(() => ({}));
  // Report the REAL delta, and say so when it disappoints.
  showToast('Purged · free space +' + _fmtBytes(d.actually_freed || 0));
  if (d.note) alert(d.note);
  _reclaimLoad();
}

// Squarified treemap. Colour encodes the dominant file-type bucket, area
// encodes bytes, so a big red block is a big pile of build output.
function _reclaimTreemapSvg(nodes, w, h) {
  const total = nodes.reduce((a, n) => a + (n.bytes || 0), 0);
  if (!total) return '<div style="color:var(--dim);padding:20px;font-size:0.82rem;">No size data for this folder.</div>';
  const items = nodes.filter(n => n.bytes > 0).map(n => ({ ...n, area: n.bytes / total * w * h }));
  const rects = [];
  let x = 0, y = 0, cw = w, ch = h, i = 0;

  while (i < items.length) {
    const vertical = cw >= ch;
    const side = vertical ? ch : cw;
    let row = [], rowArea = 0, best = Infinity;
    while (i + row.length < items.length) {
      const cand = [...row, items[i + row.length]];
      const ca = rowArea + items[i + row.length].area;
      const len = ca / side;
      const worst = Math.max(...cand.map(r => Math.max(len / (r.area / len || 1e-9), (r.area / len || 1e-9) / len)));
      if (row.length && worst > best) break;
      row = cand; rowArea = ca; best = worst;
    }
    if (!row.length || side <= 0) break;
    const len = rowArea / side;
    if (!(len > 0)) break;
    let off = 0;
    row.forEach(r => {
      const seg = (r.area / rowArea) * side;
      rects.push(vertical
        ? { ...r, x, y: y + off, w: len, h: seg }
        : { ...r, x: x + off, y, w: seg, h: len });
      off += seg;
    });
    if (vertical) { x += len; cw -= len; } else { y += len; ch -= len; }
    i += row.length;
  }

  const body = rects.map(r => {
    const name = (r.path || '').split('/').pop() || r.path;
    const color = _KIND_COLORS[r.kind || 'other'] || _KIND_COLORS.other;
    const showLabel = r.w > 54 && r.h > 22;
    const t = esc(name + ' — ' + _fmtBytes(r.bytes));
    return `<g class="tm-cell" onclick="_reclaimLoadTree('${escJs(r.path)}')">
      <title>${t}</title>
      <rect x="${r.x.toFixed(1)}" y="${r.y.toFixed(1)}" width="${Math.max(0,r.w-1.5).toFixed(1)}" height="${Math.max(0,r.h-1.5).toFixed(1)}"
            fill="${color}" fill-opacity="0.78" stroke="var(--bg)" stroke-width="1" rx="2"/>
      ${showLabel ? `<text x="${(r.x+6).toFixed(1)}" y="${(r.y+15).toFixed(1)}" font-size="10.5" fill="#fff" font-weight="600" pointer-events="none">${esc(name.slice(0,22))}</text>
      <text x="${(r.x+6).toFixed(1)}" y="${(r.y+27).toFixed(1)}" font-size="9.5" fill="#fff" fill-opacity="0.82" pointer-events="none">${_fmtBytes(r.bytes)}</text>` : ''}
    </g>`;
  }).join('');

  // viewBox is sized to the ACTUAL box (see the caller), so the map fills its
  // container without letterboxing and without preserveAspectRatio="none".
  // That would fill the box but shear every text label, since non-uniform
  // scaling distorts glyphs even though it preserves relative cell areas.
  return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}" style="display:block;border-radius:8px;overflow:hidden;">${body}</svg>`;
}

function _reclaimRender() {
  const el = document.getElementById('reclaim-content');
  if (!el) return;
  const scan = _reclaimScan?.scan;
  const findings = _reclaimScan?.findings || [];
  const totals = _reclaimScan?.totals || [];
  let html = '';

  // Header + volume state
  const freePct = scan?.df_total ? (scan.df_free / scan.df_total * 100) : null;
  const critical = freePct !== null && freePct < 10;
  html += `<div class="metrics-hdr">
    <div class="metrics-hdr-left">
      <span class="metrics-hdr-title">Disk Cleanup</span>
      ${scan?.df_total ? `<span class="metrics-hostname">${_fmtBytes(scan.df_free)} free of ${_fmtBytes(scan.df_total)}</span>` : ''}
      ${critical ? `<span style="color:var(--red);font-size:0.72rem;font-weight:600;">${freePct.toFixed(1)}% free</span>` : ''}
    </div>
    <div style="display:flex;gap:8px;align-items:center;">
      ${scan?.status === 'running'
        ? `<button class="btn" onclick="_reclaimCancelScan()" style="font-size:0.8rem;padding:5px 12px;">Stop scan</button>`
        : `<button class="btn" id="reclaim-scan-btn" onclick="_reclaimStartScan()" style="font-size:0.8rem;padding:5px 12px;">${scan ? 'Rescan' : 'Run scan'}</button>`}
    </div>
  </div>`;

  if (!scan) {
    html += `<div class="reclaim-empty">
      <div style="font-weight:600;margin-bottom:6px;">No scan yet</div>
      <div style="font-size:0.82rem;color:var(--dim);line-height:1.6;max-width:620px;">
        Walks your home directory plus the dev-tool stores that live outside it, and ranks what can be
        reclaimed. The scan is read-only and runs at background I/O priority so it does not compete
        with the amux server for disk. Nothing is deleted without you selecting it.
      </div>
    </div>`;
    el.innerHTML = html;
    return;
  }

  // Progress
  if (scan.status === 'running') {
    html += `<div class="reclaim-progress">
      <div class="reclaim-spinner"></div>
      <div style="flex:1;min-width:0;">
        <div style="font-size:0.85rem;font-weight:600;margin-bottom:3px;">Scanning…</div>
        <div style="font-size:0.75rem;color:var(--dim);">
          ${(scan.dirs_walked||0).toLocaleString()} folders · ${(scan.files_walked||0).toLocaleString()} files · ${_fmtBytes(scan.bytes_seen)} seen
        </div>
        <div class="reclaim-curpath">${scan.current_phase ? `<b>${esc(scan.current_phase)}</b> · ` : ''}${esc(scan.current_path || '')}</div>
      </div>
    </div>`;
  }

  // A scan the watchdog declared stuck. This is a different failure from
  // "interrupted" and must not be shown as one: nothing restarted, a directory
  // stopped answering, and the walk thread is still parked in the kernel on it.
  if (scan.status === 'stalled') {
    html += `<div class="reclaim-warn">
      <div style="font-weight:600;margin-bottom:4px;">⚠ Scan stalled on one directory</div>
      <div style="font-size:0.78rem;line-height:1.55;">
        ${esc(scan.error || '')}
        <div style="margin-top:6px;">
          Recorded below. A directory is only stepped over after it hangs a second scan,
          because one quiet spell on a loaded machine is contention rather than a broken folder.
          Results cover ${(scan.dirs_walked||0).toLocaleString()} folders walked before the stall.
        </div>
      </div>
    </div>`;
  }

  // An interrupted scan must say so. The server restarts on every commit to
  // the shared checkout, so a scan dying mid-walk is common, and a UI that
  // kept spinning would read as "still working" forever.
  if (scan.status === 'interrupted' || (scan.status === 'cancelled' && scan.error)) {
    html += `<div class="reclaim-warn">
      <div style="font-weight:600;margin-bottom:4px;">Scan did not finish</div>
      <div style="font-size:0.78rem;line-height:1.55;">
        ${esc(scan.error || 'The scan was cancelled.')}
        Results below are partial: ${(scan.dirs_walked||0).toLocaleString()} folders were walked before it stopped.
        Run it again to get a complete picture.
      </div>
    </div>`;
  }

  // Snapshot warning: the thing that makes cleanup look broken.
  const snapFinding = findings.find(f => f.category === 'snapshot');
  if (snapFinding) {
    html += `<div class="reclaim-warn">
      <div style="font-weight:600;margin-bottom:4px;">⚠ ${scan.snapshot_count} APFS local snapshots are holding deleted space</div>
      <div style="font-size:0.78rem;line-height:1.55;">
        Until these expire or are thinned, <b>deleting files will not increase your free space</b>.
        The blocks stay referenced by the snapshot. This is why a cleanup can look like it did nothing.
        <div style="margin-top:6px;">Release them from a terminal (needs sudo, so amux will not run it for you):</div>
        <code class="reclaim-code">sudo tmutil thinlocalsnapshots / 21474836480 4</code>
      </div>
    </div>`;
  }

  // What the scan did NOT look at. Shown next to the results rather than
  // behind a separate view, because a home-directory total that silently omits
  // a subtree is a confident wrong answer — the reader has to be able to see
  // the hole to weigh the number.
  const skipped = _reclaimScan?.skipped || [];
  if (skipped.length) {
    html += `<div class="reclaim-skips">
      <div style="font-weight:600;margin-bottom:4px;">Coverage notes (${skipped.length})</div>
      ${skipped.map(s => `<div class="reclaim-skip-row">
        <span class="reclaim-skip-reason ${s.active ? 'bad' : ''}">${esc(s.active ? 'skipped' : 'watching')}</span>
        <code>${esc(s.path)}</code>
        <span class="reclaim-skip-why">${esc(s.detail || '')}</span>
        <button class="reclaim-minibtn" onclick="_reclaimUnskip('${escJs(s.path)}')" title="Try this directory again on the next scan">Re-include</button>
      </div>`).join('')}
    </div>`;
  }

  // Category totals
  const actionable = totals.filter(t => t.category !== 'snapshot');
  if (actionable.length) {
    html += '<div class="metrics-section-title">Reclaimable by category</div><div class="metrics-cards">';
    actionable.forEach(t => {
      const meta = _RECLAIM_CATS[t.category] || { label: t.category, hint: '' };
      const on = _reclaimCat === t.category;
      html += `<div class="metrics-card reclaim-catcard${on ? ' active' : ''}" onclick="_reclaimSetCat('${escJs(t.category)}')" title="${esc(meta.hint)}">
        <div class="metrics-card-title">${esc(meta.label)}</div>
        <div class="metrics-card-value" style="font-size:1.2rem;">${_fmtBytes(t.bytes)}</div>
        <div class="metrics-card-sub">${t.count} item${t.count === 1 ? '' : 's'}${meta.safe ? ' · regenerable' : ''}</div>
      </div>`;
    });
    html += '</div>';
  }

  // Treemap
  if (_reclaimTree) {
    const rootPath = _reclaimTree.root?.path || _reclaimTreePath || '~';
    const parent = rootPath.includes('/') ? rootPath.slice(0, rootPath.lastIndexOf('/')) : null;
    html += `<div class="metrics-section-title" style="margin-top:18px;">Disk map
      <span style="text-transform:none;letter-spacing:0;font-weight:400;">(click a block to drill in)</span></div>`;
    html += `<div class="reclaim-mapbar">
      ${parent ? `<button class="btn reclaim-upbtn" onclick="_reclaimLoadTree('${escJs(parent)}')">↑ up</button>` : ''}
      <span class="reclaim-mappath">${esc(rootPath)}</span>
      ${_reclaimTree.root ? `<span style="color:var(--dim);font-size:0.75rem;">${_fmtBytes(_reclaimTree.root.bytes)}</span>` : ''}
    </div>`;
    // Lay the map out at the size it will actually occupy, so the viewBox and
    // the box agree and nothing is letterboxed. Measured from the scroll pane
    // (minus its 16px padding either side) rather than assumed.
    const _mapW = Math.round(Math.max(300, Math.min(1200,
      (document.getElementById('metrics-main')?.clientWidth || 900) - 32)));
    const _mapH = window.innerWidth < 600 ? 300 : 340;
    html += '<div class="reclaim-map">' + _reclaimTreemapSvg(_reclaimTree.children || [], _mapW, _mapH) + '</div>';
    html += '<div class="reclaim-legend">' + Object.entries(_KIND_COLORS).map(([k, c]) =>
      `<span class="reclaim-legend-item"><i style="background:${c}"></i>${k}</span>`).join('') + '</div>';
  }

  // Findings table
  const shown = _reclaimCat ? findings.filter(f => f.category === _reclaimCat) : findings.filter(f => f.category !== 'snapshot');
  const selBytes = findings.filter(f => _reclaimSel.has(f.path)).reduce((a, f) => a + (f.bytes || 0), 0);

  html += `<div class="metrics-section-title" style="margin-top:18px;">
    Findings${_reclaimCat ? ' — ' + esc(_RECLAIM_CATS[_reclaimCat]?.label || _reclaimCat) : ''}
    <span style="text-transform:none;letter-spacing:0;font-weight:400;">(${shown.length})</span>
    ${_reclaimCat ? `<button class="btn reclaim-minibtn" onclick="_reclaimSetCat(null)">clear filter</button>` : ''}
    ${_reclaimCat && _RECLAIM_CATS[_reclaimCat]?.safe ? `<button class="btn reclaim-minibtn" onclick="_reclaimSelectCategory('${escJs(_reclaimCat)}')">select all regenerable</button>` : ''}
  </div>`;

  if (_reclaimSel.size) {
    html += `<div class="reclaim-actionbar">
      <span><b>${_reclaimSel.size}</b> selected · <b>${_fmtBytes(selBytes)}</b> <span style="color:var(--dim);">(estimated)</span></span>
      <span style="display:flex;gap:8px;">
        <button class="btn" onclick="_reclaimSel=new Set();_reclaimRender()">Clear</button>
        <button class="btn reclaim-danger" onclick="_reclaimQuarantineSelected()">Move to quarantine…</button>
      </span>
    </div>`;
  }

  html += '<div class="metrics-table-wrap"><table class="metrics-table"><thead><tr>';
  html += '<th style="width:28px;"></th><th>Path</th><th>Category</th><th>Size</th><th>Files</th><th>Detail</th>';
  html += '</tr></thead><tbody>';
  if (!shown.length) {
    html += '<tr><td colspan="6" style="text-align:center;color:var(--dim);padding:20px;">'
      + (scan.status === 'running' ? 'Scan in progress…' : 'Nothing found in this category.') + '</td></tr>';
  } else {
    shown.slice(0, 400).forEach(f => {
      const meta = _RECLAIM_CATS[f.category] || { label: f.category };
      const checked = _reclaimSel.has(f.path) ? ' checked' : '';
      html += `<tr class="${_reclaimSel.has(f.path) ? 'row-selected' : ''}">
        <td><input type="checkbox"${checked} onchange="_reclaimToggle('${escJs(f.path)}')"></td>
        <td style="font-family:var(--mono,monospace);font-size:0.74rem;word-break:break-all;">${esc(f.path)}</td>
        <td style="font-size:0.74rem;">${esc(meta.label)}${f.regenerable ? '' : ' <span style="color:var(--yellow,#e3b341);" title="Not regenerable. Review before removing.">⚠</span>'}</td>
        <td style="font-weight:600;">${_fmtBytes(f.bytes)}</td>
        <td style="font-size:0.74rem;color:var(--dim);">${(f.file_count||0).toLocaleString()}</td>
        <td style="font-size:0.72rem;color:var(--dim);">${esc(f.detail || '')}</td>
      </tr>`;
    });
  }
  html += '</tbody></table></div>';
  if (shown.length > 400) {
    html += `<div style="font-size:0.72rem;color:var(--dim);margin-top:6px;">Showing the 400 largest of ${shown.length}. Narrow with a category filter to see the rest.</div>`;
  }

  // Quarantine ledger
  const batches = (_reclaimQuarantine?.batches || []).filter(b => b.status !== 'purged' || b.item_count);
  if (batches.length) {
    html += '<div class="metrics-section-title" style="margin-top:20px;">Quarantine</div>';
    html += '<div class="metrics-table-wrap"><table class="metrics-table"><thead><tr>';
    html += '<th>Staged</th><th>Items</th><th>Size</th><th>Actually freed</th><th>Status</th><th></th>';
    html += '</tr></thead><tbody>';
    batches.forEach(b => {
      const freed = (b.df_free_after != null && b.df_free_before != null)
        ? b.df_free_after - b.df_free_before : null;
      const staged = b.status === 'staged';
      html += `<tr>
        <td style="font-size:0.75rem;">${_metricsRelTime(new Date(b.created_at * 1000).toISOString())}</td>
        <td>${b.item_count}</td>
        <td style="font-weight:600;">${_fmtBytes(b.bytes)}</td>
        <td style="font-size:0.75rem;color:${freed > 0 ? '#3fb950' : 'var(--dim)'};">${freed == null ? '—' : (freed > 0 ? '+' : '') + _fmtBytes(freed)}</td>
        <td style="font-size:0.75rem;">${esc(b.status)}</td>
        <td style="text-align:right;white-space:nowrap;">
          ${staged ? `<button class="btn reclaim-minibtn" onclick="_reclaimRestore('${escJs(b.id)}')">Restore</button>
          <button class="btn reclaim-minibtn reclaim-danger" onclick="_reclaimPurge('${escJs(b.id)}',${b.bytes})">Purge</button>` : ''}
        </td>
      </tr>`;
    });
    html += '</tbody></table></div>';
    html += `<div style="font-size:0.72rem;color:var(--dim);margin-top:6px;line-height:1.5;">
      Staged files live in <code>${esc(_reclaimQuarantine?.root || '~/.amux/quarantine')}</code>.
      "Actually freed" is the real free-space change rather than the sum of file sizes. A move frees
      nothing until purge, and snapshots can hold the blocks after that.</div>`;
  }

  el.innerHTML = html;
}

// ── Torrents tab ─────────────────────────────────────────────────────────────
let _torrents = [];
let _torrentTimer = null;

async function _torrentLoad() {
  try {
    const r = await fetch(API + '/api/torrents');
    _torrents = await r.json();
    _torrentRender();
  } catch(e) { console.error('torrent load', e); }
  if (!_torrentTimer) _torrentTimer = setInterval(_torrentLoad, 3000);
}

function _torrentStopTimer() {
  if (_torrentTimer) { clearInterval(_torrentTimer); _torrentTimer = null; }
}

async function _torrentAdd() {
  const inp = document.getElementById('torrent-magnet');
  const uri = inp.value.trim();
  if (!uri) return;
  inp.value = '';
  await fetch(API + '/api/torrents', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({uri}) });
  _torrentLoad();
}

async function _torrentRemove(gid) {
  await fetch(API + '/api/torrents/' + gid, { method: 'DELETE' });
  showToast('Torrent removed');
  _torrentLoad();
}

async function _torrentAction(gid, action) {
  await fetch(API + '/api/torrents/' + gid + '/' + action, { method: 'POST' });
  _torrentLoad();
}

function _torrentShowSettings() {
  const el = document.getElementById('torrent-settings');
  const isHidden = el.style.display === 'none';
  el.style.display = isHidden ? '' : 'none';
  if (isHidden) {
    fetch(API + '/api/torrents/config').then(r => r.json()).then(d => {
      document.getElementById('torrent-dir').value = d.download_dir || '';
    });
  }
}

async function _torrentSaveDir() {
  const dir = document.getElementById('torrent-dir').value.trim();
  if (!dir) return;
  await fetch(API + '/api/torrents/config', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({download_dir: dir}) });
  document.getElementById('torrent-settings').style.display = 'none';
}

function _torrentRender() {
  const list = document.getElementById('torrent-list');
  const empty = document.getElementById('torrent-empty');
  if (!_torrents.length) { list.innerHTML = ''; empty.style.display = ''; return; }
  empty.style.display = 'none';
  list.innerHTML = _torrents.map(t => {
    const pct = t.total > 0 ? Math.round(t.completed / t.total * 100) : 0;
    const speed = t.speed > 0 ? _fmtBytes(t.speed) + '/s' : '';
    const size = t.total > 0 ? _fmtBytes(t.completed) + ' / ' + _fmtBytes(t.total) : '';
    const statusCls = t.status === 'complete' ? 'color:var(--green)' : t.status === 'error' ? 'color:var(--red)' : t.status === 'paused' ? 'color:var(--yellow)' : '';
    // Control buttons based on status
    const isActive = t.status === 'active';
    const isPaused = t.status === 'paused' || t.status === 'waiting';
    const isDone = t.status === 'complete';
    const ctrlBtns = isDone
      ? `<button onclick="_torrentRemove('${t.gid}')" style="background:none;border:none;color:var(--dim);cursor:pointer;font-size:0.78rem;" title="Remove">&#x2716;</button>`
      : `${isActive ? `<button onclick="_torrentAction('${t.gid}','pause')" style="background:none;border:none;color:var(--yellow);cursor:pointer;font-size:0.85rem;" title="Pause">&#x23F8;</button>` : ''}
         ${isPaused ? `<button onclick="_torrentAction('${t.gid}','resume')" style="background:none;border:none;color:var(--green);cursor:pointer;font-size:0.85rem;" title="Resume">&#x25B6;</button>` : ''}
         <button onclick="_torrentAction('${t.gid}','remove')" style="background:none;border:none;color:var(--red);cursor:pointer;font-size:0.85rem;" title="Stop &amp; remove">&#x23F9;</button>`;
    return `<div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:10px 14px;">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">
        <strong style="flex:1;font-size:0.85rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(t.name || t.gid)}</strong>
        <span style="font-size:0.75rem;${statusCls}">${esc(t.status)}</span>
        ${speed ? `<span style="font-size:0.75rem;color:var(--accent);">${speed}</span>` : ''}
        ${ctrlBtns}
      </div>
      <div style="height:4px;background:var(--border);border-radius:2px;overflow:hidden;">
        <div style="height:100%;width:${pct}%;background:${isPaused ? 'var(--yellow)' : 'var(--accent)'};border-radius:2px;transition:width 0.3s;"></div>
      </div>
      <div style="display:flex;justify-content:space-between;margin-top:4px;font-size:0.75rem;color:var(--dim);">
        <span>${size}</span><span>${pct}%</span>
      </div>
      ${t.files && t.files.length ? `<div style="margin-top:6px;font-size:0.78rem;">
        ${t.files.map(f => {
          const isVideo = /\.(mp4|mkv|avi|mov|webm|m4v)$/i.test(f.path);
          const fname = f.path.split('/').pop();
          return `<div style="display:flex;align-items:center;gap:6px;padding:2px 0;">
            <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text);">${esc(fname)}</span>
            <span style="color:var(--dim);font-size:0.72rem;">${_fmtBytes(f.size)}</span>
            ${f.complete && isVideo ? `<button onclick="_playVideo('${t.gid}','${encodeURIComponent(f.path)}')" style="background:var(--accent);color:#fff;border:none;border-radius:4px;padding:2px 8px;font-size:0.72rem;cursor:pointer;">&#9654; Play</button>` : ''}
            ${f.complete ? `<a href="${API}/api/torrents/${t.gid}/file?path=${encodeURIComponent(f.path)}" download style="color:var(--accent);font-size:0.72rem;text-decoration:none;">Download</a>` : ''}
          </div>`;
        }).join('')}
      </div>` : ''}
    </div>`;
  }).join('');
}

function _fmtBytes(b) {
  if (b < 1024) return b + ' B';
  if (b < 1048576) return (b/1024).toFixed(1) + ' KB';
  if (b < 1073741824) return (b/1048576).toFixed(1) + ' MB';
  return (b/1073741824).toFixed(2) + ' GB';
}

function _torrentBrowseDir() {
  fetch(API + '/api/torrents/config').then(r => r.json()).then(d => {
    if (d.download_dir) openExplore(d.download_dir);
  });
}

// ── Video player ─────────────────────────────────────────────────────────────
let _vpRAF = null;
let _vpHideTimer = null;

function _vpPosKey(url) { return 'amux_vp_pos_' + url; }

function _vpMimeFromUrl(url) {
  const ext = url.split('?')[0].split('.').pop().toLowerCase();
  const map = { mp4:'video/mp4', m4v:'video/mp4', mov:'video/quicktime', webm:'video/webm', mkv:'video/x-matroska', avi:'video/x-msvideo' };
  return map[ext] || 'video/mp4';
}

async function _vpPrepareAndPlay(v, q, origUrl) {
  const status = document.getElementById('vp-status');
  for (;;) {
    if (v._vpUrl !== origUrl) return;   // player closed or another video opened
    let d;
    try {
      const r = await fetch(_authUrl(API + '/api/file/prepare?' + q));
      d = await r.json();
    } catch (e) { d = null; }
    if (d && d.ready && d.cached_path) {
      v.src = _authUrl(API + '/api/file/raw?path=' + encodeURIComponent(d.cached_path));
      v.play().catch(() => {});
      return;
    }
    if (!d || d.error) {
      // Prepare unavailable (no ffmpeg / no disk) — fall back to the live
      // transcode pipe, which still works in desktop browsers.
      v.src = _authUrl(API + '/api/file/transcode?' + q);
      v.play().catch(() => {});
      if (d && d.error) console.warn('prepare failed:', d.error);
      return;
    }
    status.style.display = 'flex';
    const pct = d.progress != null ? Math.round(d.progress) : 0;
    status.textContent = pct >= 99 ? 'Preparing video… finishing up'
                                   : 'Preparing video… ' + pct + '%';
    await new Promise(res => setTimeout(res, 2000));
  }
}

function _playVideoUrl(url, title) {
  const v = document.getElementById('video-player');
  const status = document.getElementById('vp-status');

  // MKV/AVI can't play natively — prepare a seekable MP4 server-side and play
  // that. The old live-transcode pipe (no Content-Length, no ranges) never
  // starts on iOS AVPlayer; a prepared cached mp4 streams + seeks everywhere.
  // Extract extension from the path query param (url is /api/file/raw?path=..., not the filename).
  const _vpSrcPath = (() => { try { return new URL(url, location.origin).searchParams.get('path') || url; } catch(e) { return url; } })();
  const ext = _vpSrcPath.split('.').pop().toLowerCase();
  const needsTranscode = ['mkv', 'avi'].includes(ext);
  v._vpUrl = url;
  if (needsTranscode) {
    // Extract path and cwd params from the raw URL for the prepare call
    const u = new URL(url, location.origin);
    const q = 'path=' + encodeURIComponent(u.searchParams.get('path') || '')
      + (u.searchParams.get('cwd') ? '&cwd=' + encodeURIComponent(u.searchParams.get('cwd')) : '');
    _vpPrepareAndPlay(v, q, url);
  } else {
    v.src = _authUrl(url);
  }

  document.getElementById('vp-title').textContent = title || url.split('/').pop();
  document.getElementById('video-overlay').style.display = 'flex';

  // Show loading state
  status.style.display = 'flex';
  status.textContent = 'Loading...';

  // Show AirPlay button if Safari supports it
  const airBtn = document.getElementById('vp-airplay');
  if (airBtn) airBtn.style.display = (v.webkitShowPlaybackTargetPicker) ? '' : 'none';
  // Show PiP button if supported
  const pipBtn = document.getElementById('vp-pip');
  if (pipBtn) pipBtn.style.display = (document.pictureInPictureEnabled || v.webkitSupportsPresentationMode) ? '' : 'none';

  const key = _vpPosKey(url);
  const saved = parseFloat(localStorage.getItem(key));
  if (saved > 0) {
    const doSeek = () => { v.currentTime = saved; v.removeEventListener('loadedmetadata', doSeek); };
    if (v.readyState >= 1) v.currentTime = saved;
    else v.addEventListener('loadedmetadata', doSeek);
  }

  // Hide loading when playback is ready
  const hideLoading = () => { status.style.display = 'none'; v.removeEventListener('canplay', hideLoading); v.removeEventListener('playing', hideLoading); };
  v.addEventListener('canplay', hideLoading);
  v.addEventListener('playing', hideLoading);
  // Fallback: if already ready, hide immediately
  if (v.readyState >= 3) hideLoading();

  // Error handling
  v.onerror = () => {
    const err = v.error;
    let msg = 'Cannot play this video';
    if (err) {
      if (err.code === 4) msg = 'Format not supported by this browser';
      else if (err.code === 2) msg = 'Network error loading video';
      else if (err.code === 3) msg = 'Video decode error';
    }
    status.style.display = 'flex';
    status.textContent = msg;
  };

  v.play().catch(() => {});
  _vpStartLoop();
  _vpShowControls();
  v.onpause = () => _vpSavePos(v);
  v.onseeked = () => _vpSavePos(v);
}

function _playVideo(gid, encodedPath) {
  const url = API + '/api/torrents/' + gid + '/file?path=' + encodedPath;
  const fname = decodeURIComponent(encodedPath).split('/').pop();
  _playVideoUrl(url, fname);
}

function _vpSavePos(v) {
  if (!v._vpUrl || !v.currentTime) return;
  if (v.duration && v.currentTime > v.duration - 10) {
    localStorage.removeItem(_vpPosKey(v._vpUrl));
  } else {
    localStorage.setItem(_vpPosKey(v._vpUrl), String(v.currentTime));
  }
}

function _closeVideo() {
  const v = document.getElementById('video-player');
  _vpSavePos(v);
  v.pause();
  v.removeAttribute('src');
  v._vpUrl = null;
  v.onerror = null;
  v.load();
  document.getElementById('vp-status').style.display = 'none';
  document.getElementById('video-overlay').style.display = 'none';
  if (_vpRAF) { cancelAnimationFrame(_vpRAF); _vpRAF = null; }
}

function _vpFmtTime(s) {
  if (!isFinite(s)) return '0:00';
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = Math.floor(s % 60);
  return h > 0 ? h + ':' + String(m).padStart(2,'0') + ':' + String(sec).padStart(2,'0') : m + ':' + String(sec).padStart(2,'0');
}

function _vpStartLoop() {
  function update() {
    const v = document.getElementById('video-player');
    if (!v || !v._vpUrl) return;
    const dur = v.duration || 0;
    const cur = v.currentTime || 0;
    // Played bar
    const pct = dur > 0 ? (cur / dur * 100) : 0;
    document.getElementById('vp-played').style.width = pct + '%';
    // Buffer bar
    if (v.buffered.length > 0) {
      const bufEnd = v.buffered.end(v.buffered.length - 1);
      document.getElementById('vp-buffer').style.width = (bufEnd / dur * 100) + '%';
    }
    // Time
    document.getElementById('vp-time').textContent = _vpFmtTime(cur) + ' / ' + _vpFmtTime(dur);
    // Play/pause icon
    document.getElementById('vp-play').innerHTML = v.paused ? '&#x25B6;' : '&#x23F8;';
    // Auto-save position every ~5s
    if (!v.paused && v._vpUrl && Math.floor(cur) % 5 === 0) _vpSavePos(v);
    _vpRAF = requestAnimationFrame(update);
  }
  if (_vpRAF) cancelAnimationFrame(_vpRAF);
  _vpRAF = requestAnimationFrame(update);
}

function _vpTogglePlay() {
  const v = document.getElementById('video-player');
  if (v.paused) v.play().catch(() => {}); else v.pause();
}

function _vpSeek(e) {
  const v = document.getElementById('video-player');
  const rect = e.currentTarget.getBoundingClientRect();
  const pct = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
  if (v.duration) v.currentTime = pct * v.duration;
}

function _vpHoverTime(e) {
  const v = document.getElementById('video-player');
  if (!v.duration) return;
  const rect = e.currentTarget.getBoundingClientRect();
  const pct = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
  const t = pct * v.duration;
  const el = document.getElementById('vp-hover-time');
  el.style.display = '';
  el.style.left = (pct * 100) + '%';
  el.textContent = _vpFmtTime(t);
}

function _vpHoverHide() {
  document.getElementById('vp-hover-time').style.display = 'none';
}

function _vpToggleMute() {
  const v = document.getElementById('video-player');
  v.muted = !v.muted;
  document.getElementById('vp-mute').innerHTML = v.muted ? '&#x1F507;' : '&#x1F50A;';
  document.getElementById('vp-volume').value = v.muted ? 0 : v.volume;
}

function _vpSetVolume(val) {
  const v = document.getElementById('video-player');
  v.volume = parseFloat(val);
  v.muted = val == 0;
  document.getElementById('vp-mute').innerHTML = val == 0 ? '&#x1F507;' : '&#x1F50A;';
}

function _vpFullscreen() {
  const container = document.getElementById('vp-container');
  const v = document.getElementById('video-player');
  // iOS Safari: use webkitEnterFullscreen on the video element
  if (v.webkitEnterFullscreen) { v.webkitEnterFullscreen(); return; }
  const el = container || v;
  if (el.requestFullscreen) el.requestFullscreen();
  else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen();
}

function _vpAirPlay() {
  const v = document.getElementById('video-player');
  if (v.webkitShowPlaybackTargetPicker) v.webkitShowPlaybackTargetPicker();
}

function _vpPiP() {
  const v = document.getElementById('video-player');
  if (document.pictureInPictureElement) { document.exitPictureInPicture().catch(() => {}); return; }
  if (v.requestPictureInPicture) v.requestPictureInPicture().catch(() => {});
  else if (v.webkitSupportsPresentationMode) v.webkitSetPresentationMode(v.webkitPresentationMode === 'picture-in-picture' ? 'inline' : 'picture-in-picture');
}

function _vpShowControls() {
  const ctrl = document.getElementById('vp-controls');
  if (ctrl) ctrl.style.opacity = '1';
  clearTimeout(_vpHideTimer);
  _vpHideTimer = setTimeout(() => {
    const v = document.getElementById('video-player');
    if (v && !v.paused) ctrl.style.opacity = '0';
  }, 3000);
}

// Click/tap video to toggle play, mousemove/touchstart to show controls
document.getElementById('video-player').addEventListener('click', e => { e.stopPropagation(); _vpTogglePlay(); });
document.getElementById('vp-container').addEventListener('mousemove', _vpShowControls);
document.getElementById('vp-container').addEventListener('touchstart', _vpShowControls, { passive: true });

// Touch seek on progress bar
(function() {
  const bar = document.getElementById('vp-progress-wrap');
  if (!bar) return;
  function touchSeek(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const rect = bar.getBoundingClientRect();
    const pct = Math.max(0, Math.min(1, (touch.clientX - rect.left) / rect.width));
    const v = document.getElementById('video-player');
    if (v.duration) v.currentTime = pct * v.duration;
  }
  bar.addEventListener('touchstart', touchSeek, { passive: false });
  bar.addEventListener('touchmove', touchSeek, { passive: false });
})();

// Hide volume slider on mobile (iOS ignores programmatic volume)
if ('ontouchstart' in window) {
  const vw = document.getElementById('vp-volume-wrap');
  if (vw) vw.style.display = 'none';
}

// Keyboard controls
document.getElementById('video-overlay').addEventListener('keydown', e => {
  const v = document.getElementById('video-player');
  if (!v || !v._vpUrl) return;
  if (e.key === ' ' || e.key === 'k') { e.preventDefault(); _vpTogglePlay(); }
  if (e.key === 'ArrowLeft') { e.preventDefault(); v.currentTime = Math.max(0, v.currentTime - 10); }
  if (e.key === 'ArrowRight') { e.preventDefault(); v.currentTime = Math.min(v.duration || 0, v.currentTime + 10); }
  if (e.key === 'ArrowUp') { e.preventDefault(); v.volume = Math.min(1, v.volume + 0.1); document.getElementById('vp-volume').value = v.volume; }
  if (e.key === 'ArrowDown') { e.preventDefault(); v.volume = Math.max(0, v.volume - 0.1); document.getElementById('vp-volume').value = v.volume; }
  if (e.key === 'f') _vpFullscreen();
  if (e.key === 'm') _vpToggleMute();
  if (e.key === 'Escape') _closeVideo();
});

// Enter key in magnet input
document.getElementById('torrent-magnet').addEventListener('keydown', e => { if (e.key === 'Enter') _torrentAdd(); });

// ── Terminal tab ──────────────────────────────────────────────────────────────
let _term = null;       // xterm.js Terminal instance
let _termFit = null;    // FitAddon
let _termId = null;     // server PTY session id
let _termPoll = null;   // polling interval
let _termInited = false;
let _termResizeTimer = null;

// Make the terminal fill the viewport: body is normal flow (not a full-height
// flex column), so terminal-view's flex:1 does nothing on its own — pin an
// explicit height from its top to the bottom of the window, then refit xterm.
function _termLayout() {
  if (activeView !== 'terminal') return;
  const view = document.getElementById('terminal-view');
  if (!view) return;
  const top = view.getBoundingClientRect().top;
  view.style.height = Math.max(240, Math.round(window.innerHeight - top - 12)) + 'px';
  if (_term && _termFit) { try { _termFit.fit(); } catch (e) {} }
}

function _termStatus(state, text) {
  const pill = document.getElementById('term-status');
  const t = document.getElementById('term-status-text');
  if (t) t.textContent = text;
  if (pill) { pill.classList.remove('connected', 'error'); if (state) pill.classList.add(state); }
}

function _termClear() { if (_term) { _term.clear(); _term.focus(); } }

function _termInit() {
  if (_termInited) {
    _termLayout();
    if (_term && _termFit) setTimeout(() => { try { _termFit.fit(); } catch (e) {} }, 60);
    return;
  }
  _termInited = true;
  // Fill the viewport now, and keep xterm fit to the container on any size
  // change (tab switch, window resize, toolbar wrap) — the ResizeObserver is the
  // robust catch-all the old window-resize-only listener missed.
  requestAnimationFrame(_termLayout);
  const _tc = document.getElementById('term-container');
  if (_tc && window.ResizeObserver) {
    let _roTimer;
    new ResizeObserver(() => {
      clearTimeout(_roTimer);
      _roTimer = setTimeout(() => {
        if (_term && _termFit && activeView === 'terminal') { try { _termFit.fit(); } catch (e) {} }
      }, 100);
    }).observe(_tc);
  }
  // Load saved font size
  const savedSize = localStorage.getItem('amux_term_fontsize');
  if (savedSize) document.getElementById('term-fontsize').value = savedSize;
  // Set default host to amux connection hostname (for SSH)
  const hostInput = document.getElementById('term-host');
  const h = location.hostname;
  if (h && h !== 'localhost' && h !== '127.0.0.1') {
    hostInput.placeholder = h;
    hostInput.value = h;
  }
  // Load saved hosts into dropdown
  const savedHosts = JSON.parse(localStorage.getItem('amux_term_hosts') || '[]');
  const sel = document.getElementById('term-profile');
  savedHosts.forEach(h => {
    const opt = document.createElement('option');
    opt.value = h; opt.textContent = h;
    sel.appendChild(opt);
  });
}

async function _termConnect() {
  const hostInput = document.getElementById('term-host').value.trim();
  const profileSel = document.getElementById('term-profile');
  const host = hostInput || (profileSel.value === 'local' ? '' : profileSel.value);

  // Save to recent hosts
  if (host) {
    let hosts = JSON.parse(localStorage.getItem('amux_term_hosts') || '[]');
    hosts = hosts.filter(h => h !== host);
    hosts.unshift(host);
    hosts = hosts.slice(0, 20);
    localStorage.setItem('amux_term_hosts', JSON.stringify(hosts));
    // Add to dropdown if not there
    const sel = document.getElementById('term-profile');
    if (!Array.from(sel.options).some(o => o.value === host)) {
      const opt = document.createElement('option');
      opt.value = host; opt.textContent = host;
      sel.appendChild(opt);
    }
  }

  // Create PTY on server
  const fontSize = parseInt(document.getElementById('term-fontsize').value) || 14;
  const container = document.getElementById('term-container');

  // Remove placeholder
  const ph = document.getElementById('term-placeholder');
  if (ph) ph.remove();

  // Destroy old terminal if exists
  if (_term) {
    _term.dispose();
    _term = null;
  }
  if (_termPoll) { clearTimeout(_termPoll); _termPoll = null; }
  if (_termId) {
    fetch(API + '/api/terminal/' + _termId, { method: 'DELETE' }).catch(() => {});
    _termId = null;
  }

  // Create xterm.js instance
  _term = new Terminal({
    cursorBlink: true,
    cursorStyle: 'block',
    fontSize: fontSize,
    fontFamily: "'JetBrains Mono', 'Menlo', 'Monaco', 'Courier New', monospace",
    theme: {
      background: '#0d1117',
      foreground: '#c9d1d9',
      cursor: '#58a6ff',
      cursorAccent: '#0d1117',
      selectionBackground: 'rgba(56,139,253,0.3)',
      black: '#484f58',   red: '#ff7b72',    green: '#3fb950',  yellow: '#d29922',
      blue: '#58a6ff',    magenta: '#bc8cff', cyan: '#39d353',   white: '#b1bac4',
      brightBlack: '#6e7681', brightRed: '#ffa198', brightGreen: '#56d364', brightYellow: '#e3b341',
      brightBlue: '#79c0ff',  brightMagenta: '#d2a8ff', brightCyan: '#56d364', brightWhite: '#f0f6fc',
    },
    scrollback: 10000,
    allowProposedApi: true,
    macOptionIsMeta: true,
    macOptionClickForcesSelection: true,
    rightClickSelectsWord: true,
    allowTransparency: false,
  });

  _termFit = new FitAddon.FitAddon();
  _term.loadAddon(_termFit);
  _term.loadAddon(new WebLinksAddon.WebLinksAddon());

  _term.open(container);
  _termLayout();   // pin container to full viewport height BEFORE measuring cols/rows
  _termFit.fit();

  const dims = _termFit.proposeDimensions();
  const cols = dims ? dims.cols : 120;
  const rows = dims ? dims.rows : 40;

  _termStatus('', host ? 'Connecting to ' + host + '…' : 'Starting local shell…');

  try {
    const r = await fetch(API + '/api/terminal/create', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ host, cols, rows }),
    });
    const data = await r.json();
    if (data.error) {
      _term.writeln('\r\n\x1b[31mError: ' + data.error + '\x1b[0m');
      _termStatus('error', 'Error');
      return;
    }
    _termId = data.id;
  } catch (e) {
    _term.writeln('\r\n\x1b[31mFailed to create terminal: ' + e.message + '\x1b[0m');
    _termStatus('error', 'Error');
    return;
  }

  _termStatus('connected', host ? host : 'Local shell');
  document.getElementById('term-connect-btn').style.display = 'none';
  document.getElementById('term-disconnect-btn').style.display = '';

  // Send keyboard input to server
  _term.onData(data => {
    if (!_termId) return;
    fetch(API + '/api/terminal/' + _termId + '/input', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ data: btoa(unescape(encodeURIComponent(data))) }),
      // /api/terminal is outbox-skipped: a failure here means typed keys were
      // dropped into a live-looking terminal — never swallow that.
    }).catch(() => showToast('Terminal input failed'));
  });

  // Handle resize — debounce to avoid flooding the server during drag/animation
  _term.onResize(({ cols, rows }) => {
    if (!_termId) return;
    clearTimeout(_termResizeTimer);
    _termResizeTimer = setTimeout(() => {
      fetch(API + '/api/terminal/' + _termId + '/resize', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cols, rows }),
      }).catch(() => {});
    }, 150);
  });

  // Stream output via long-poll: each request blocks server-side until output
  // is available (up to 25s), then we re-request immediately — near-real-time
  // with no fixed polling lag. Only back off on transient errors.
  async function _termTick() {
    if (!_termPoll || !_termId) return;
    try {
      const r = await fetch(API + '/api/terminal/' + _termId + '/output?wait=25');
      const d = await r.json();
      if (d.data) {
        const bytes = Uint8Array.from(atob(d.data), c => c.charCodeAt(0));
        _term.write(bytes);
      }
      if (!d.alive) {
        _term.writeln('\r\n\x1b[33m[Process exited]\x1b[0m');
        _termStatus('', 'Disconnected');
        _termPoll = null;
        document.getElementById('term-connect-btn').style.display = '';
        document.getElementById('term-disconnect-btn').style.display = 'none';
        return;
      }
    } catch (e) {
      if (_termPoll) _termPoll = setTimeout(_termTick, 500);  // transient — back off
      return;
    }
    if (_termPoll) _termPoll = setTimeout(_termTick, 0);  // re-poll immediately
  }
  _termPoll = setTimeout(_termTick, 0);

  _term.focus();
}

function _termDisconnect() {
  if (_termPoll) { clearTimeout(_termPoll); _termPoll = null; }
  if (_termId) {
    fetch(API + '/api/terminal/' + _termId, { method: 'DELETE' })
      .catch(() => showToast('Disconnected locally, but the server shell may still be running'));
    _termId = null;
  }
  if (_term) {
    _term.writeln('\r\n\x1b[33m[Disconnected]\x1b[0m');
  }
  _termStatus('', 'Disconnected');
  document.getElementById('term-connect-btn').style.display = '';
  document.getElementById('term-disconnect-btn').style.display = 'none';
}

function _termSetFontSize(size) {
  localStorage.setItem('amux_term_fontsize', size);
  if (_term) {
    _term.options.fontSize = parseInt(size);
    if (_termFit) _termFit.fit();
  }
}

// Recompute the terminal's viewport-fill height (and refit xterm) on resize.
{ let _wrt;
window.addEventListener('resize', () => {
  clearTimeout(_wrt);
  _wrt = setTimeout(() => { if (activeView === 'terminal') _termLayout(); }, 100);
}); }

// ── Messages tab (global send history across all sessions) ──────────────────
let _msgsData = [];
let _msgsAllSessions = null;   // store-derived dropdown options (AMUX-2548); null = not fetched
let _msgsDeepQ = '';   // non-empty = server-side full-history search is active
let _msgsGroup = '';   // non-empty = scoped to a group (arrived from its scope panel)
function _msgsRenderGroupChip() {
  let el = document.getElementById('msgs-group-chip');
  if (!el) {
    const host = document.getElementById('msgs-session-filter');
    if (!host || !host.parentElement) return;
    el = document.createElement('span');
    el.id = 'msgs-group-chip';
    host.parentElement.insertBefore(el, host.nextSibling);
  }
  // The filter must be VISIBLE and removable — a silent pre-filter is how a
  // scoped page gets read as the whole corpus (the tag-scoped board incident).
  el.innerHTML = _msgsGroup
    ? '<span class="msg-tag" style="background:rgba(88,166,255,0.14);color:var(--accent);cursor:pointer;"'
      + ' title="Clear group filter" onclick="_msgsGroup=\'\';_msgsRenderGroupChip();_messagesLoad(true);">group: '
      + esc(_msgsGroup) + ' \u2715</span>'
    : '';
}
let _msgsOffset = 0;
const _MSGS_PAGE = 200;
let _msgsDone = false;

async function _messagesLoad(reset, presetSession) {
  if (reset !== false) { _msgsData = []; _msgsOffset = 0; _msgsDone = false; }
  try {
    // Kind-scoped at the SERVER. Filtering a mixed page client-side is what
    // showed 48 human messages out of 6547 — the human rows never made it into
    // the window. ?counts=1 supplies true per-kind totals for the chips, which
    // a tally of the fetched page cannot (every unselected chip would read 0).
    const _sf = document.getElementById('msgs-session-filter')?.value || '';
    let _u = API + '/api/history?limit=' + _MSGS_PAGE + '&offset=' + _msgsOffset;
    if (_msgsKind !== 'all') _u += '&kind=' + encodeURIComponent(_msgsKind);
    if (_sf) _u += '&session=' + encodeURIComponent(_sf);
    // Deep search (Enter in the box): the SERVER scans all history, so hits
    // older than the loaded page exist. Typing still filters the loaded page
    // instantly — two speeds, one box (AMUX-2426).
    if (_msgsDeepQ) _u += '&q=' + encodeURIComponent(_msgsDeepQ);
    if (_msgsGroup) _u += '&group=' + encodeURIComponent(_msgsGroup);
    const r = await fetch(_u);
    const rows = await r.json();
    fetch(API + '/api/history?counts=1' + (_sf ? '&session=' + encodeURIComponent(_sf) : ''))
      .then(x => x.json()).then(c => { _msgsCounts = c; _msgsRenderChips(); }).catch(() => {});
    if (!Array.isArray(rows)) return;
    _msgsData = _msgsData.concat(rows.map(_msgNorm));
    _msgsOffset += rows.length;
    _msgsDone = rows.length < _MSGS_PAGE;
    // Session filter options — FROM THE STORE, not the loaded page (AMUX-2548).
    // Deriving names from _msgsData meant the dropdown listed only workers with
    // a message in the newest 200 rows — ~7 hours of a 46-lane fleet — so 90 of
    // 115 workers with history were absent from it entirely. A message to any
    // of them was unfindable from the global view while that worker's peek
    // showed it fine: the same store, two windows, and the view's own control
    // silently limited to the window. The dropdown is the SCOPE control; it
    // must enumerate the store's scopes, which only the server can see.
    const sel = document.getElementById('msgs-session-filter');
    if (sel) {
      const cur = (presetSession != null && presetSession !== '') ? presetSession : sel.value;
      let names = _msgsAllSessions;
      if (!names) {
        try {
          const sr = await fetch(API + '/api/history?sessions=1');
          if (sr.ok) names = _msgsAllSessions = (await sr.json()).map(x => x.session);
        } catch (e) {}
      }
      // Fallback keeps the old (window-derived) behaviour if the fetch failed,
      // which can only ever show a subset — never nothing.
      if (!names) names = [...new Set(_msgsData.map(m => m.session).filter(Boolean))].sort();
      sel.innerHTML = '<option value="">All workers</option>' +
        names.map(n => '<option value="' + esc(n) + '"' + (n === cur ? ' selected' : '') + '>' + esc(n) + '</option>').join('');
      if (cur && !names.includes(cur)) sel.value = '';
    }
    _messagesRender();
  } catch (e) {
    const list = document.getElementById('msgs-list');
    if (list && !_msgsData.length) list.innerHTML = '<div style="color:var(--red);font-size:0.85rem;padding:20px;text-align:center;">Failed to load messages</div>';
  }
}

function _msgsFmtTs(ts) {
  if (!ts) return '';
  const d = new Date(ts);
  const sameYear = d.getFullYear() === new Date().getFullYear();
  return d.toLocaleString([], { month: 'short', day: 'numeric', ...(sameYear ? {} : { year: 'numeric' }), hour: 'numeric', minute: '2-digit' });
}

// Open the session's peek and scroll to where the message was sent: prefill the
// peek search with a short snippet (the terminal hard-wraps long lines, so only
// a SHORT prefix can match the rendered pane) — same jump flow as card log-hits.
function _msgLocate(session, encText) {
  if (!session) { showToast('No worker recorded for this message'); return; }
  const text = decodeURIComponent(encText);
  // FIRST NON-EMPTY line, not line[0]. A message that opens with a blank line
  // yielded an empty query, and openPeek treats an empty query as "no search" —
  // so Find silently did nothing and looked like the message was not in the
  // log. A locate that no-ops is worse than one that says it found nothing.
  const line = text.split('\n').map(l => l.trim()).find(l => l.length > 0) || '';
  const snippet = line.slice(0, 32);
  if (!snippet) { showToast('Nothing searchable in this message'); return; }
  if (typeof closeCmdHistoryModal === 'function') closeCmdHistoryModal();
  openPeek(session, { query: snippet });
}

// Same three kinds, same order, same chip class as the peek Messages tab and
// the history modal — one definition so the three surfaces cannot drift.
// Defaults to human for the same reason: on a busy fleet, inter-session and
// scheduler traffic outnumber what you typed by roughly 3:1 and bury it.
// 'all', matching the session peek's default (AMUX-2548). This was 'human',
// which made the two views disagree BY DEFAULT: a message sent by a session,
// a schedule or the harness existed in the store, showed in the worker's peek
// Messages tab, and was silently absent from the global tab — including from
// its Enter deep-search, which inherits the kind filter. Ethan: "make sure the
// message tab contents for global amux is the same tab contents as session
// message, for example I cant locate a message that was sent." The kind chips
// still narrow; they just no longer narrow SILENTLY as the starting state.
// Default HUMAN, not all (Ethan, 2026-08-15). The other two message views
// already opened on human — _cmdHistKind and _peekMsgFilter are both 'human' —
// so this was the odd one out rather than a considered difference.
// Safe with the chips because the counts are fetched SEPARATELY and unfiltered
// (?counts=1 with no kind param), so every chip keeps its true total instead of
// reading 0 for the unselected kinds — the failure the comment at the fetch site
// already warns about. Verified live: counts=1 and counts=1&kind=human return
// identical totals (all 8555, human 3094, session 3941, schedule 607, amux 913).
// It also makes the first load SMALLER: kind is applied at the server, so the
// opening page is 3094 candidates instead of 8555, which matters on mobile.
let _msgsKind = 'human';        // all | human | session | schedule
let _msgsCounts = null;         // true per-kind totals from the server
function _msgsSetKind(k) {
  _msgsKind = k;
  _messagesLoad(true, document.getElementById('msgs-session-filter')?.value || '');
}
function _msgsRenderChips() {
  const bar = document.getElementById('msgs-kind-filter');
  if (!bar) return;
  const c = _msgsCounts || { all: _msgsData.length, human: 0, session: 0, schedule: 0 };
  if (!_msgsCounts) _msgsData.forEach(m => { c[_msgKind(m)] = (c[_msgKind(m)] || 0) + 1; });
  const chips = [['all', 'All']].concat(_MSG_KIND_ORDER.map(k => [k, _MSG_KIND[k].label]));
  const refresh = '<button class="btn" onclick="_msgsAllSessions=null;_messagesLoad(true)" title="Refresh" '
    + 'style="font-size:0.78rem;padding:5px 10px;min-height:44px;flex:0 0 auto;">\u21BB</button>';
  bar.innerHTML = refresh + chips.map(([k, lbl]) => {
    const on = _msgsKind === k;
    const km = _MSG_KIND[k];
    const col = km ? km.color : 'var(--accent)';
    return '<button class="msg-kind-chip" onclick="_msgsSetKind(\'' + k + '\')" style="'
      + 'border:1px solid ' + (on ? col : 'var(--border)') + ';'
      + 'background:' + (on ? (km ? km.bg : 'rgba(88,166,255,0.14)') : 'transparent') + ';'
      + 'color:' + (on ? col : 'var(--dim)') + ';">' + lbl + ' ' + (c[k] || 0) + '</button>';
  }).join('');
}

// ── Message multi-select + resend (AMUX-2318) ───────────────────────────────
// A resend is not free: each one wakes a session and costs it a turn. So the
// blast radius is shown BEFORE the click (how many messages, to how many
// distinct lanes, named) rather than discovered afterwards.
let _msgSel = new Set();
// ONE key for every message surface. It used to read m.ts, which only exists on
// the raw server rows the Messages tab keeps — the command-history and peek
// surfaces rename ts -> time, so every row there keyed as "<session>|0" and a
// single checkbox selected the whole session (AMUX-2334). Accept both.
const _msgKey = (m) => (typeof m === 'string' ? '|' + m.slice(0, 60)
  : (m.session || '') + '|' + (m.time || m.ts || 0) + '|' + String(m.text || '').slice(0, 40));

function _msgSelToggle(key, ev) {
  if (ev) { ev.stopPropagation(); }
  if (_msgSel.has(key)) _msgSel.delete(key); else _msgSel.add(key);
  _messagesRender();
}
function _msgSelAll(visibleKeys) { visibleKeys.forEach(k => _msgSel.add(k)); _messagesRender(); }
function _msgSelNone() { _msgSel.clear(); _messagesRender(); }

// The per-row overflow menu. One open at a time; click anywhere closes it.
function _msgMenu(btn, ev) {
  if (ev) ev.stopPropagation();
  const open = btn.parentElement.querySelector('.msg-menu.open');
  document.querySelectorAll('.msg-menu.open').forEach(m => m.classList.remove('open'));
  if (!open) btn.parentElement.querySelector('.msg-menu').classList.add('open');
}
document.addEventListener('click', () => {
  document.querySelectorAll('.msg-menu.open').forEach(m => m.classList.remove('open'));
});

// Shared core so the global tab and the peek panel cannot drift apart. They
// have DIFFERENT data shapes (_msgsData rows carry .session; peek items are
// strings or {text,time} belonging to peekSession), so each surface builds the
// {session,text} list and this does the rest.
async function _resendRows(rows) {
  rows = (rows || []).filter(r => r && r.session && r.text);
  if (!rows.length) { showToast('Nothing to resend (messages with no target worker are skipped)'); return; }
  const lanes = [...new Set(rows.map(r => r.session))];
  const preview = rows.slice(0, 3).map(r => '  \u2022 ' + r.text.slice(0, 60)).join('\n');
  const ok = await showConfirm(
    'Resend ' + rows.length + ' message' + (rows.length === 1 ? '' : 's') +
    ' to ' + lanes.length + ' worker' + (lanes.length === 1 ? '' : 's') + '?\n\n' +
    lanes.join(', ') + '\n\n' + preview + (rows.length > 3 ? '\n  \u2026and ' + (rows.length - 3) + ' more' : '') +
    '\n\nEach resend wakes its worker and costs it a turn.',
    'Resend', false);
  if (!ok) return false;
  let sent = 0, failed = 0;
  for (const r of rows) {
    try {
      const resp = await fetch(API + '/api/sessions/' + encodeURIComponent(r.session) + '/send', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: r.text }),
      });
      if (resp.ok) sent++; else failed++;
    } catch (e) { failed++; }
  }
  showToast('Resent ' + sent + (failed ? ' \u00b7 ' + failed + ' failed' : '') + ' to ' + lanes.length + ' worker(s)');
  return true;
}

// ── Peek Messages panel selection (AMUX-2319) ───────────────────────────────
// Separate set from _msgSel: different surface, different shape, and a stale
// cross-surface selection would resend the wrong things.
let _pmSel = new Set();
const _pmKey = (e) => {
  const t = typeof e === 'string' ? e : (e.text || '');
  return ((typeof e === 'string' ? '' : (e.time || '')) + '|' + t.slice(0, 60));
};
function _pmSelToggle(key, ev) {
  if (ev) ev.stopPropagation();
  if (_pmSel.has(key)) _pmSel.delete(key); else _pmSel.add(key);
  _peekMessagesRender();
}
function _pmSelAll(keys) { keys.forEach(k => _pmSel.add(k)); _peekMessagesRender(); }
function _pmSelNone() { _pmSel.clear(); _peekMessagesRender(); }
async function _pmResend(keys) {
  const items = _peekMessagesFor().filter(e => keys.includes(_pmKey(e)));
  const rows = items.map(e => ({ session: peekSession,
                                 text: typeof e === 'string' ? e : (e.text || '') }));
  if (await _resendRows(rows)) { _pmSel.clear(); _peekMessagesRender(); }
}

async function _msgResend(keys) {
  const rows = _msgsData.filter(m => keys.includes(_msgKey(m)) && (m.session || ''))
                        .map(m => ({ session: m.session, text: m.text || '' }));
  if (await _resendRows(rows)) { _msgSel.clear(); _messagesRender(); }
}

function _messagesRender() {
  const list = document.getElementById('msgs-list');
  if (!list) return;
  const q = (document.getElementById('msgs-search')?.value || '').trim().toLowerCase();
  const sessF = document.getElementById('msgs-session-filter')?.value || '';
  _msgsRenderChips();
  let rows = _msgsData;
  if (sessF) rows = rows.filter(m => (m.session || '') === sessF);
  // No client-side kind filter: the fetch is already kind-scoped, so the page
  // is 500 rows OF THAT KIND rather than 500 mixed rows filtered down to a
  // handful — the same crowding that showed 48 human messages out of 6547.
  if (_msgsKind !== 'all') rows = rows.filter(m => _msgKind(m) === _msgsKind);
  if (q) rows = rows.filter(m => (m.text || '').toLowerCase().includes(q) || (m.session || '').toLowerCase().includes(q));
  // Selection toolbar (AMUX-2318). Only rendered when something is selected,
  // so the default view is unchanged - a persistent bar for a rare action is
  // clutter, and this list is read far more often than it is acted on.
  const _visKeys = rows.map(_msgKey);
  const _selVis = _visKeys.filter(k => _msgSel.has(k));
  const bar = document.getElementById('msgs-selbar');
  if (bar) {
    if (_selVis.length) {
      const lanes = [...new Set(rows.filter(m => _msgSel.has(_msgKey(m)) && m.session).map(m => m.session))];
      bar.innerHTML =
        '<span class="msgs-selcount">' + _selVis.length + ' selected</span>' +
        '<span class="msgs-sellanes">' + lanes.length + ' worker' + (lanes.length === 1 ? '' : 's') + ': ' + esc(lanes.slice(0,3).join(', ')) + (lanes.length > 3 ? ' +' + (lanes.length - 3) : '') + '</span>' +
        '<button class="btn primary" onclick="_msgResend(' + JSON.stringify(_selVis).replace(/"/g, '&quot;') + ')">Resend ' + _selVis.length + '</button>' +
        '<button class="btn" onclick="_msgSelAll(' + JSON.stringify(_visKeys).replace(/"/g, '&quot;') + ')">Select all ' + _visKeys.length + '</button>' +
        '<button class="btn" onclick="_msgSelNone()">Clear</button>';
      bar.style.display = 'flex';
    } else {
      bar.innerHTML = '';
      bar.style.display = 'none';
    }
  }
  const count = document.getElementById('msgs-count');
  if (count) count.textContent = rows.length + ' message' + (rows.length === 1 ? '' : 's') + (_msgsDone ? '' : ' (more available)');
  const more = document.getElementById('msgs-more-btn');
  if (more) more.style.display = _msgsDone ? 'none' : '';
  if (!rows.length) {
    const kl = (_MSG_KIND[_msgsKind] || {}).label;
    list.innerHTML = '<div style="color:var(--dim);font-size:0.85rem;padding:24px;text-align:center;">'
      + (q ? (_msgsDeepQ === q
               ? 'No matches anywhere in history.'
               // The instant filter searches ONLY the loaded page. A bare "No
               // matches." here is how a message that provably exists reads as
               // absent (AMUX-2548) — the reader cannot tell a page-local miss
               // from a store-wide one, and that difference is the whole
               // answer. Name the denominator and offer the real search.
               : 'No matches in the ' + _msgsData.length + ' loaded messages. '
                 + '<a href="#" onclick="event.preventDefault();_msgsDeepQ=document.getElementById(\'msgs-search\').value.trim();_messagesLoad(true);" '
                 + 'style="color:var(--accent);">Search all history</a> (or press Enter).')
           : kl ? 'No ' + kl.toLowerCase() + ' messages' + (sessF ? ' for ' + esc(sessF) : '') + '.'
                : (sessF ? 'No messages for ' + esc(sessF) + '.' : 'No messages yet.')) + '</div>';
    return;
  }
  // Burst grouping + message→card join (AMUX-2143): you fire clusters
  // across sessions and lose the thread. A divider marks each burst (>90s
  // gap), and a human row whose capture stamped card_id gets a live chip:
  // card id + status now + last attached commit, click-through to the card.
  const _cardById = {};
  (typeof boardItems !== 'undefined' ? boardItems : []).forEach(c => { _cardById[c.id] = c; });
  const _stColor = st => st === 'verified' ? 'var(--green)' : st === 'done' ? '#3fb950'
    : st === 'doing' ? '#d29922' : st === 'review' ? '#bc8cff'
    : st === 'discarded' ? 'var(--dim)' : 'var(--accent)';
  let _prevTs = null;
  let _prevDay = null;
  // Third copy of the same row markup, now the shared renderer. The burst
  // separator is genuinely this surface's own (it groups a human's rapid
  // sends), so it stays here and wraps the shared row. The DATE-GROUP header
  // (sticky, one per calendar day) is the review-by-calendar pattern (Ethan):
  // rows are newest-first, so each header labels the day of the messages below
  // it; `data-day` lets the date picker scroll straight to a day.
  list.innerHTML = rows.map(m => {
    const _ts = m.time || m.ts;
    let dateHdr = '';
    const _day = _msgDayKey(_ts);
    if (_day !== _prevDay) {
      dateHdr = '<div class="msgs-date-header" data-day="' + esc(_day) + '">' + esc(_msgDayLabel(_ts)) + '</div>';
      _prevDay = _day;
    }
    let burst = '';
    if (_msgsKind === 'human' && _prevTs !== null && (_prevTs - _ts) > 90000) {
      burst = '<div style="font-size:0.68rem;color:var(--dim);padding:8px 4px 2px;border-top:1px dashed var(--border);margin-top:4px;">' + _msgsFmtTs(_ts) + '</div>';
    }
    _prevTs = _ts;
    return dateHdr + burst + _cmdHistItemHTML(m, _msgCtxMessages());
  }).join('');
}

// Calendar/time review helpers for the Messages timeline (Ethan 2026-08-13).
function _msgDayKey(ts) {
  if (!ts) return 'unknown';
  const d = new Date(ts);
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}
function _msgDayLabel(ts) {
  if (!ts) return 'Unknown date';
  const d = new Date(ts), now = new Date();
  const same = (a, b) => a.toDateString() === b.toDateString();
  const yst = new Date(now); yst.setDate(now.getDate() - 1);
  if (same(d, now)) return 'Today';
  if (same(d, yst)) return 'Yesterday';
  const opts = { weekday: 'long', month: 'long', day: 'numeric' };
  if (d.getFullYear() !== now.getFullYear()) opts.year = 'numeric';
  return d.toLocaleDateString([], opts);
}
// Jump the timeline to a chosen day. Rows are newest-first and paged; if the day
// is older than what's loaded, keep loading older pages until it's in range (or
// the store is exhausted), then scroll its header into view. The date-review
// jump (Ethan): easily land on any past day without hand-scrolling.
async function _msgsJumpToDate(dateStr) {
  if (!dateStr) return;
  const target = new Date(dateStr + 'T00:00:00').getTime();  // local start-of-day, ms
  let guard = 0;
  while (!_msgsDone && guard < 80) {
    const last = _msgsData[_msgsData.length - 1];
    const oldest = last ? (last.time || last.ts) : Infinity;
    if (oldest <= target + 86400000) break;   // loaded into (or past) that day
    await _messagesLoad(false);
    guard++;
  }
  _messagesRender();
  requestAnimationFrame(() => {
    const list = document.getElementById('msgs-list');
    if (!list) return;
    const hdrs = [...list.querySelectorAll('.msgs-date-header')];  // newest first
    let hdr = hdrs.find(h => h.dataset.day === dateStr)
      || hdrs.find(h => h.dataset.day <= dateStr)  // nearest day on/before target
      || hdrs[hdrs.length - 1];
    if (hdr) {
      hdr.scrollIntoView({ behavior: 'smooth', block: 'start' });
      hdr.classList.add('msgs-date-flash');
      setTimeout(() => hdr.classList.remove('msgs-date-flash'), 1500);
    } else if (typeof showToast === 'function') {
      showToast('No messages on or before that date');
    }
  });
}

// ── Database workbench tab ──────────────────────────────────────────────────
let _dbTables = [];
let _dbTable = null;
let _dbMode = 'data';
let _dbLimit = 50, _dbOffset = 0, _dbSort = '', _dbDir = 'asc';
let _sqlSchemaLoaded = false;

function _sqlInit() { if (!_sqlSchemaLoaded) { _sqlSchemaLoaded = true; _dbLoadSchema(); } }

async function _dbLoadSchema() {
  const side = document.getElementById('db-tables');
  if (side) side.innerHTML = '<div style="color:var(--dim);font-size:0.74rem;padding:6px;">Loading…</div>';
  try {
    const d = await fetch(API + '/api/sql/schema').then(r => r.json());
    if (d.error) { if (side) side.innerHTML = '<div style="color:#f85149;font-size:0.74rem;padding:6px;">' + esc(d.error) + '</div>'; return; }
    _dbTables = d.tables || [];
    const f = document.getElementById('db-filter');
    _dbRenderSidebar(f ? f.value : '');
    if (_dbTable) _dbRenderStructure();
  } catch (e) { if (side) side.innerHTML = '<div style="color:#f85149;font-size:0.74rem;padding:6px;">schema failed</div>'; }
}

function _dbFilter(q) { _dbRenderSidebar(q); }

function _dbRenderSidebar(q) {
  const el = document.getElementById('db-tables');
  if (!el) return;
  const ql = (q || '').toLowerCase();
  const list = _dbTables.filter(t => !ql || t.name.toLowerCase().includes(ql));
  el.innerHTML = '<h4>Tables (' + list.length + ')</h4>' + list.map(t =>
    '<div class="db-tbl' + (t.writable ? ' wb' : '') + (t.name === _dbTable ? ' active' : '') + '" ' +
      'title="' + esc(t.columns.map(c => c.name + ' ' + c.type).join(', ')) + '" onclick="_dbSelectTable(\'' + esc(t.name) + '\')">' +
      '<span class="n">' + esc(t.name) + '</span><span class="c">' + (t.rows == null ? '' : t.rows) + '</span></div>').join('');
}

function _dbSelectTable(name) {
  _dbTable = name; _dbOffset = 0; _dbSort = ''; _dbDir = 'asc';
  const f = document.getElementById('db-filter');
  _dbRenderSidebar(f ? f.value : '');
  const t = _dbTables.find(x => x.name === name);
  document.getElementById('db-title').innerHTML = esc(name) +
    '<span class="sub">' + (t && t.rows != null ? t.rows + ' rows · ' : '') + (t && t.writable ? 'writable' : 'read-only') + '</span>';
  if (_dbMode === 'query') _dbSetMode('data');
  _dbLoadData();
  _dbRenderStructure();
}

function _dbSetMode(mode) {
  _dbMode = mode;
  ['data', 'structure', 'query'].forEach(m => {
    const pane = document.getElementById('db-pane-' + m);
    if (pane) pane.style.display = m === mode ? '' : 'none';
    document.getElementById('db-mode-' + m).classList.toggle('active', m === mode);
  });
  if (mode === 'query') {
    const ta = document.getElementById('sql-editor');
    if (ta && !ta.value.trim() && _dbTable) ta.value = 'SELECT * FROM ' + _dbTable + ' LIMIT 100;';
    setTimeout(() => ta && ta.focus(), 30);
  }
}

async function _dbLoadData() {
  if (!_dbTable) return;
  const grid = document.getElementById('db-grid');
  const status = document.getElementById('sql-status');
  status.classList.remove('err');
  try {
    const q = '?table=' + encodeURIComponent(_dbTable) + '&limit=' + _dbLimit + '&offset=' + _dbOffset +
      (_dbSort ? '&sort=' + encodeURIComponent(_dbSort) + '&dir=' + _dbDir : '');
    const d = await fetch(API + '/api/sql/rows' + q).then(r => r.json());
    if (d.error) { status.classList.add('err'); status.textContent = d.error; grid.innerHTML = '<div style="padding:16px;color:#f85149;">' + esc(d.error) + '</div>'; return; }
    _dbRenderGrid(grid, d.columns, d.rows, true);
    _dbRenderPager(d);
    const t = _dbTables.find(x => x.name === _dbTable);
    status.textContent = t && t.writable ? 'Read/write · wb_*' : 'Read-only';
  } catch (e) { status.classList.add('err'); status.textContent = 'load failed'; }
}

function _dbRenderPager(d) {
  const p = document.getElementById('db-pager');
  if (!p) return;
  const from = d.total === 0 ? 0 : d.offset + 1, to = Math.min(d.offset + d.limit, d.total);
  p.innerHTML =
    '<select onchange="_dbLimit=parseInt(this.value);_dbOffset=0;_dbLoadData()">' +
      [25, 50, 100, 200].map(n => '<option value="' + n + '"' + (n === _dbLimit ? ' selected' : '') + '>' + n + '/pg</option>').join('') + '</select>' +
    '<button class="btn" ' + (d.offset <= 0 ? 'disabled' : '') + ' onclick="_dbOffset=Math.max(0,_dbOffset-_dbLimit);_dbLoadData()">&#8249;</button>' +
    '<span>' + from + '&ndash;' + to + ' of ' + d.total + '</span>' +
    '<button class="btn" ' + (to >= d.total ? 'disabled' : '') + ' onclick="_dbOffset+=_dbLimit;_dbLoadData()">&#8250;</button>';
}

function _dbSortBy(col) {
  if (_dbSort === col) _dbDir = _dbDir === 'asc' ? 'desc' : 'asc';
  else { _dbSort = col; _dbDir = 'asc'; }
  _dbOffset = 0; _dbLoadData();
}

function _dbRenderGrid(grid, columns, rows, sortable) {
  if (!columns || !columns.length) { grid.innerHTML = '<div style="padding:16px;color:var(--dim);font-size:0.82rem;">(statement ran — no result set)</div>'; return; }
  if (!rows.length) { grid.innerHTML = '<div style="padding:16px;color:var(--dim);font-size:0.82rem;">0 rows.</div>'; return; }
  const th = columns.map(c => {
    const arrow = sortable && _dbSort === c ? (_dbDir === 'asc' ? ' ▲' : ' ▼') : '';
    return '<th' + (sortable ? ' class="sortable" onclick="_dbSortBy(\'' + esc(c) + '\')"' : '') + '>' + esc(c) + arrow + '</th>';
  }).join('');
  const body = rows.map(r => '<tr>' + r.map(v => '<td>' + (v === null ? '<span class="sql-null">NULL</span>' : esc(String(v))) + '</td>').join('') + '</tr>').join('');
  grid.innerHTML = '<table class="sqlr"><thead><tr>' + th + '</tr></thead><tbody>' + body + '</tbody></table>';
}

function _dbRenderStructure() {
  const el = document.getElementById('db-structure');
  if (!el || !_dbTable) return;
  const t = _dbTables.find(x => x.name === _dbTable);
  if (!t) return;
  const rows = t.columns.map(c => '<tr>' +
    '<td>' + esc(c.name) + '</td><td>' + esc(c.type || '') + '</td>' +
    '<td>' + (c.notnull ? 'NOT NULL' : '') + '</td><td>' + (c.pk ? 'PK' : '') + '</td>' +
    '<td>' + (c.dflt == null ? '' : esc(String(c.dflt))) + '</td></tr>').join('');
  el.innerHTML = '<table class="sqlr"><thead><tr><th>Column</th><th>Type</th><th>Null</th><th>Key</th><th>Default</th></tr></thead><tbody>' + rows + '</tbody></table>';
}

// ── Query pane ──
function _sqlWriteToggle() {
  const on = document.getElementById('sql-write').checked;
  const s = document.getElementById('sql-status');
  if (s && !s.classList.contains('err')) s.textContent = on ? 'Read/write · wb_*' : 'Read-only';
}
async function _sqlRun() {
  const sql = document.getElementById('sql-editor').value.trim();
  if (!sql) return;
  const write = document.getElementById('sql-write').checked;
  const status = document.getElementById('sql-status');
  const results = document.getElementById('sql-results');
  status.classList.remove('err'); status.textContent = 'Running…';
  try {
    const d = await fetch(API + '/api/sql', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sql, write }),
    }).then(r => r.json());
    if (d.error) {
      status.classList.add('err'); status.textContent = d.error;
      results.innerHTML = '<div style="padding:16px;color:#f85149;font-size:0.82rem;font-family:var(--mono);white-space:pre-wrap;">' + esc(d.error) + '</div>';
      return;
    }
    if (d.write) { status.textContent = d.message + ' · ' + d.ms + 'ms'; _dbLoadSchema(); return; }
    _dbRenderGrid(results, d.columns, d.rows, false);
    status.textContent = d.rowcount + (d.truncated ? '+ (capped)' : '') + ' row' + (d.rowcount === 1 ? '' : 's') + ' · ' + d.ms + 'ms';
  } catch (e) { status.classList.add('err'); status.textContent = 'request failed'; }
}

// ── Notes tab ─────────────────────────────────────────────────────────────────







// Tap-to-edit: clicking anywhere in the rendered preview switches to edit mode
// (Obsidian/Bear-style — no explicit "Edit" button needed)

// Swipe-from-left-edge to open the notes sidebar on mobile (Bear/Apple Notes pattern)

// ── Teleprompter ──
let _tp = { running: false, y: 0, wpm: 150, size: 48, mirror: false, lastT: 0, raf: null, toolbarTimer: null };

function _filesOpenTeleprompter() {
  // Render currently-open markdown file content as the teleprompter script
  if (!_fileData || !_fileData.content) return;
  const overlay = document.getElementById('teleprompter-overlay');
  const content = document.getElementById('tp-content');
  content.innerHTML = _tpRenderMarkdown(_fileData.content);
  // Restore saved settings
  try {
    const saved = JSON.parse(localStorage.getItem('amux_tp_settings') || '{}');
    _tp.wpm = saved.wpm || 150;
    _tp.size = saved.size || 48;
    _tp.mirror = !!saved.mirror;
  } catch(e) {}
  document.getElementById('tp-wpm').value = _tp.wpm;
  document.getElementById('tp-wpm-val').textContent = _tp.wpm;
  document.getElementById('tp-size').value = _tp.size;
  content.style.fontSize = _tp.size + 'px';
  _tp.y = 0;
  content.style.transform = 'translate(-50%, 0px)' + (_tp.mirror ? ' scaleX(-1)' : '');
  _tp.running = false;
  document.getElementById('tp-play').innerHTML = '&#x25B6;';
  overlay.style.display = 'block';
  _tpShowToolbar();
  document.addEventListener('keydown', _tpKeyHandler);
  document.getElementById('tp-viewport').addEventListener('mousemove', _tpShowToolbar);
  document.getElementById('tp-viewport').addEventListener('wheel', _tpWheelScroll, { passive: false });
}

function _tpClose() {
  _tp.running = false;
  if (_tp.raf) cancelAnimationFrame(_tp.raf);
  _tp.raf = null;
  document.getElementById('teleprompter-overlay').style.display = 'none';
  document.removeEventListener('keydown', _tpKeyHandler);
  clearTimeout(_tp.toolbarTimer);
  try {
    localStorage.setItem('amux_tp_settings', JSON.stringify({ wpm: _tp.wpm, size: _tp.size, mirror: _tp.mirror }));
  } catch(e) {}
  if (document.fullscreenElement) document.exitFullscreen().catch(()=>{});
}

function _tpRenderMarkdown(text) {
  // Minimal markdown → HTML for teleprompter (headers, bold, italic, lists, paragraphs)
  const esc = (s) => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const lines = text.split('\n');
  const out = [];
  let inList = false;
  for (let raw of lines) {
    const line = raw.trimEnd();
    if (!line.trim()) { if (inList) { out.push('</ul>'); inList = false; } out.push('<br>'); continue; }
    let m;
    if ((m = line.match(/^(#{1,3})\s+(.+)$/))) {
      if (inList) { out.push('</ul>'); inList = false; }
      const lvl = m[1].length;
      out.push(`<h${lvl} style="font-size:${1.4 - (lvl-1)*0.15}em;margin:0.8em 0 0.3em;">${_tpInline(esc(m[2]))}</h${lvl}>`);
    } else if ((m = line.match(/^[-*+]\s+(.+)$/))) {
      if (!inList) { out.push('<ul style="padding-left:1.2em;margin:0.3em 0;">'); inList = true; }
      out.push('<li>' + _tpInline(esc(m[1])) + '</li>');
    } else {
      if (inList) { out.push('</ul>'); inList = false; }
      out.push('<p style="margin:0.4em 0;">' + _tpInline(esc(line)) + '</p>');
    }
  }
  if (inList) out.push('</ul>');
  return out.join('\n');
}
function _tpInline(s) {
  return s.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
          .replace(/\*(.+?)\*/g, '<em>$1</em>')
          .replace(/`([^`]+)`/g, '<code style="font-family:monospace;font-size:0.9em;opacity:0.85;">$1</code>');
}

function _tpToggle() {
  _tp.running = !_tp.running;
  document.getElementById('tp-play').innerHTML = _tp.running ? '&#x23F8;' : '&#x25B6;';
  if (_tp.running) {
    _tp.lastT = performance.now();
    _tp.raf = requestAnimationFrame(_tpTick);
  } else if (_tp.raf) {
    cancelAnimationFrame(_tp.raf);
    _tp.raf = null;
  }
}

function _tpTick(t) {
  if (!_tp.running) return;
  const dt = Math.min((t - _tp.lastT) / 1000, 0.1); // clamp to 100ms
  _tp.lastT = t;
  // WPM → pixels/sec. Assume avg 5 chars/word and font-size px ≈ line-height * 1 word per char ratio.
  // Empirically: pxPerSec ≈ (wpm / 60) * fontSize * 1.5 (line-height multiplier)
  const pxPerSec = (_tp.wpm / 60) * _tp.size * 1.5;
  _tp.y += pxPerSec * dt;
  const content = document.getElementById('tp-content');
  const viewport = document.getElementById('tp-viewport');
  if (!content || !viewport) return;
  // Stop at end
  const maxY = content.scrollHeight - viewport.clientHeight + viewport.clientHeight * 0.5;
  if (_tp.y > maxY) { _tp.y = maxY; _tp.running = false; document.getElementById('tp-play').innerHTML = '&#x25B6;'; return; }
  content.style.transform = `translate(-50%, ${-_tp.y}px)` + (_tp.mirror ? ' scaleX(-1)' : '');
  _tp.raf = requestAnimationFrame(_tpTick);
}

function _tpSetWpm(v) {
  _tp.wpm = parseInt(v);
  document.getElementById('tp-wpm-val').textContent = _tp.wpm;
}
function _tpSetSize(v) {
  _tp.size = parseInt(v);
  document.getElementById('tp-content').style.fontSize = _tp.size + 'px';
}
function _tpRestart() {
  _tp.y = 0;
  const content = document.getElementById('tp-content');
  content.style.transform = 'translate(-50%, 0px)' + (_tp.mirror ? ' scaleX(-1)' : '');
}
function _tpToggleMirror() {
  _tp.mirror = !_tp.mirror;
  const content = document.getElementById('tp-content');
  content.style.transform = `translate(-50%, ${-_tp.y}px)` + (_tp.mirror ? ' scaleX(-1)' : '');
  document.getElementById('tp-mirror-btn').style.background = _tp.mirror ? '#7c6fcd' : 'none';
}
function _tpFullscreen() {
  const el = document.getElementById('teleprompter-overlay');
  if (!document.fullscreenElement) el.requestFullscreen?.().catch(()=>{});
  else document.exitFullscreen?.();
}
function _tpWheelScroll(e) {
  e.preventDefault();
  _tp.y = Math.max(0, _tp.y + e.deltaY);
  const content = document.getElementById('tp-content');
  if (content) content.style.transform = `translate(-50%, ${-_tp.y}px)` + (_tp.mirror ? ' scaleX(-1)' : '');
}
function _tpShowToolbar() {
  const tb = document.getElementById('tp-toolbar');
  if (!tb) return;
  tb.style.opacity = '1';
  clearTimeout(_tp.toolbarTimer);
  _tp.toolbarTimer = setTimeout(() => { tb.style.opacity = '0'; }, 3000);
}
function _tpKeyHandler(e) {
  if (document.getElementById('teleprompter-overlay').style.display === 'none') return;
  if (e.key === ' ') { e.preventDefault(); _tpToggle(); _tpShowToolbar(); }
  else if (e.key === 'Escape') { _tpClose(); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); _tp.wpm = Math.min(400, _tp.wpm + 10); document.getElementById('tp-wpm').value = _tp.wpm; document.getElementById('tp-wpm-val').textContent = _tp.wpm; _tpShowToolbar(); }
  else if (e.key === 'ArrowDown') { e.preventDefault(); _tp.wpm = Math.max(60, _tp.wpm - 10); document.getElementById('tp-wpm').value = _tp.wpm; document.getElementById('tp-wpm-val').textContent = _tp.wpm; _tpShowToolbar(); }
  else if (e.key === 'ArrowLeft') { e.preventDefault(); _tp.y = Math.max(0, _tp.y - (_tp.wpm / 60) * _tp.size * 1.5 * 10); _tpTick(performance.now()); }
  else if (e.key === 'ArrowRight') { e.preventDefault(); _tp.y += (_tp.wpm / 60) * _tp.size * 1.5 * 10; _tpTick(performance.now()); }
  else if (e.key === 'f' || e.key === 'F') { _tpFullscreen(); }
  else if (e.key === 'm' || e.key === 'M') { _tpToggleMirror(); _tpShowToolbar(); }
  else if (e.key === 'r' || e.key === 'R') { _tpRestart(); _tpShowToolbar(); }
}


// ── Preview search (find-in-page for rendered notes) ──
let _previewSearchHits = [];
let _previewSearchIdx = -1;
let _previewSearchOrigHTML = '';


function _highlightTextNodes(root, regex) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode: n => {
      if (n.parentElement && (n.parentElement.tagName === 'SCRIPT' || n.parentElement.tagName === 'STYLE' || n.parentElement.tagName === 'MARK')) return NodeFilter.FILTER_REJECT;
      return regex.test(n.textContent) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    }
  });
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(node => {
    regex.lastIndex = 0;
    const frag = document.createDocumentFragment();
    let last = 0, m;
    while ((m = regex.exec(node.textContent)) !== null) {
      if (m.index > last) frag.appendChild(document.createTextNode(node.textContent.slice(last, m.index)));
      const mark = document.createElement('mark');
      mark.className = 'search-hit';
      mark.textContent = m[1];
      frag.appendChild(mark);
      last = regex.lastIndex;
    }
    if (last < node.textContent.length) frag.appendChild(document.createTextNode(node.textContent.slice(last)));
    node.parentNode.replaceChild(frag, node);
  });
}


